window.D=window.D||{};D["mb_11"]={"276":[{"s":"<b>דיני נר שהדליק עכו\"ם בשבת. ובו ה סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>עכו\"ם שהדליק את הנר בשביל ישראל <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i><i data-commentator=\"Eshel Avraham\" data-label=\"א\" data-order=\"1\"></i>אסור לכל <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>אפי' למי שלא הודלק בשבילו: <small>הגה ואין חילוק בזה בין <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>קצב לו שכר או לא קצב או שעשאו בקבלנות או בשכירות דהואיל והישראל נהנה ממלאכה עצמה בשבת אסור בכל ענין. [הגהות אשירי פ\"ק דשבת וב\"י בשם סמ\"ג וסה\"ת] </small> <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>אבל אם הדליקו לצרכו <i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>או לצורך חולה ישראל אפי' אין בו סכנה: <small>הגה או לצורך קטנים דהוא כחולה שאין בו סכנה [מרדכי פ\"ק דשבת] </small> מותר לכל ישראל להשתמש לאורו <i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>וה\"ה לעושה מדורה לצרכו או לצורך חולה <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i><i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"1\"></i>ויש אוסרים במדורה משום <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>דגזרינן שמא ירבה <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>בשבילו: <small>הגה <i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"2\"></i>מיהו אם עשה עכו\"ם בבית ישראל <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i>מדעתו אין הישראל <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i>צריך <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>לצאת אע\"פ שנהנה מנר או מן המדורה [טור]:</small>","m":["(א) שהדליק - וה\"ה לכל מלאכה שיעשה הא\"י בשבת בשביל ישראל דאסור לכל ליהנות מזה ועיין לעיל בסימן רנ\"ב ס\"ב לענין קבלנות:","(ב) אסור - מדרבנן דאם יהא מותר ליהנות יאמר לו להדליק:","(ג) אפילו וכו' - ולא דמי למי שהובא בשבילו מחוץ לתחום בשבת דמותר לאחר וכדלקמן בסימן שכ\"ה סעיף ח' דתחומין דרבנן וכן כל איסור דרבנן שעשה א\"י בשביל ישראל מותר לאחר שלא נעשה בשבילו:","(ד) בין קצב - היינו מע\"ש וקמ\"ל דלא אמרינן בעניננו א\"י אדעתא דנפשיה עביד כדי לקבל שכרו הנקצב לו וכדלעיל בסימן רנ\"ב ס\"ב לענין קבלנות:","(ה) או שעשאו וכו' - הוא פירוש למה שאמר מתחלה בין קצב ע\"ז אמר בין שהקצבה היתה בקבלנות או בשכירות וקבלנות מקרי היכא ששכרו סתם להדליק לו נר בעת שיצטרך וקצב לו מכל הדלקה דבר קצוב ושכירות מקרי כשנותן לו בכל יום כך וכך:","(ו) קטנים - היינו אם צריכים הרבה אבל בלא\"ה לא:","(ז) לכל ישראל - דלא שייך כאן גזירה שמא יאמר לו להדליק בשביל חולה שהרי מותר לומר אף לכתחלה וכדלקמן בסימן שכ\"ח סי\"ז:","(ח) להשתמש לאורו - אפילו הוא מכירו ולא חיישינן שמא ירבה בשבילו דנר לאחד נר למאה ובכ\"ז אין חילוק בין אם הא\"י הדליק הנר בביתו או בבית ישראל:","(ט) לצרכו וכו' - דמותר לכל ישראל להתחמם ואפילו הוא מכירו משום דמדורה קטנה נמי מחממת הרבה אנשים והוי כמו נר דנר לאחד נר למאה והי\"א ס\"ל דבמדורה גזרינן שמא ירבה ולא דמי לנר משום דלפי ריבוי אנשים שמסובין אצל המדורה צריך להוסיף ולהגדיל המדורה ואם הסיק הא\"י התנור לצרכו כו\"ע מודים דרשאי הישראל ליכנס לבית החורף דחימום לאחד חימום למאה והוי כמו נר דשרי:","(י) בשבילו - ואם ידוע הוא שאינו מכירו שרי לכו\"ע:","(יא) אם עשה וכו' - היינו דוקא אחר שכבר עשה הא\"י ומה יש לו לישראל לעשות לא הטריחוהו לצאת מהבית בשביל זה ויזהירנו על להבא שלא לעשות כן אבל אם נזדמן לישראל שראה בעת שהא\"י רוצה להדליק בשבילו או לעשות המדורה צריך למחות בידו אפילו אם היה זה בביתו של א\"י ג\"כ צריך למחות כיון שהנר והעצים של ישראל ואפילו אם דעת הישראל לצאת אח\"כ לחדר אחר שלא יהנה מהנר ג\"כ צריך למחות וכ\"ש בבית ישראל ואם הא\"י עושה בע\"כ חייב לגרשו מביתו מפני חילול השם שיחשדוהו שעושה הא\"י בשליחותו כיון שהוא בבית ישראל ואין חילוק בזה בין אם הא\"י עושה בחנם או שקצץ עמו שכר בקיבולת כיון שהוא עושה בבית ישראל:","(יב) בבית ישראל - לאו דוקא דה\"ה אם שבת במלון אצל א\"י בשבת כביתו הוא ולא הטריחוהו לצאת ממנו [ב\"י]:","(יג) מדעתו - היינו שלא צוהו הישראל אע\"פ שעושה הא\"י בשבילו לא הטריחו אותו לצאת מהבית אע\"פ שבע\"כ הוא נהנה רק שאסור להשתמש לאורו דבר שלא היה יכול לעשות בלא נר או להתחמם נגד המדורה אבל אם צוהו מתחלה צריך לצאת אח\"כ מהבית:","(יד) אין וכו' - וה\"ה שא\"צ להפוך פניו מהנר אא\"כ שרוצה לעשות מדת חסידות כ\"כ המ\"א בשם הב\"י ובחידושי הרשב\"א משמע שהוא מחמיר בזה עי\"ש:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i>ישראל ועכו\"ם שהסיבו יחד והדליק עכו\"ם נר אם רוב עכו\"ם מותר להשתמש לאורו ואם רוב ישראל או אפילו מחצה על מחצה אסור <i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"7\"></i>ואם יש <i data-commentator=\"Magen Avraham\" data-order=\"6\"></i>הוכחה שלצורך <i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>עכו\"ם מדליקה כגון שאנו רואים שהוא משתמש לאורה <i data-commentator=\"Turei Zahav\" data-order=\"2\"></i>אף על פי שרוב ישראל מותר: <small>הגה י\"א דמותר לומר לעכו\"ם להדליק לו נר <i data-commentator=\"Magen Avraham\" data-order=\"7\"></i>לסעודת <i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i>שבת משום דסבירא ליה' דמותר אמירה לעכו\"ם אפי' במלאכה גמורה במקום <i data-commentator=\"Magen Avraham\" data-order=\"8\"></i>מצוה [ר\"ן ס\"פ ר\"א דמילה בשם העיטור] שעל פי זה נהגו רבים להקל בדבר לצוות לעכו\"ם להדליק נרות לצורך סעודה בפרט בסעודת חתונה או מילה <i data-commentator=\"Magen Avraham\" data-order=\"9\"></i>ואין מוחה בידם ויש להחמיר במקום שאין <i data-commentator=\"Ba'er Hetev\" data-order=\"5\"></i>צורך גדול דהא רוב הפוסקים חולקים על סברא זו ועיין לקמן סי' ש\"ז ס\"ה:</small>","m":["(טו) אם רוב א\"י - דמסתמא אדעתא דרובא קעביד ואפילו אם אח\"כ נתרבו ישראל ונתוספו עליהן או שהלכו להן הא\"י וכן להיפוך ברוב ישראל:","(טז) מחצה על מחצה - הטעם משום דליכא למיקם עלה דמלתא אם בשביל א\"י עביד או בשביל ישראל עביד וי\"א משום דבמחצה על מחצה מסתמא לשם שניהם נעשה:","(יז) שלצורך א\"י - ר\"ל לצורך עצמו וכדמסיים לבסוף וה\"ה אם יש הוכחה שהדליק בשביל איזה א\"י אחר. ואם אנו יודעין שעשה גם בשביל ישראל אסור כ\"כ המ\"א ועיין בבה\"ל שהארכנו בזה:","(יח) שהוא משתמש - היינו מיד:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ח\" data-order=\"8\"></i>אם אומר אדם לעבדו או לשפחתו לילך עמו והדליקו הנר אע\"פ שגם הם צריכים לו אין זה לצורך העכו\"ם כיון שעיקר ההליכה בשביל ישראל: <small>הגה ומותר לומר לעכו\"ם לילך עמו <i data-commentator=\"Magen Avraham\" data-order=\"10\"></i>ליטול נר דלוק <i data-commentator=\"Ba'er Hetev\" data-order=\"6\"></i>כבר הואיל ואינו עושה <i data-commentator=\"Magen Avraham\" data-order=\"11\"></i>רק טלטול הנר בעלמא (רבי' ירוחם ני\"ב ח\"ב והגהות מרדכי פ\"ק דשבת והגהות מיי' פ\"י):</small>","m":["(יט) אע\"פ וכו' - דמסתמא כשהדליק מתחלה נמי העיקר אדעתא דידיה עביד ונר לאחד נר למאה:","(כ) לסעודת שבת - היינו שיושב בחשך ואין לו שום נר לאכול אבל אם גמר סעודתו אף שעדיין לא בירך בהמ\"ז או שיש לו נר אחד פשיטא דאסור לצוות לא\"י להדליק לו דהוי שבות שלא במקום מצוה מיהו אם יש לו שום נר ועבר וצוה לא\"י להדליק לו נר אחר שרי ליהנות ממנו בעוד שהנר הראשון דולק כמ\"ש בסעיף ד':","(כא) אמירה לא\"י - אבל שבות דישראל עצמו לכו\"ע אסור אפילו במקום מצוה:","(כב) במקום מצוה - ולבנות בהכ\"נ בשבת ע\"י א\"י כתב המ\"א דאסור אפילו לדעת העיטור ועיין בפמ\"ג שמסיק משום דהוי מצוה שאינה עוברת שיכול לבנותו בחול ועיין בסימן רמ\"ד במ\"א שהוא אסור לעשות דבר זה אף בקבלנות אם לא שיש חשש שמא יתבטל ח\"ו עי\"ז בנין הבהכ\"נ לגמרי דאז יש להקל בקבלנות ואפשר דאף ע\"י שכירות מותר בכה\"ג אם לא ירצה הא\"י בקבלנות [פמ\"ג]:","(כג) ואין מוחה - ומוטב שיהיו שוגגין ואל יהיו מזידין [ב\"ח ומ\"א]:","(כד) שאין וכו' - ושל\"ה החמיר אף לצורך גדול ושכן ראה נוהגים בקהלות חשובים שיושבים בחשכה במוצאי שבת אפילו בחתונה עד שאמרו הקהל ברכו וכן נהג הגאון הר\"ש כשהיו סועדים אצלו סעודה שלישית ובפמ\"ג מצדד להקל להדליק ע\"י א\"י במו\"ש לצורך מצוה אף כשהוא עדיין בין השמשות וכ\"ש בערב שבת בין השמשות לצורך מצוה דבודאי מותר כדלקמן בסימן שמ\"ב עי\"ש:","(כה) דהא רוב וכו' - ומ\"מ מותר לומר לא\"י לתקן את העירוב שנתקלקל בשבת כדי שלא יבואו רבים לידי מכשול וכדאי הוא בעל העיטור לסמוך עליו להתיר שבות דאמירה אפילו במלאכה דאורייתא במקום מצוה דרבים [ח\"א בשם המ\"מ] וכעין זה דעת הפמ\"ג לעיל בסוף ס\"ק כ\"ב:","(כו) ועיין לקמן - ר\"ל דשם ג\"כ מבואר דלא כבעל העיטור:","(כז) לילך עמו - דוקא נקט אבל אם משלחם בשליחותו שילכו בעצמם והדליקו את הנר להאיר להם אין זה מקרי לצרכו אף שעיקר הליכתם הוא בשבילו כיון שאין גופו נהנה מהנר בעת ההדלקה ומותר אח\"כ לישראל להשתמש אצל הנר וכעין זה כתב הט\"ז בסוף הסימן וז\"ל נ\"ל אותו הנר שמדלקת השפחה כדי להדיח כלי אכילה שאכלו לא מיקרי לצורך ישראל כיון שאין גוף הישראל נהנה ממנו אלא כלים שלו מודחים והיא חייבת להדיחם לצרכה היא מדלקת ומותר אח\"כ ישראל להשתמש לנר זה אף צרכי גופו כיון דבעת הדלקת הנר הדליקה לצרכה. ומותר לסייע להשפחה גם בהדחת הכלים לפני נר זה דאף שמצדד הפמ\"ג להחמיר בזה היינו כשהישראל ידיח לבדו את הכלים אחר שהדליקה השפחה הנר ומשום דמחזי שהדליקה לצרכו משא\"כ בזה אמרינן דהעיקר אדעתא דנפשה קעבדה וכנ\"ל בס\"ב:","(כח) צריכים לו - ר\"ל וא\"כ הוא הוכחה שלצרכו הדליק וכדלעיל בס\"ב:","(כט) לומר לא\"י - ואין להתיר אלא לבני תורה דילמא אתי למיסרך ולהקל יותר:","(ל) לילך עמו - כגון שרוצה שילך עמו למשוך יין מן המרתף או להביא לחם וכה\"ג ואין חילוק בין נר של שעוה וחלב או של שמן אך בנר של שמן נכון להחמיר שלא לומר לא\"י שילך עמו במרוצה כי אי אפשר שלא יתקרב עי\"ז השמן להפתילה או יתרחק ויש בזה משום מכבה ומבעיר אם היה הישראל בעצמו עושה זה ע\"כ אין לומר זה לא\"י:","(לא) בעלמא - ר\"ל הואיל דהוא רק איסור מוקצה ומוקצה שרי ע\"י טלטול מן הצד כמש\"כ בסימן שי\"א וכיון דאי בעי ישראל שקיל ליה בעצמו ע\"י טלטול מן הצד כגון באחורי ידיו או בין אצילי ידיו וכי\"ב כשמביא הא\"י באיסורא לית לן בה ועיין לקמן סימן רע\"ט במ\"א סק\"ט דלטלטל את הפתילה ע\"י הא\"י כדי שלא יגנב או שלא יפסד אסור ורק טלטול כשהוא צריך לו גופא וכנ\"ל בסק\"ל או כשצריך למקומו מותר וכ\"כ בדה\"ח:","(לב) מותר - ר\"ל אף דעתה ע\"י הנר הזה שהדליק בשביל ישראל נתגדל האור יותר אפ\"ה מותר ומיירי כשהיה יכול מתחלה במקום הזה עכ\"פ ליהנות קצת לאור הנר הראשון ולכן שרי ובלא\"ה אסור. ועיין לעיל סוף סק\"כ דלכתחלה לומר לא\"י להדליק אסור בכל ענין:","(לג) אבל וכו' - וכן אם היתה מדורה שנדלקה מע\"ש ובא א\"י והוסיף עצים בשבת בשביל ישראל אסור להתחמם כנגדה לאחר שיכלו העצים הראשונים וקודם שיכלו יש להתיר לעת הצורך:","(לד) מותר וכו' - אף דע\"י נתינת השמן ניתוסף האור וכן אם עשה שאר תיקון בהנר בשביל ישראל שעי\"ז ניתוסף האור אף דבודאי איסור גמור לכתחלה לצוות לא\"י לזה אפ\"ה מותר להשתמש לאורו כיון דבלא\"ה היה יכול מתחלה קצת להשתמש לאורו:","(לה) ומותר - דסד\"א להחמיר בזה כדי שלא לדבר בענין הדלקה כלל [ב\"י]:"]},{"s":"<i data-commentator=\"Magen Avraham\" data-order=\"12\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ט\" data-order=\"9\"></i>אם יש נר בבית ישראל ובא עכו\"ם והדליק נר אחר מותר להשתמש לאורו בעוד נר ראשון דולק <i data-commentator=\"Turei Zahav\" data-order=\"3\"></i>אבל לאחר שיכבה הראשון אסור להשתמש <i data-commentator=\"Ba'er Hetev\" data-order=\"7\"></i>לאור השני <i data-commentator=\"Turei Zahav\" data-order=\"4\"></i>וכן אם נתן שמן בנר הדולק מותר להשתמש עד כדי שיכלה השמן שהיה בו כבר ואח\"כ אסור: <small>הגה <i data-commentator=\"Magen Avraham\" data-order=\"13\"></i><i data-commentator=\"Turei Zahav\" data-order=\"5\"></i>ומותר למחות בעכו\"ם שבא <i data-commentator=\"Magen Avraham\" data-order=\"14\"></i>להדליק <i data-commentator=\"Ba'er Hetev\" data-order=\"8\"></i>נר או להוסיף שמן (טור):</small>","m":["(לו) למחות - ומכיון דמיחה בו והראה לו דלא ניחא ליה שיעשה בשבת בשבילו אפילו אם אח\"כ עשה המלאכה חשוב כאלו עשה המלאכה לצרכו ומותר להשתמש לאורו ואפילו אם היה הנר של ישראל בבית ישראל. וכ\"ז כשלא יערים במחאתו [מ\"א]:","(לז) להדליק וכו' - דוקא כשהנר של א\"י אבל כשהנר של ישראל צריך למחות בו כשרואה שרוצה להדליק נר או להוסיף שמן בשבילו וכנ\"ל בס\"ק י\"א עי\"ש [מ\"א]:"]},{"s":"<i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"3\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"י\" data-order=\"10\"></i>בארצות קרות מותר לעכו\"ם לעשות מדורה בשביל הקטנים ומותרין הגדולים להתחמם בו ואפילו בשביל הגדולים מותר אם <i data-commentator=\"Ba'er Hetev\" data-order=\"9\"></i>הקור גדול שהכל חולים אצל הקור <i data-commentator=\"Magen Avraham\" data-order=\"15\"></i>ולא כאותם שנוהגים היתר אע\"פ שאין הקור גדול ביום ההוא: <i data-commentator=\"Be'er HaGolah\" data-label=\"•\" data-order=\"11\"></i>","m":["(לח) לעשות מדורה - וה\"ה להסיק תנור בית החורף:","(לט) ומותרין הגדולים - ר\"ל כיון דהעיקר נעשה בשביל הקטנים וכנ\"ל בס\"א אבל אם נעשה בשביל שניהן ביחד פוסק השו\"ע לקמן בסימן שכ\"ה ס\"ו דאסור:","(מ) מותר - ר\"ל אפילו לומר בפירוש בשבת להסיק:","(מא) גדול - דבלא\"ה אין דרך הגדולים להצטער כ\"כ:","(מב) שהכל חולים - ומ\"מ להסיק אחר מנחה בשבת שיהא למו\"ש אסור מאחר דכבר נתחמם בבוקר ואע\"פ שכבר נתקרר אינו קר כ\"כ שיהא האדם נחשב כחולה אצל קרירות זה ולכן חייבים למחות לא\"י שלא להסיק עוד עד אחר צאת הכוכבים ומ\"מ הכל תלוי לפי הקור ולפי בית החורף:","(מג) אצל הקור - וצריך להכין מבע\"י הפחמים שיהיו מזומנים בשבת לפני הא\"י כי אסור לישראל לטלטלם בשבת ולהכינם לפניו:","(מד) ולא כאותם וכו' - ומ\"מ אין למחות בהם דמוטב שיהיו שוגגין ואל יהיו מזידין [ב\"י]:","(מה) שאין הקור גדול - ועכ\"פ יזהרו שלא לומר לו בשבת להסיק או לעשות המדורה אלא יקצבו עמו בקבלנות שיסיק לו כל ימות החורף בעת שיהיה קר ואז אף אם הא\"י יסיק כשאין הקור גדול אפשר דהו\"ל כאלו עשה מדעתו וא\"צ לצאת מביתו וכמ\"ש בס\"א וע\"ש במ\"ב סקי\"ג:\n"]}],"277":[{"s":"<b>שלא לגרום כיבוי הנר. ובו ה סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>נר שמונח אחורי הדלת אסור לפתוח הדלת <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i><small> (כדרכו) (רמב\"ם פ\"ה ומרדכי פרק כ\"ב וב\"י בשם סמ\"ג) </small> <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>שמא יכבנו הרוח <small> (אבל) <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>לנעול הדלת כנגדו מותר (ת\"ה סי' נ\"ט) (וה\"ה בחלון שכנגד הנר שעל השלחן) (מרדכי פכ\"ב וב\"י בשם תוס' וטור) </small> <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>ואם הוא קבוע בכותל באחורי הדלת <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i>אסור לפתוח הדלת <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i>ולנעלו כדרכו שמא תהא הדלת <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>נוקשת עליו ותכבנו אלא פותח ונועל בנחת <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>ואם הוא קבוע בדלת עצמו שפתיחתו ונעילתו מקרב השמן לנר או מרחיקו ממנו <i data-commentator=\"Turei Zahav\" data-order=\"2\"></i>אסור לפותחו ולנעלו: <small>הגה <i data-commentator=\"Turei Zahav\" data-order=\"3\"></i>ובנר של <i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i>שעוה מותר לפתוח ולנעול <i data-commentator=\"Eshel Avraham\" data-label=\"א\" data-order=\"1\"></i>אע\"פ שהוא קבוע בדלת (ב\"י):</small>","m":["(א) נר וכו' - ואין חלוק בזה בין נר של שמן או שעוה וחלב:","(ב) אחורי הדלת - כגון דלת שנפתחת לפנים ומאחריה מונח בבית נר דלוק. ודוקא כשהוא נגד פתיחת הדלת ממש וקרוב אל הדלת בענין שכשיפתח הדלת יוכל להכבות ע\"י הרוח המנשב מבחוץ ומש\"כ כדרכו עיין במ\"א שכתב דט\"ס הוא דאפילו אם הוא פותח הדלת בנחת מ\"מ הרוח מבחוץ מנשב ואסור וכן סתמו כמה אחרונים ועיין בבה\"ל:","(ג) הרוח - עיין במ\"א סי' תקי\"ד סק\"ט דאפילו אם אין הרוח מנשב עתה ג\"כ יש לאסור דבכל רגע ורגע הרוח מנשב וא\"א להבחין בזה ויש מקילין בזה ונ\"ל דבמקום הדחק יש להקל בזה כשפותח הדלת בנחת לאט לאט שלא יגרום הדלת גופא לרוח שיבא:","(ד) מותר - שבזה אינו עושה כלום לא מכבה ולא מבעיר:","(ה) קבוע בכותל - ר\"ל שהדלת פותחת לפנים והנר קבוע בכותל באופן אם יפתח הדלת תנקוש ותגיע אל נר שלאחוריה:","(ו) ולנעלו - והאחרונים כתבו דבזה לנעול שרי דלא יבא עי\"ז לכבוי ועיין בפמ\"ג שיישב קצת דברי המחבר דמיירי שנועל בכח דעי\"ז מתנדנד הכותל כולו ויבא לכבוי דהיינו שיתרחק קצת השמן שבנר מן הפתילה או שיתקרב קצת השמן שבנר אל הפתילה ויתחייב משום מבעיר:","(ז) מקרב השמן וכו' - ויש בזה משום מבעיר או מכבה ואע\"ג דאינו מכוין מ\"מ פסיק רישיה הוא ואם הוא פותחו ונועלו בנחת בענין שלא יהא פסיק רישיה מותר ואין איסור בטלטול הדלת משום הנר המוקצה הקבוע בה לפי שהדלת לא נעשית בסיס לנר לפי שהיא חשובה שמשמשת לבית ובטלה אצלו ולא להנר:","(ח) של שעוה - ושל חלב ומפני שאין בהם משום מקרב השמן או מרחק. ואם הוא בענין שיש לחוש שע\"י הפתיחה ונעילה יכבה לגמרי אף בשל שעוה אסור:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>אסור לפתוח הדלת כנגד המדורה <i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>שהיא קרובה קצת אל הדלת ואפי' אין שם <i data-commentator=\"Turei Zahav\" data-order=\"4\"></i>אלא רוח מצויה אבל אם היה פתוח כנגדה <i data-commentator=\"Magen Avraham\" data-order=\"6\"></i>מותר לסגרו ואין בו משום מכבה:","m":["(ט) כנגד המדורה - מפני שהרוח המנשב גורם להבעיר המדורה יותר ואע\"פ שאינו מכוין בזה מ\"מ פסיק רישיה הוא:","(י) ואפילו וכו' - ר\"ל אף דע\"י רוח מצויה אין דרך המדורה להבעיר יותר אפ\"ה אסור דגזרינן אטו שאינה מצויה. ואם אין שם רוח כלל מותר [מ\"א בסימן תקי\"ד סק\"ט] ואם ע\"י דפיקת הדלת עושה רוח מצויה משמע בחדושי הר\"ן דאסור:","(יא) מותר לסגרו - ואע\"פ שהרוח היה מבעירה אין בו משום מכבה שאינו עושה כלום אלא עוצר הרוח ואם תכבה תכבה:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i>שכח נר על הטבלא מנער את הטבלא והוא נופל אפי' אם הוא דולק רק שלא יכוין לכבותו: <small>הגה וטוב לעשות <i data-commentator=\"Magen Avraham\" data-order=\"7\"></i>ע\"י <i data-commentator=\"Ba'er Hetev\" data-order=\"5\"></i>עכו\"ם במקום שאינו צריך כ\"כ: (כל בו) </small> <i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"7\"></i>ובלבד שיהא נר של שעוה וכיוצא בו או שלא יהא בו שמן אבל אם יש בו שמן א\"א שלא יקרבנו אל הפתילה ונמצא מבעיר <i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"1\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ח\" data-order=\"8\"></i>ואם <i data-commentator=\"Turei Zahav\" data-order=\"5\"></i>הניח עליה מדעת <i data-commentator=\"Magen Avraham\" data-order=\"8\"></i>אסור לנערה שהרי הטבלא <i data-commentator=\"Ba'er Hetev\" data-order=\"6\"></i>הוא בסיס <small> (פי' דבר הנושא דבר אחר תרגום ואת כנו וית בסיסיה) </small> לדבר האסור: <small>הגה ומ\"מ מותר ליגע בטבלא הואיל ואינו מטלטל הנר והוא הדין שמותר ליגע <i data-commentator=\"Ba'er Hetev\" data-order=\"7\"></i><i data-commentator=\"Turei Zahav\" data-order=\"6\"></i>במנורה שבבית הכנסת והנרות דולקות עליו ובלבד שלא ינענע (מרדכי פכ\"ב):</small>","m":["(יב) שכח נר - מבעוד יום שלא מדעת ואפילו אם הניחו על הטבלא בכונה אך לא היה דעתו שישאר שם בשבת ואח\"כ שכחו שם הוא ג\"כ בכלל שוכח:","(יג) על הטבלא - וה\"ה בכ\"ז בזמננו לענין השלחן עם הנרות [אחרונים]:","(יד) מנער וכו' - כשצריך להטבלא ואע\"ג דאפשר שיכבה הנר ע\"י הנפילה אפ\"ה מותר דלא הוי פסיק רישיה וקי\"ל דדבר שאין מתכוין מותר וכתב במאירי דדוקא אם הוא מנערו בנחת [דהיינו שמטה הטבלא ומורידו לארץ ואח\"כ הוא מנערו] דאל\"ה הוא פסיק רישיה וכן משמע במהרי\"ל והביאו הא\"ר:","(טו) ע\"י א\"י - ואז אפילו בנר של שמן שרי דבמקום שאין מתכוין שרי ע\"י א\"י אפילו הוא פסיק רישיה ומשמע במהרי\"ל דאם אין א\"י מזומן יראה לעשות ע\"י קטן:","(טז) או שלא וכו' - ר\"ל שדולקת רק הפתילה וכבר כלה שמן:","(יז) אי אפשר וכו' - ודוקא בנעור אמרינן דהוא פסיק רישיה אבל טלטול בעלמא את הטבלא או השלחן ממקום למקום שרי אפילו מונח עליו נר של שמן דלא הוי פסיק רישיה ודוקא אם הוא מטלטלו בנחת:","(יח) מדעת - בסימן ש\"ט יתבאר שיש מחלוקת אימת נקרא מדעת אם בעינן דוקא שיניחו ע\"ד שיהיה שם כל השבת או אפילו רק בכניסתו לחוד. והנה הנרות שאנו מדליקין על השלחן דעתנו לטלו למחר ע\"י א\"י ולדעת הי\"א המקילין שם אין דינו כמניח ולא נעשה השלחן והמפה בסיס לאיסור וכתב הב\"ח דאם נפל נר של שעוה או חלב על השלחן ואין א\"י [או קטן] מזומן לפניו שרי לנער בעצמו דבמקום פסידא סמכינן על המקילין הנ\"ל דלא מקרי מניח כיון שהיה דעתו לסלק למחר ואם היה מונח על השלחן בין השמשות גם ככרות ושאר דברים שצריך לשבת פשיטא דהם חשובים יותר מן הנר דהיינו מן שלהבת הנר הדולקת ונעשה בסיס לגבייהו וכמו שכתוב בסימן ש\"י ס\"ח דהיכי דהוא בסיס להיתר ולאיסור וההיתר חשיב יותר דהוא בטיל לגבי ההיתר ושרי לכו\"ע לנער ואם א\"א לנער במקום זה משום פסידא דהיינו שיפסיד איזה דבר ע\"י הפלת הנר במקום זה רשאי לטלטל השלחן למקום אחר ולנערו שם. ואם צריך למקום שעומד השלחן להושיב שם איזה דבר רשאי לטלטל השלחן ואפילו בעוד שהנרות דולקות עליו כיון שהיה מונח עליו הלחם הצריך לשבת לא נעשה בסיס לאיסור ומזה נובע המנהג שהנשים נזהרות ליתן ככר הצריך לשבת על השלחן קודם הדלקת הנרות ומנהג נכון הוא כדי שיהא מותר לטלטל את השלחן כשיהיה צריך לו ורק אם הנר הוא של שמן יזהר מאד לטלטל השלחן בנחת כדי שלא יבא לקרב השמן להפתילה או לרחק. ועיין בפמ\"ג שמצדד לומר דלאחר שכבו הנרות אינו רשאי לטלטל השלחן עם המנורה שעליה דהא יכול לנערה מתחלה והוא שהיתה של מתכות וליכא פסידא בניעורה:","(יט) במנורה שבבהכ\"נ - היינו בקבועה על מקום אחד אבל אם היא תלויה אפילו ליגע בה אסור שבקל ינענע ואפילו כשכבר כבו הנרות כן משמע ממ\"א לעיל בסימן רס\"ה וכן מהט\"ז בסק\"ז וכן משמע מהמרדכי דמיירי בקבועה ועיין מה שכתבנו לעיל בבה\"ל בשם אור זרוע:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ט\" data-order=\"9\"></i>מותר להניח נר של שבת מבעוד יום על גבי אילן וידליק שם בשבת <i data-commentator=\"Turei Zahav\" data-order=\"7\"></i>דליכא למיחש דלכשיכבה לשקליה מיניה ונמצא משתמש במחובר אבל אין מניחין נר של י\"ט על גבי אילן דשקיל ומנח ליה ונמצא משתמש באילן:","m":["(כ) דליכא למיחש וכו' - דהא קיי\"ל דנר שהדליקו בו באותה שבת אסור לטלטלו אפילו לאחר שכבה וכדלקמן בסימן רע\"ט:","(כא) אבל אין מניחין - ר\"ל אפילו להניחו מעי\"ט וכדלקמן בסימן תקי\"ד ס\"ו:"]},{"s":"<i data-commentator=\"Magen Avraham\" data-order=\"9\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"י\" data-order=\"10\"></i>מותר לכפות קערה על גבי <i data-commentator=\"Ba'er Hetev\" data-order=\"8\"></i>הנר בשבת <i data-commentator=\"Turei Zahav\" data-order=\"8\"></i>כדי שלא יאחוז האור בקורה:","m":["(כב) קערה - של חרס אבל של מתכות אסור כי המחממו חייב משום מבעיר אם לא במקום שיש לחוש שיבוא ע\"י הדליקה לידי סכנת נפשות מותר בכל גוונא:","(כג) כדי - ואע\"ג דנוטל הכלי לצורך הקורה שאינה ניטלת בשבת קיי\"ל דכלי ניטל אפילו לצורך דבר שאינו ניטל וכדלקמן בסי' ש\"י ס\"ו:","(כד) שלא וכו' - וה\"ה אם עושה בשביל שקשה לעיניו אורו של הנר או ענין אחר אך יזהר להניח מעט אויר בין הכלי להנר דאל\"כ יכבה הנר:"]}],"278":[{"s":"<b>שיכול לכבות הנר בשביל החולה. ובו סעיף אחד:</b><br><i data-commentator=\"Magen Avraham\" data-order=\"1\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>מותר לכבות הנר <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i>בשביל שישן החולה שיש בו סכנה:","m":["(א) מותר וכו' - עיין ברמב\"ם בפירוש המשנה שכתב דדוקא בשא\"א להוציא החולה למקום אחר או להסתיר האור ממנו ור\"ל ע\"י כפיית כלי על גביו וכדלעיל בסוף הסימן עי\"ש או ע\"י הוצאה לחדר אחר דאל\"ה בודאי יותר טוב לטלטל מוקצה מלעבור על איסור כביה ועיין בבה\"ל:","(ב) לכבות הנר - וכשיקיץ אח\"כ מותר לדלוק הנר בשבילו ובכל זה אם א\"י מזומן לפניו ואפשר לעשות על ידו בלי איחור יעשה על ידו [סימן שכ\"ח סי\"ב בהג\"ה]:","(ג) החולה שיש בו סכנה - שפקוח נפש דוחה שבת וכדלקמן בסימן שכ\"ח וה\"ה כשמתיירא מפני לסטים שלא יבואו עליו ויהרגוהו ואין לו עצה להסתיר את האור ג\"כ מותר לכבות וכתבו האחרונים דה\"ה בשביל החולה שהוא ספק סכנה ג\"כ מותר לכבות אבל בשביל חולה שאין בו סכנה אסור לכבות לכו\"ע ואפי' להפוסקים דס\"ל דאין על כיבוי חיוב חטאת משום דהוי מלאכה שאין צריך לגופה אפ\"ה אסור מדברי סופרים ולכך נקראת מלאכה שאין צריך לגופה שהרי א\"צ לתכלית המלאכה כי א\"צ לכיבוי בשביל עצמו אלא שהוא מכבה מפני איזה ענין כגון כדי שיישן החולה או שהוא חס על השמן שבנר שלא ידלק כולו עכשיו או שהוא חס על חרס הנר שלא יתקלקל מפני חוזק ההדלקה או שמכבה עצים דולקים מפני שחס עליהם או שמכבה את הדליקה מפני שחס על ממונו כ\"ז מקרי אינו צריך לגופו שהרי אינו מכוין לתכלית המלאכה עצמה וכן הדמיון בשאר מלאכות כגון החופר גומא וא\"צ אלא לעפרה שהמלאכה היא הגומא וחייב בבית משום בונה ובשדה משום חורש וכיון דא\"צ לגומא הוי מלאכה שאין צריך לגופה. ואין לך כיבוי הצריך לגופו אלא כשהוא מכבה עצים כדי לעשות מהן פחמין דהלא זה צריך לגוף המלאכה שהרי א\"א לעשות פחמין אם לא שיכבה וכן כשהוא מכבה את הפתילה מפני שצריך להבהבה שיהא נאחז בה האור יפה כשיחזור וידליקנה. וכ\"ז שכתבנו הוא לדעת הרבה פוסקים והרמב\"ם פוסק דמלאכה שאין צריך לגופה חייב עליה ואפילו להפוסקים הנ\"ל איסור כביה חמור משאר איסור דרבנן כיון דיש בו צד חיוב לכו\"ע:"]}],"279":[{"s":"<b>דיני טלטול הנר בשבת. ובו ז סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>נר <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i>שהדליקו בו באותו שבת <i data-commentator=\"Eshel Avraham\" data-label=\"א\" data-order=\"1\"></i>אע\"פ שכבה <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>אסור <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"1\"></i>לטלטלו <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>וכן <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>מותר השמן שבנר שהדליקו בו באותו שבת אסור לטלטלו להסתפק ממנו באותו שבת:","m":["(א) אע\"פ שכבה וכו' - והיינו אפילו לא נשאר בו שמן כלל והטעם דכיון דביה\"ש היה אסור בטלטול לפי שנעשה הנר והשמן והפתילה בסיס לשלהבת שהוא דבר האסור בטלטול ומיגו דאיתקצאי לביה\"ש איתקצאי לכולי יומא וזהו הנקרא בגמרא מוקצה מחמת איסור דקי\"ל ביה לאיסורא. אם יש אימת א\"י עליו ע\"י הנר [כמו שהיה בזמן האמוראים שהיתה אומה אחת שהיו מקפידין ביום חגם על ישראל שמדליקין נר באותו היום וכל כה\"ג] מותר לטלטלו לאחר שכבה [ש\"ג וכן הסכים בספר תו\"ש ודלא כמ\"א ומפמ\"ג משמע שאם ירא שיכהו או שאר הפסד ממון לכו\"ע שרי]:","(ב) מותר השמן שבנר - וה\"ה מותר הנר העשוי מחלב ושעוה שהדליקו בו באותה שבת וכבה [אחרונים]:","(ג) לטלטלו ולהסתפק ממנו וכו' - דהואיל והוקצה בתחלת כניסת השבת דהיינו שבביה\"ש כשהיה דולק היה אסור להסתפק ממנו דהמסתפק משמן שבנר חייב משום מכבה וכדלעיל ברס\"י רס\"ה איתקצאי לכולי יומא שלא להסתפק ממנו אף אחר שכבה וכיון שאסור ליהנות ממנו כל יום השבת ממילא אסור ג\"כ לטלטלו דאינו ראוי לכלום ומלבד זה בטלטול גופא הוקצה בבין השמשות שנעשה הכל בסיס להשלהבת וכדלעיל בריש סק\"א:","(ד) אפילו לצורך וכו' - ולא דמי לשאר כלי שמלאכתו לאיסור דמותר לטלטלו לצורך גופו ומקומו וכמו דאיתא בסימן ש\"ח ס\"ג דהכא כיון דבביה\"ש היה אסור לטלטלו אף לצורך גופו ומקומו דהיה בסיס להשלהבת וכנ\"ל מיגו דאיתקצאי לביה\"ש לגמרי איתקצאי לכולי יומא לגמרי ואין חילוק בכל זה בין הנר שהדליקו בו השמן ובין המנורה שהדליקו בה הנרות דגם הוא נעשה בסיס להנרות:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>נר זה שאמרנו שאסור לטלטלו אפי' לצורך גופו ולצורך מקומו אסור <i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>ויש מי שהתיר <i data-commentator=\"Turei Zahav\" data-order=\"2\"></i>ולא נראה דבריו: <small>הגה <i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"1\"></i>וי\"א דמי שהוא איסטניס והנר מאוס עליו מותר להוציאו דהוי לדידיה כגרף של רעי <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i><i data-commentator=\"Turei Zahav\" data-order=\"3\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>והמחמיר לא הפסיד (מרדכי ריש ביצה):</small>","m":["(ה) איסטניס - והב\"ח ומ\"א פסקו דאף מי שאינו איסטניס אם הוא אומר שמאוס עליו שרי לסלקו מעל השלחן ומשמע בב\"ח דלא הקיל אלא בנר של חרס שהוא מאוס בודאי וכדלקמן בס\"ו וה\"ה של עץ אבל של מתכת לא מאיס ובדה\"ח משמע דיש להחמיר באינו איסטניס וכדעת ההג\"ה:","(ו) מאיס עליו - היינו שאינו יכול לסבול שיהא מונח אצלו לאחר שכבה או למחר ביום:","(ז) להוציאו - היינו כשהוא מונח במקום ישיבתו שרי להוציאו משם אבל אם הוא מונח במקום אחר גם האיסטניס אסור לטלטלו ממקום למקום לכו\"ע [אחרונים]:","(ח) והמחמיר לא הפסיד - צ\"ל והמחמיר יחמיר והמיקל לא הפסיד:","(ט) אסור - הטעם דהא מ\"מ כבר איתקצאי בביה\"ש דעדיין לא היה בו אז לחם ומיגו דאיתקצאי בביה\"ש וכו':"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>לטלטל נר ע\"י שנותנין עליו לחם <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i>בשבת <i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>אסור ואם נתן עליו הלחם מבעוד יום <i data-commentator=\"Turei Zahav\" data-order=\"4\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i>יש מי שמתיר לטלטלו בשבת <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"4\"></i>על ידי לחם זה ואין לסמוך עליו:","m":["(י) הלחם - היינו אם הלחם הוא חשיב אצלו יותר מהשמן וה\"ה אם מניח שאר דבר חשוב דאז אמרינן כיון דהנר נעשה בסיס לאיסור דהוא השמן ולהיתר וההיתר חשוב טפי ולכך שרי כמ\"ש סימן ש\"י ומ\"מ סיים המחבר שאין לסמוך ע\"ז והטעם דכיון דהמנורה עיקר עשייתה בשביל השלהבת לכן נעשית תמיד טפל ובסיס להשלהבת ולא ללחם ושארי דברים אחרים אף שהם חשובים יותר [מ\"א]:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"7\"></i>אם התנה מע\"ש על נר זה שיטלטלנו משיכבה <i data-commentator=\"Magen Avraham\" data-order=\"6\"></i>מותר לטלטלו אחר שכבה: <small>הגה <i data-commentator=\"Magen Avraham\" data-order=\"7\"></i>וי\"א דלא מהני תנאי וכן נוהגין במדינות אלו <i data-commentator=\"Magen Avraham\" data-order=\"8\"></i>ודין התנאי ע\"ל סי' <i data-commentator=\"Ba'er Hetev\" data-order=\"5\"></i>תרל\"ח (הגהות אשירי פ' כירה ור\"י ח\"ב כל בו) ונוהגין לטלטלו ע\"י עכו\"ם ואין בזה משום <i data-commentator=\"Magen Avraham\" data-order=\"9\"></i>איסור אמירה <i data-commentator=\"Ba'er Hetev\" data-order=\"6\"></i>לעכו\"ם הואיל והמנהג כך <i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"2\"></i>הוי כאלו התנה עליו מתחלה ושרי כנ\"ל:</small>","m":["(יא) אם התנה וכו' - משום דנר עשוי להכבות משו\"ה מהני ביה תנאי אבל בשאר בסיס לדבר האסור אף לדעה ראשונה לא מהני תנאי להתנות כשיסתלק הדבר איסור מן הבסיס שיהא מותר להשתמש [מ\"א וש\"א] ועיין לקמן בסימן תקי\"ח בבה\"ל:","(יב) ודין התנאי ע\"ל וכו' - היינו לענין שיעשהו קודם בה\"ש כמבואר שם אבל הכא אינו יכול לומר אפילו לדעה ראשונה איני בודל מהנר כל בין השמשות כמו התם דהא ביה\"ש הוא דולק וע\"כ אסור לטלטלו [מ\"א] ומדברי הגר\"א בביאורו דכתב דסברא הראשונה ס\"ל כגירסת הרי\"ף שם בביצה דף ל' משמע לכאורה דמהני ג\"כ באומר איני בודל כידוע שיטת הרי\"ף שם:","(יג) לטלטלו ע\"י א\"י - היינו אפילו אם אינו צריך לו לצורך גופו ומקומו רק שלא יגנב או שלא יפסד [אחרונים]:","(יד) הוי כאלו התנה - ר\"ל דלטלטלו ע\"י א\"י מצרפינן לזה הדעה ראשונה דמהני תנאי. ואם העמיד עששית על השלחן ודעתו היה שידלק כל היום כולו [כמו יא\"צ וכדומה] וכבה דבזה לא שייך לומר הוי כאלו התנה אפשר דאסור לטלטלו אף ע\"י א\"י [פמ\"ג] והיינו דוקא כדי שלא יגנב אבל לצורך גופו ומקומו שרי ע\"י א\"י בכל גווני:","(טו) מותר וכו' - דאין מוקצה לחצי שבת דדוקא אם איתקצאי ביה\"ש שהוא בתחלת כניסת השבת הוא דאמרינן דאיתקצאי לכולי שבת אף לאחר שכבה אבל לא בזה שהודלק מע\"ש לחיה וחולה שיש בו סכנה שהיה מותר בתחלת השבת לטלטלו לא איתקצאי לכולי שבת לאחר שנתרפא החולה אלא על זמן שהוא דולק בלבד וכ\"ש אם הודלק בשבת גופא לצורך חיה וחולה דלא היה דולק כלל ביה\"ש בודאי לא איתקצאי לכולי יומא:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ח\" data-order=\"8\"></i>נר שהדליקו בשבת לחיה ולחולה וילדה החיה ונתרפא החולה <i data-commentator=\"Magen Avraham\" data-order=\"10\"></i>מותר <i data-commentator=\"Ba'er Hetev\" data-order=\"7\"></i>לטלטלו אם כבה <i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"3\"></i>והוא הדין למדליק בשבת <i data-commentator=\"Magen Avraham\" data-order=\"11\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"8\"></i>בשוגג וכבה שמותר לטלטלו:","m":["(טז) לטלטלו אם כבה - היינו דוקא לצורך גופו או מקומו דלא עדיפא משאר כלי שמלאכתו לאיסור [אחרונים]:","(יז) והוא הדין וכו' - הכל מטעם הנ\"ל דאין מוקצה לחצי שבת שיאסר אף אחר שכבה:","(יח) בשוגג - נקט בשוגג דלא איירי ברשיעיא ובאמת אפילו הדליקו במזיד ג\"כ מותר לטלטלו אחר שכבה לצורך גופו או מקומו הואיל ולא היה מוקצה בתחלת כניסת השבת:","(יט) מותר לטלטלו - ואף דהוא כלי שמלאכתו לאיסור מ\"מ לצורך גופו ומקומו מותר וכמ\"ש סימן ש\"ח ס\"ג:","(כ) מותר - הואיל ואיכא תורת כלי עליה וחזי לכסויי ביה מנא:","(כא) מנורה וכו' - אפילו היא חדשה שלא הדליקו בה מעולם:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ט\" data-order=\"9\"></i>נר שלא הדליקו בו באותו שבת <i data-commentator=\"Be'er HaGolah\" data-label=\"י\" data-order=\"10\"></i>אפי' הוא של חרס דמאיס ואפילו הוא של נפט <i data-commentator=\"Magen Avraham\" data-order=\"12\"></i>דמסריח מותר <i data-commentator=\"Ba'er Hetev\" data-order=\"9\"></i>לטלטלו דמוקצה <i data-commentator=\"Magen Avraham\" data-order=\"13\"></i>מחמת מיאוס מותר:","m":[]},{"s":"<i data-commentator=\"Magen Avraham\" data-order=\"14\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"כ\" data-order=\"11\"></i>מנורה בין גדולה בין קטנה אם היא של פרקים אין מטלטלין אותה דחיישינן <i data-commentator=\"Turei Zahav\" data-order=\"5\"></i>שמא תפול <i data-commentator=\"Ba'er Hetev\" data-order=\"10\"></i>ותתפרק ויחזירנה <i data-commentator=\"Turei Zahav\" data-order=\"6\"></i>ונמצא <i data-commentator=\"Ba'er Hetev\" data-order=\"11\"></i>עושה כלי <i data-commentator=\"Be'er HaGolah\" data-label=\"ל\" data-order=\"12\"></i>ואפילו אם אינה של פרקים אלא יש בה חריצים סביב ודומה לשל פרקים <i data-commentator=\"Ba'er Hetev\" data-order=\"12\"></i>אסור לטלטלה:","m":["(כב) ונמצא עושה כלי - עיין בט\"ז ועיין לקמן סימן תקי\"ט ס\"ב. ואם דרכה להיות רפוי שרי כמ\"ש סימן שי\"ג ס\"ו וע\"ש מה שכתבנו במ\"ב לענין כוסות של פרקים:","(כג) ודומה וכו' - משום דמיחלף בשל פרקים. ודע דלפי המתבאר בסעיף זה אסור לטלטל נרות שלנו [שקורין לייכטע\"ר] אף שלא הדליקו בו מעולם דהרי הם עשויין של פרקים ומש\"כ בס\"ו מיירי בנרות שלא היו עשויין פרקים: "]}],"280":[{"s":"<b>תשמיש המטה בשבת. ובו ב סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>תשמיש המטה <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>מתענוגי שבת הוא <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i><i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"1\"></i>לפיכך עונת תלמידי חכמים הבריאים מליל שבת לליל שבת:","m":["(א) עונת וכו' - ויהיה זהיר לקיים עונתו מצוה לאכול שום בע\"ש או בליל שבת וה\"ה שאר דברים המרבים זרע עיין סי' תר\"ח. כתב בס\"ח סימן ש\"ץ דשומים מבטלים תאוה רק שומים צלויים מרבים זרע. עוד כתב כל דברים מלוחים ממעטים וכן קטניות. ועדשים מבושלים כשאין מלוחים מרבים [א\"ר]:","(ב) הבריאים - לאפוקי חלושי כח אינם חייבין רק לפי כחן:","(ג) מליל שבת וכו' - היינו לבד ליל טבילה. וצריך להזהר שקודם שיגיע הלילה חייב להראות חבה יתירה ואהבה עם אשתו וא\"צ לומר שלא ירגיל שום קטטה בע\"ש [ב\"ח]:"]},{"s":"<i data-commentator=\"Turei Zahav\" data-order=\"2\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>מותר <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>לבעול לכתחלה בתולה בשבת ואין בו משום חובל ולא משום צער לה:","m":["(ד) משום חובל - דדם מיפקד פקיד דהיינו שדם בתולים אינו מובלע בכותלי בית הרחם אלא כנוס הוא שם כמופקד ומוצנע בתוך הכלי וזה פתחו שיצא הדם מתוכו. והנה י\"א דבמקום שנתפשט המנהג להחמיר בזה אין להקל להם אבל הט\"ז כתב חלילה לעשות איסור בזה ובבירור שמעתי שהחסידים גאוני העולם נהגו בעצמם היתר בזה ע\"כ אין חשש חומרא בזה כלל והמחמיר אינו אלא מן המתמיהין. ועיין לקמן סימן של\"ט סקי\"א במ\"א דלכתחלה ראוי ליחדן אחר החופה יחוד גמור קודם השבת די\"א דחופה שלנו לא מקרי חופה וא\"כ כשיתיחדו אח\"כ בשבת יהיה אח\"כ כקונה קנין בשבת:\n"]}],"281":[{"s":"<b>שלא יכרע בולך אנחנו מודים. ובו סעיף אחד:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>אין לשחות בולך אנחנו מודים שאין לשחות אלא במקומות שאמרו חכמים: <small>הגה ונוהגים שבשבת מאחרין יותר לבא לבהכ\"נ <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>מבחול משום דבתמיד של ימות החול נאמר בבוקר ואצל שבת נאמר <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"•\" data-order=\"2\"></i>וביום השבת דמשמע איחור (מרדכי פכ\"כ) ונוהגין להרבות בזמירות של שבת כל מקום לפי מנהגו ובכל דבר אם לא אמרו אין מחזירין אותו מלבד אם לא אמר לאל אשר שבת וכו' <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"1\"></i>מחזירין אותו <i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"1\"></i>ויש להאריך <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>ולהנעים בזמירות <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i>ואין למחות במאריך בהם אע\"פ שהמוחה מכוין משום ביטול תורה (אור זרוע) ומ\"מ בשבת ויו\"ט לא יאריך יותר מדאי כדי שיאכלו קודם שעה ששית כדלקמן סי' רפ\"ח:</small>","m":["(א) מאחרין - ומ\"מ צריכין ליזהר שלא לעבור זמן ק\"ש וברש\"י [מגילה כ\"ג] משמע שגם בשבת מצוה למהר לקרוא ק\"ש כותיקין:","(ב) ובכל דבר וכו' - היינו כל דבר שמוסיפין בשביל שבת ואפילו נשמת:","(ג) מחזירין אותו - אין הכונה שמחזירין אותו לברכת יוצר אור אלא לאחר תפלת ח\"י יאמר כך בלי ברכה ויתחיל משבח נותנים וכו' משא\"כ שאר זמירות אם שכח אין חיוב לאמרן אחר התפלה. ואם נזכר קודם שאמר בא\"י יוצר המאורות שלא אמר לאל אשר שבת אפשר דיש לחזור ולהתחיל מלאל אשר שבת [פמ\"ג ע\"ש שנשאר בזה בצ\"ע]. כתב הח\"א מ\"מ נ\"ל שלא ידלג לכתחלה הנוסח דלאל אשר שבת או הכל יודוך כדי להתפלל בצבור שהרי כ\"ז נזכר בזהר ש\"מ שנוסח ברכה כך היא:","(ד) ולהנעים - היינו לאמרם בנגון שיש בו נעימה כעין שעושין בפסוקי דזמרה אבל לא להאריך הרבה וכבר הפליגו הקדמונים בגנות המשוררים המאריכים ומפרידים אות מחברתה ותיבה מחברתה. וביותר מצוי קלקול ע\"י הנגונים בסיום הברכה כשעונין הקהל אמן לפעמים עונין קודם שיסיים ממש הברכה ולפעמים מאריכין בניגון אחר סיום התיבה ועונין בהפסק גדול אמן [פמ\"ג]:","(ה) במאריך בהם - ומ\"מ יש ליזהר מאד שלא לעבור זמן ק\"ש ותפלה עי\"ז:"]}],"282":[{"s":"<b>קריאת התורה והמפטיר בשבת. ובו ז סעיפים:</b><br><i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>מוציאין ס\"ת וקורים בו <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>שבעה <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i><i data-commentator=\"Eshel Avraham\" data-label=\"א\" data-order=\"1\"></i>ואם רצה להוסיף <i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>מוסיף: <small>הגה <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i>וה\"ה ביו\"ט מותר להוסיף על הקרואים (רמב\"ם פי\"ב מהל' תפלה ותשובת מהר\"ם וב\"י) ויש אומרים <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>דבי\"ט <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>אין <i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i>להוסיף (ר\"ן פרק הקורא) וכן נהגו במדינות אלו מלבד בשמחת תורה שמוסיפין הרבה גם בכל יו\"ט אין המפטירין ממנין הקרואים כדלקמן:</small>","m":["(א) מוציאין וכו' - יש לומר בריך שמיה בפתיחת הארון בין בשבת ובין בחול. והנותן ס\"ת והמקבלו צריך שיהא בימין ואפילו אם הוא איטר יד אין לשנות בזה:","(ב) וקורין בו וכו' - והיא מצוה מד\"ס והיא תקנה קדומה ממשה רבינו ע\"ה וכמ\"ש בסימן קל\"ה עי\"ש במ\"ב:","(ג) שבעה - הנה בזמן המשנה היה המנהג שהראשון שבקרואים היה מברך הברכה לפניה והאחרון היה מברך הברכה לאחריה והאמצעים כולן היו יוצאין בברכתן ואח\"כ בזמן הגמרא התקינו שכל אחד יברך לפניה ולאחריה כמו שנהוג היום:","(ד) ואם רצה - וי\"א שהיום שכל אחד מהקרואים מברך לפניה ולאחריה וכנ\"ל אין כדאי להוסיף להרבות בברכות אך במקום הצורך כגון חתונה או ברית מילה וכל כה\"ג אין לחוש לזה:","(ה) מוסיף - ונכון שלא להוסיף הרבה מפני טורח הצבור ובמקום שיש לחוש לתרעומות איזה אנשים כשלא יקראו להם לתורה א\"צ לדקדק בזה. כתבו האחרונים דבשבת שקורין ב' פרשיות יש לקרות מנין חצי הקרואים מהשבעה בכל סדרה דהיינו שקורא להרביעי קצת מהסדר א' ומהסדר ב' ג' פסוקים עכ\"פ ואין לחוש במה שיוסיף על השבעה בסדר ב' כיון דאין שום חיוב מן הדין להוסיף:","(ו) אין להוסיף - וכשחל יו\"ט בשבת לכו\"ע מותר להוסיף על שבעה כמו בשאר שבתות השנה דכי בשביל שניתוסף בו קדושת יו\"ט נגרע ממנו המעלה דשאר שבתות אך כשחל יוה\"כ בשבת טוב לכתחלה שלא להוסיף על שבעה משום שראשי הפרשיות מכוונים שמסיימים במילי דכפרה:","(ז) מלבד בשמחת תורה - דכדי שיזכה כל אחד לקרוא בתורה בעת סיום התורה אוקמי אדינא כרוב הפוסקים שמתירין להוסיף ביו\"ט:","(ח) אין המפטירין וכו' - ר\"ל דלמפטיר קורא פרשה בפני עצמה בחובת היום ומזה ממילא ג\"כ ראיה דנקטינן לדינא כדעה א' דביו\"ט מותר להוסיף על מנין הקרואים וכדלקמן:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>מותר לקרות עולים הרבה אע\"פ שקרא זה מה שקרא זה וחוזר ומברך אין בכך כלום: <small>הגה ויש אוסרים (מרדכי סוף מגילה) וכן נהגו במדינות אלו <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"5\"></i>חוץ מבשמחת תורה שנהגו להרבות בקרואים ונוהגים כסברא ראשונה:</small>","m":["(ט) אין בכך כלום - ומ\"מ אינו עולה מן המנין אם לא שהוסיף לכל הפחות שני פסוקים על מה שקרא הראשון דאז דיעבד עולה למנין וכמ\"ש בסוף סימן קל\"ז:","(י) חוץ מבש\"ת - י\"א דה\"ה בחתונה אבל מנהגנו שלא לקרוא לזה מה שקרא כבר אחד אף בחתונה לבד בש\"ת נוהגין כרמ\"א [פמ\"ג]:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>הכל עולים <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"6\"></i>למנין ז' אפי' אשה <i data-commentator=\"Magen Avraham\" data-order=\"6\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"7\"></i>וקטן שיודע למי מברכין אבל אמרו חכמים אשה לא תקרא בציבור מפני כבוד הציבור: <small>הגה ואלו דוקא מצטרפים למנין הקרואים אבל לא שיהיו כולם נשים או קטנים (ר\"ן וריב\"ש) ודין עבד כנעני כדין אשה אבל אם <i data-commentator=\"Magen Avraham\" data-order=\"7\"></i>אמו מישראל <i data-commentator=\"Eshel Avraham\" data-label=\"ב\" data-order=\"2\"></i>מותר לעלות (הגהות מיי' פי\"ב מהל' תפלה) ואסור לקרות <i data-commentator=\"Magen Avraham\" data-order=\"8\"></i>בראש מגולה ואין איסור לקרות ע\"ה נכבד ועשיר וגדול הדור לפני ת\"ח כי אין זה בזיון לת\"ח רק כבוד לתורה שמתכבדת באנשים גדולים (א\"ז) וממזר מותר לעלות לס\"ת (מהר\"א מפרא\"ג) וע\"ל סי' קל\"ו מסדר הקרואים:</small>","m":[]},{"s":"<i data-commentator=\"Magen Avraham\" data-order=\"9\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>נוהגים לקרות שבעה לגמור עמהם הפרשה <i data-commentator=\"Turei Zahav\" data-order=\"2\"></i>ואומר קדיש וחוזר וקורא עם המפטיר מה שקרא השביעי. <small>הגה <i data-commentator=\"Magen Avraham\" data-order=\"10\"></i>וכן נוהגים בימים טובים שאין מפטיר ממנין הקרואים אבל בחול שאסור להוסיף על מנין הקרואים השלישי הוא מפטיר וביום שמוציאין ב' ספרים או ג' <i data-commentator=\"Magen Avraham\" data-order=\"11\"></i>המפטיר קורא באחרונה <i data-commentator=\"Eshel Avraham\" data-label=\"ג\" data-order=\"3\"></i>וקטן יכול לקרות בפרשת המוספין <i data-commentator=\"Ba'er Hetev\" data-order=\"8\"></i>או <i data-commentator=\"Magen Avraham\" data-order=\"12\"></i>בד' פרשיות שמוסיפין באדר וכן נוהגים (ר\"ן ומרדכי פ\"ב דמגילה) <i data-commentator=\"Turei Zahav\" data-order=\"3\"></i>אע\"פ שיש חולקים <i data-commentator=\"Magen Avraham\" data-order=\"13\"></i><i data-commentator=\"Turei Zahav\" data-order=\"4\"></i>ואומרים קדיש קודם שעולה <i data-commentator=\"Ba'er Hetev\" data-order=\"9\"></i>המפטיר ואין חילוק בזה בין הוסיפו על מנין הקרואים או לא ובין מוציאין ס\"ת א' <i data-commentator=\"Ba'er Hetev\" data-order=\"10\"></i>או ג' (ב\"י בשם הר\"ר ישעיה והרא\"ש ורבי ירוחם):</small>","m":[]},{"s":"<i data-commentator=\"Magen Avraham\" data-order=\"14\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>אם לא נמצא מי שיודע להפטיר אלא אחד מאותם שעלו לקרות בתורה וכבר אמר ש\"ץ קדיש אחר קריאת הפרשה <i data-commentator=\"Turei Zahav\" data-order=\"5\"></i>זה שרוצה להפטיר <i data-commentator=\"Magen Avraham\" data-order=\"15\"></i>צריך לחזור ולקרות ויברך על קריאתו תחלה <i data-commentator=\"Ba'er Hetev\" data-order=\"11\"></i>וסוף: <small>הגה אבל אם לא אמר קדיש <i data-commentator=\"Magen Avraham\" data-order=\"16\"></i>יפטיר מי שעלה <i data-commentator=\"Ba'er Hetev\" data-order=\"12\"></i>לשביעי אם יודע ואם יש אחרים שיודעים להפטיר לא יפטיר מי שעלה כבר (א\"ז) עססי' קמ\"ד:</small>","m":[]},{"s":"<i data-commentator=\"Magen Avraham\" data-order=\"17\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i>אם טעה ש\"ץ וסיים הפרשה עם הששי ואמר קדיש אין צריך לקרות עוד אחר אלא יקרא עם המפטיר מה שקרא עם הששי דקי\"ל מפטיר עולה למנין שבעה:","m":["(יא) למנין שבעה - אבל לא למנין שלשה [מ\"א] ובעולת שבת כתב עוד דה\"ה למנין דה\"ו שיש בר\"ח ויו\"ט ויוה\"כ ג\"כ אין עולה:","(יב) וקטן - ואף אם אין שם כהן אלא קטן קורין אותו [רי\"ט ורדב\"ז] ודעת המ\"א שאין אנו מחוייבין לקרותו דמ\"ע דוקדשתו לא נאמר על כהן קטן דהא כתיב כי את לחם אלהיך הוא מקריב וקטן לאו בר עבודה הוא וכן נוהגין בימינו שכשאין בבהכ\"נ כהן שהוא בן י\"ג שנה קורין ישראל במקום כהן ואפילו יש שם כהן קטן. ויותר מזה נוהגין כהיום שאין קורין קטן כלל לשום עליה אפילו אם כבר נשלם מנין הקרואים אלא למפטיר [אחרונים]. כתב המ\"א בשם מסכת סופרים שהנשים אע\"פ שאין חייבות בת\"ת מ\"מ חייבות לשמוע קריאת ספר כאנשים ואין נוהגות ליזהר בזה ואדרבה יש מקומות שנוהגות הנשים לצאת חוץ בעת הקריאה:","(יג) שיודע למי מברכין - ומ\"מ אין יכול להיות מקרא את העולים דהיינו שהוא יקרא בקול רם בס\"ת והעולים אומרים אחריו בלחש וכל הצבור יהיו יוצאים ידי חובתן בשמיעה ממנו עד שיביא שתי שערות [ומשהוא בן י\"ג שנה בחזקה שהביא שתי שערות לענין זה] ומ\"מ כשאין שם קורא אחר ותתבטל הקריאה לגמרי מסתפק הפמ\"ג דאפשר דיש להקל באופן זה אפילו אם לא הביא עדיין שתי שערות וכן בדה\"ח בהלכות קה\"ת מיקל ג\"כ בשעת הדחק:","(יד) כולם - או רובם:","(טו) אמו מישראל - דאז הו\"ל ישראל מעליא וחייב בכל המצות:","(טז) בראש מגולה - היינו אפילו הוא קטן. וכן קטן שהוא פוחח דהיינו שבגדיו קרועים וזרועותיו וכתפיו מגולין אסור לקרותו לתורה [מגילה כ\"ד ע\"ב]:","(יז) מותר לעלות - שהרי הוא חייב בכל המצות שבתורה כשאר איש ישראל:","(יח) נוהגים - מה שנהגו למכור ששי בפני עצמו יש קצת סמך מהזוהר שלח לך [מ\"א] ואחרון מוכרים בפ\"ע דאחרון חביב שמסיים בו [פמ\"ג] ומ\"מ ח\"ו להתקוטט בעבור זה שכל אותיות התורה הם כולם קדושים וטהורים וכדכתיב אמרות ה' אמרות טהורות וגו':","(יט) לקרות שבעה וכו' - דהנה מן הדין קי\"ל דמפטיר עולה למנין שבעה והיה יכול לגמור הפרשה דהיינו הסדרה עם המפטיר שהוא השביעי ואח\"כ לומר קדיש ואך כדי לצאת גם דעת האומר בגמרא דאין מפטיר עולה למנין שבעה וע\"כ מהנכון הוא לקרות שבעה קרואים קודם שמתחיל המפטיר וכדי להודיע לכל שהמפטיר אינו ממנין העולים תקנו ג\"כ שהנכון לכתחלה להפסיק בהקדיש בין קריאתו לקריאת שאר העולים וממילא מוכרח לגמור הסדרה מתחלה כדי שלא יפסיק בקדיש באמצע הקריאה ואח\"כ לחזור עם המפטיר עכ\"פ ג' פסוקים ממה שקרא השביעי או האחרון:","(כ) ולגמור עמהם הפרשה - וה\"ה דיכול להוסיף עוד על השבעה אך העיקר אשמועינן דנהגו שלא להשלים בהמפטיר את הפרשה ואח\"כ לומר קדיש אלא יאמר קדיש קודם קריאת המפטיר וממילא מוכרח לגמור כל הסדרה מתחלה קודם אמירת הקדיש וכמש\"כ בסקי\"ט:","(כא) וכן נוהגים ביו\"ט - ר\"ל שגם ביו\"ט אף דמדינא היה מותר המפטיר להיות מן המנין חמשה מ\"מ נוהגים ג\"כ שאין המפטיר מן המנין אלא קורא בפני עצמו בפרשה של חובת היום והקדיש אומר מקודם ומ\"מ יוצא בזה אף למ\"ד דעולה מן המנין שהרי רוב הפוסקים סוברים דמותר להוסיף וכנ\"ל בס\"א:","(כב) או ג' וכו' - כגון ר\"ח טבת שחל בשבת שצריך לקרות פרשת השבוע ופרשת ר\"ח וענין של חנוכה או בש\"ת שצריך לקרות פרשת וזאת הברכה ובראשית ופרשת המוספים בכל זה המפטיר בלבד קורא באחרונה ובין כשמשלימין המנין או שמוסיפין על המנין הכל עולים בשני ספרים הראשונים:","(כג) או בד' פרשיות - ואע\"פ שפרשת זכור היא חובה מן התורה שישמענה כל אדם מישראל והקטן שאינו מחויב בדבר אינו יכול להוציאם י\"ח מ\"מ הרי עכשיו הש\"ץ קורא ומשמיע לצבור ומוציאם ידי חובתן ויש מחמירין בדבר שלא לקרותו לקטן לפרשת זכור וכן לפרשת פרה שי\"א שגם היא מדאורייתא וכן הסכים בא\"ר ודה\"ח. וביום א' של שבועות שקורין המרכבה למפטיר וכן בשביעי של פסח שקורין השירה ובשבת שובה ג\"כ נוהגין שאין קורין אותו לכתחלה למפטיר ובתשובת פרח שושן העלה לעיקר דהקטן לא יקרא בד' פרשיות והביאו בחידושי רע\"א. ואמנם גם בשאר מפטיר ג\"כ דוקא בקטן שהגיע לחינוך שיודע לחתוך האותיות בטוב ודלא כאותן שמניחים קטנים הרבה לומר ההפטרה [מ\"א] ועיין בבאור הלכה:","(כד) אע\"פ שיש חולקים - היינו דהחולקים ס\"ל דוקא בשבת שקורא המפטיר מה שכבר קרא השביעי אז נוכל לקרות לקטן משא\"כ בכל אלו שקורא המפטיר פרשה שלא קראו מתחלה:","(כה) ואומרים קדיש - לא חידש בזה כלום על המחבר רק לאשמועינן מה שסיים לבסוף דאין חילוק וכו' אלא בכל פעם אומרים הקדיש קודם המפטיר דוקא:","(כו) קודם שעולה המפטיר - היינו בשבת אבל בחול שהמפטיר ממנין הקרואים אומרים קדיש אחר המפטיר [דהיינו אחר שמכניסין הס\"ת להיכל] ולא קודם דאין אומרים קדיש עד שנשלם המנין ובחוה\"מ פסח וכן בחוה\"מ סוכות אומרים קדיש אחר שקרא הרביעי דאז כבר נשלם מנין הקרואים:","(כז) אם לא נמצא וכו' - וה\"ה בשבת של חזון אפילו נמצא מי שיודע להפטיר בנביא רק שלא ידע לקונן כנהוג ג\"כ דינא הכי:","(כח) צריך לחזור ולקרות - ואפילו השביעי רוצה להפטיר צריך לחזור ולקרות כיון שהפסיק בקדיש הנכנסים לא ידעו שזה המפטיר קרא מתחלה בתורה ואיכא בזיון לתורה כדאמרינן בגמרא דהמפטיר צריך שיקרא בתורה תחלה מפני כבוד התורה [היינו דאי המפטיר יפטיר בנביאים ויברך עליו ולא יקראו בתורה הרי אנו משוים דברי הנביאים לתורה בקריאה וברכה לכן צריך לקרות המפטיר בתורה תחלה ומזה יראו שהתורה עיקרית] ומ\"מ נכון יותר בעניננו שהפסיק בקדיש שיקרא המפטיר אחד מן הקודמים ולא השביעי:","(כט) יפטיר מי שעלה וכו' - היינו שיפטיר בנביא וא\"צ לחזור ולקרות בתורה אלא מה שקרא בשביעי בסיום הפרשה [או כשהוסיפו מי שקרא באחרון] עולה גם למפטיר דהא קי\"ל דהמפטיר עולה למנין שבעה וכדלקמיה בס\"ו והקדיש יאמר אחר קריאת הפטרה וברכותיה. כתב הפמ\"ג דה\"ה בכל מפטיר כששכח לומר הקדיש מקודם ונזכר אחר שכבר קרא המפטיר בתורה לא יאמר הקדיש עד לאחר קריאת הפטרה וברכותיה:","(ל) אם יודע - ואם השביעי אינו יודע ויצטרך לעלות למפטיר אחד מהקודמים אז בכל גווני צריך לחזור ולקרות ולברך בתורה לשם מפטיר:","(לא) לא יפטיר - ובשבת חזון במקום שהמנהג שקוראים הרב למפטיר לא יקראוהו מקודם לשלישי [מ\"א ותו\"ש] ועיין בא\"ר:","(לב) מי שעלה כבר - אם קראו לאדם לתורה בבית הכנסת אחרת ונזדמן לו אותה הפרשה שקרא היום צריך לחזור ולברך [אחרונים]:","(לג) א\"צ לקרות וכו' - ר\"ל שא\"צ לקרות עוד שביעי מלבד המפטיר דאחרי שאמר קדיש בסיום הפרשה אינו קורא אח\"כ רק לשם מפטיר לבד כמו שרגיל תמיד אחר הקדיש והוא יהיה עולה למנין שבעה אבל אם נזכר קודם שאמר הקדיש אז צריך לקרות אחד לשביעי ממה שקרא כבר ויסיים הפרשה עמו ויאמר קדיש ואח\"כ יחזור לקרות איזה פסוקים למפטיר כמו שרגיל תמיד:","(לד) אלא יקרא וכו' - וא\"צ לחזור ולומר קדיש:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"7\"></i>קרא הפרשה <i data-commentator=\"Turei Zahav\" data-order=\"6\"></i>בתפלת שחרית בשבת <i data-commentator=\"Magen Avraham\" data-order=\"18\"></i>ודילג <i data-commentator=\"Ba'er Hetev\" data-order=\"13\"></i>פסוק אחד חוזר וקורא הוא ושנים עמו אפילו הפטיר והתפלל מוסף חוזר וקורא:","m":["(לה) ודילג פסוק אחד - ה\"ה תיבה אחת אלא שדיבר בהוה:","(לו) חוזר וקורא - ויברך לפניה ולאחריה על הג' פסוקים ועיין לעיל סימן קל\"ז ס\"ג שם מבואר כל פרטי דין זה:"]}],"283":[{"s":"<b>למה אין מוציאין ב' ספרי תורות בשבת. ובו סעיף אחד:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>מה שאין מוציאין בשבת ספר שני לקרות פרשת המוספין מפני <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i>שאין בה אלא שני פסוקים:","m":["(א) שאין בה - ואין קורין בתורה פחות מג' פסוקים וכדלעיל סימן קל\"ז ולהצטרף עמה פסוקים שלא מענינו של יום אי אפשר והתוס' כתבו עוד טעם לפי שצריך להפטיר בנביא בכל שבת מענינו של יום ואי קרינן בשל שבת א\"כ יהא צריך להפטיר בדסליק מיניה והיינו מעניני שבת וא\"כ יהיו כל ההפטרות מענין אחד:"]}],"284":[{"s":"<b>דיני הפטורה וברכותיה. ובו ז סעיפים:</b><br><i data-commentator=\"Turei Zahav\" data-order=\"1\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>מפטירין <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>בנביא מעניינה של פרשה ואין פוחתין מכ\"א פסוקים אלא א\"כ סליק עניניה בבציר מהכי כגון עולותיכם ספו על זבחיכם: <small>הגה ודוקא בשבת בעינן כ\"א פסוקים ג' ג' פסוקים לכל א' מן הקרואים אבל ביו\"ט שקורין ה' סגי בט\"ו פסוקים (מהר\"ם פאדואה) ולא נתקנה ההפטורה רק בצבור אחר שקראו בתורה (תשובת הרמב\"ן סי' קצ\"ט) <i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"1\"></i>אבל בלאו הכי אסור לקרות עם הברכה שלפניה ולאחריה אבל <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>בלא ברכה שרי (ב\"י):</small>","m":["(א) מפטירין - כתב הלבוש תמהתי על שלא ראיתי נוהגין לכתוב ההפטרות כדין ספר כי היה נ\"ל שאין יוצאין כלל בקריאת ההפטרה בחומשים הנדפסין כיון שאין נכתבין בכל הלכות הס\"ת או מגילה והט\"ז ומ\"א יישבו המנהג וס\"ל דאף שהוא ע\"י דפוס וגם על הנייר ושלא בגלילה מותר לענין זה ומ\"מ דעת המ\"א דצריך לקרות ההפטרה מתוך נביא שלם הנדפס ולא מתוך הפטרה לבד הנדפסת בחומש וכן ג\"כ דעת הא\"ר ע\"ש ומ\"מ אם אין להם רק הפטרה הנדפסת בחומש יש לסמוך להקל שלא לבטל קריאת הפטרה אך לכתחלה בודאי ראוי ונכון שיהיה לכל צבור נביאים שנכתבין בקלף כדין שאז גם השמות נכתבים בקדושה משא\"כ כשהוא על הנייר הנדפס [עיין בא\"ר] וכן הנהיג הגר\"א בקהלתו וכעת נתפשט זה בהרבה קהלות ישראל ואשרי חלקם:","(ב) בנביא וכו' - והטעם מפני שפ\"א גזרו גזירה על ישראל שלא יעסקו בתורה וקראו בנביאים שבעה וברכו עליהם כנגד השבעה שהיו צריכים לעלות ולקרות בתורה ולא היו קורין עם כל אחד פחות מג' פסוקים והרי בין כולם כ\"א פסוקים לכך אע\"פ שהגזירה בטלה מנהגא לא בטל ומשו\"ה תקנו שהמפטיר יקרא בנביא לא פחות מכ\"א פסוקים ויהא קורא בתורה תחלה מפני כבוד התורה וכמ\"ש בסימן רפ\"ב במ\"ב סקכ\"ח ויברך המפטיר ז' ברכות [דהיינו שתי ברכות שמברך המפטיר על התורה לפניה ולאחריה ואחת על הנביא לפניה וארבע לאחריה] כנגד ז' שקראו בתורה:","(ג) אבל בלא\"ה - כגון שלא היה להם ס\"ת לקרות בה ואם קראו בס\"ת ונמצאת אחר הקריאה שהיא פסולה אפ\"ה מפטירין אחריה ומברכין הברכות לפניה ולאחריה ועיין בבה\"ל. אם אין עירוב שיכולין להביא הנביא או החומש בבהכ\"נ להפטיר הולכין עשרה ומפטירין בבית שמונח שם ובברכת ההפטרה ג\"כ דהרי מ\"מ קראו בתורה תחלה אע\"פ שלא היה באותו מקום:"]},{"s":" <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>אם חל ראש חדש בשבת אין המפטיר מזכיר של ר\"ח כלל <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>וי\"א שאע\"פ שאינו מזכיר בחתימה של ראש חדש מזכירין אותו בתוך הברכה שאומר את יום המנוח הזה ואת יום ראש החודש הזה והמנהג כסברא ראשונה:","m":["(ד) אין המפטיר וכו' - דאלמלא שבת אין נביא בר\"ח וקריאת הנביא הוא רק משום שבת:"]},{"s":" <i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>צריך לכוין לברכות הקוראים בתורה ולברכות המפטיר ויענה <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>אחריהם <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>אמן ויעלו לו להשלים מנין מאה ברכות שחיסר מניינם בשבת:","m":["(ה) צריך לכוין - וע\"כ מצוה על העולים שיברכו בקול רם כדי שכל הקהל ישמעו ויוכלו לענות אמן:","(ו) אחריהם אמן - דע\"י עניית אמן חשוב כאלו היה מברך לעצמו. אין לענות אמן אחר אמת וצדק שאומרים בברכות שאחר הפטרה שאין זה סיום ברכה וכן אין לענות אמן אחר הנאמרים באמת שנאמר בברכה שלפני ההפטרה דזהו ג\"כ ברכה אחת עם מה שאמר אח\"כ בא\"י הבוחר בתורה דזו היא חתימתה:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i> קטן יכול להפטיר: <small>הגה ואם קראו למפטיר מי שאינו יודע לומר ההפטרה <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>יכול אחר לאומרה אבל לכתחלה אסור לעשות כן:</small>","m":["(ז) מי שאינו יודע וכו' - היינו שקרא מתחלה הקטן בתורה לשם מפטיר ואח\"כ נמצא שאין יודע לומר ההפטרה וכן בגדול כה\"ג יכול אחר לומר ההפטרה וברכותיה דאף שתקנו שהמפטיר יקרא בתורה תחלה מפני כבוד התורה מ\"מ בדיעבד אמרינן שגם בזה איכא כבוד לתורה שניכר הדבר שקראו בתורה בתחלה לשם מפטיר שהרי הפסיק בקדיש מקודם והפמ\"ג כתב דאם יכול עכ\"פ לומר מלה במלה כשמקרין אותו טוב יותר שהוא בעצמו שקרא בתורה לשם מפטיר יאמר אח\"כ ההפטרה וברכותיה ג\"כ:","(ח) אבל לכתחלה וכו' - היינו שאין קורין למפטיר מי שלא ידע אח\"כ לקרות ההפטרה ג\"כ. ובזמנינו שהמנהג בכמה מקומות לכתוב נביאים על קלף ובגלילה כס\"ת וא\"כ הקורא בנביא הוא מוציא כל הצבור כקריאת ס\"ת ולכן אפילו לכתחלה מותר לקרות למפטיר אפילו מי שאינו יודע לקרות בנביא בעצמו דהוא יאמר כל הברכות והש\"ץ יקרא ההפטרה כמו שקורא בס\"ת [ח\"א]:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i>אם נשתתק המפטיר באמצע ההפטרה הבא לסיימה לא יתחיל ממקום שפסק הראשון <i data-commentator=\"Turei Zahav\" data-order=\"2\"></i>אלא צריך לחזור ולהתחיל ממקום שהתחיל הראשון <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i>כמו בס\"ת: <small>הגה <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i><i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"2\"></i>ושנים לא יאמרו ההפטרה <i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>בפעם אחת דתרי קלי לא משתמעי (ריב\"ש סי' ל\"ו ומגילה דף כ\"א):</small>","m":["(ט) כמו בס\"ת - ולענין ברכה לפניה יש דעות בריש סימן ק\"מ ע\"ש הטעם וה\"ה הכא ועיין בפמ\"ג שכתב דספק ברכות להקל ועיין במה שכתבנו בסימן ק\"מ בבה\"ל. ועיין שם בס\"א בהג\"ה דאפילו במקום שהש\"ץ קורא בס\"ת ג\"כ הדין דצריך להתחיל ממקום שהתחיל הראשון וה\"ה כאן:","(י) ושנים וכו' - גם לא יהיה נקרא ההפטרה ע\"י שנים דהיינו שאחד יקרא פסוק אחד והב' שותק עד שמסיים הפסוק ואח\"כ קורא השני פסוק אחר כי המפטיר שקרא בתורה צריך שיקרא הוא לבד כל ההפטרה [עט\"ז]:","(יא) לא יאמרו - עיין במ\"א דדוקא בקול רם אבל בלחש מותר לומר שבזה לא יטריד לחבירו שלא יוכל לשמוע וגם נכון לכתחלה לעשות כן לקרות בלחש מתוך הספר עם הקורא ועיין בפמ\"ג דמשמע דיראה לקרות מלה במלה עם הש\"ץ כדי שיציית להקורא ועיין בבה\"ל מה שכתבנו בשם שער אפרים ועיין בספר מעשה רב שכתב דהא דכתב המ\"א שיראה לקרות בלחש מתוך הספר עם הקורא היינו דוקא כשהקורא קורא מתוך החומש אבל כשקורא מתוך הנביא יקרא הוא לבד וכולם יהיו שומעין וע\"ש עוד שכתב דאם יקראו הכל בקול רם עם הקורא תהיה ברכת הקורא ברכה לבטלה:"]},{"s":" <i data-commentator=\"Magen Avraham\" data-order=\"6\"></i><i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"3\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"7\"></i>אין המפטיר מפטיר עד שיגמור <i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i>הגולל לגלול הספר תורה:","m":["(יב) אין המפטיר וכו' - היינו שאין רשאי להתחיל לומר ההפטרה עד שיגמור וכו' והטעם כדי שגם הגולל יתן לבו למה שיאמר המפטיר שחובה היא על כל אדם לשמוע פרשת ההפטרה כמו פרשה שבס\"ת וברש\"י שם משמע שצריך להמתין עד שיוגלל הס\"ת במטפחותיה אין לסלק מעל השלחן ספר הנביאים או החומש שקורין בו המפטיר עד אחר הברכה כדי שיראה ויברך על מה שהפטיר:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ח\" data-order=\"8\"></i>בשבת שהפרשיות מחוברות מפטירין בהפטרת פ' שניה: <small>הגה וע\"ל סי' תכ\"ח ונהגו להזכיר אחר קריאת התורה נשמות המתים ולברך <i data-commentator=\"Magen Avraham\" data-order=\"7\"></i>העוסקים בצרכי <i data-commentator=\"Ba'er Hetev\" data-order=\"5\"></i>צבור כל מקום לפי מנהגו (שבולי הלקט והגהות מרדכי פ\"ק דשבת) ונוהגים לומר יקום פורקן ואין בזה משום איסור תחינה בשבת גם נוהגים לומר אב הרחמים ובכל יום ) שאין אומרים בו צדקתך צדק אין אומרים אותו וכן כשיש חתונה או מילה ויש מקומות שאין אומרים אותו כשמברכין <i data-commentator=\"Ba'er Hetev\" data-order=\"6\"></i>החדש <i data-commentator=\"Be'er HaGolah\" data-label=\"•\" data-order=\"9\"></i>מלבד <i data-commentator=\"Magen Avraham\" data-order=\"8\"></i>בימי <i data-commentator=\"Ba'er Hetev\" data-order=\"7\"></i>הספירה והולכין בכל זה אחר המנהג:</small>","m":["(יג) שניה - שבה מסיימין את הקריאה:","(יד) וע\"ל סי' תכ\"ח - לענין הפטרת אחרי וקדושים כשהן מחוברות ויתר דיני הפטרה:","(טו) אחר קריאת התורה - לאפוקי אחר אשרי לא יאמר שום דבר דהקדיש שאומרים לפני העמוד קודם תפלת י\"ח הוא קאי על אשרי שאמר בתחלה וע\"כ אין להפסיק ביניהם ויהללו שאומרים אין הפסק. ומה שנשתרבב המנהג שכשיש חולה אוחז החזן הס\"ת בידו לאחר אשרי ואומר מי שבירך ומפסיק הרבה בין אשרי לקדיש שלפני העמוד שלא כדין הוא [פמ\"ג]:","(טז) ובכל יום שאין אומרים וכו' - ואם חל ט\"ב בשבת אע\"פ שאין אומרים צ\"צ אומרים א\"ה כ\"כ א\"ר בסי' תקנ\"ז והפמ\"ג בסי' תקנ\"ט כתב שג\"כ מזכירין בו נשמות אותן שמזכירין בכל שבת אבל בשבת שמברכין בו אב או בשבת שחל בו ר\"ח אב גופא א\"א אב הרחמים ואין מזכירין בו נשמות:","(יז) כשמברכין החודש - ואין מזכירין בו נשמות ואפילו במקום שאומרים אב הרחמים כגון בימי הספירה אפ\"ה אין מזכירין בו נשמות רק למי שנפטר באותו שבוע [מ\"א] והפמ\"ג כתב שכדומה שאין מזכירין אז נשמות כלל:","(יח) בימי הספירה - משום שהיו הגזרות באותו זמן ואפילו חל מילה בשבתות ההם דאיכא תרתי לטיבותא אפ\"ה אומרים דהא אומרים אותו בימי חדש ניסן כשמברכין חדש אייר דאית ביה נמי תרתי לטיבותא [וה\"ה אם יש מילה בניסן דאיכא ג' לטיבותא ג\"כ אומרים אותו דאין חילוק בין תרתי לטיבותא ובין ג' לטיבותא] אבל כשחל ר\"ח אייר בשבת אין אומרים אותו וכ\"ש שאין מזכירים בו נשמות וכן בכל חודש ניסן אף בימים שלאחר הפסח דהוא תוך הספירה ג\"כ אין מזכירין בו נשמות אבל אה\"ר אומרים בו כיון שהוא בימי הספירה: "]}],"285":[{"s":"<b>לקרות הפרשה שנים מקרא ואחד תרגום. ובו ז סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>אע\"פ שאדם שומע כל התורה כולה כל שבת בצבור <i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"1\"></i>חייב לקרות לעצמו בכל שבוע פרשת אותו שבוע <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i><i data-commentator=\"Eshel Avraham\" data-label=\"א\" data-order=\"1\"></i>שנים מקרא ואחד <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"1\"></i>תרגום <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i>אפילו <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>עטרות ודיבון:","m":["(א) לקרות לעצמו בכל שבוע - היינו שלא יקדים לקרות קודם אותו שבוע וגם לא יאחר דצריך להשלים פרשיותיו עם הצבור וכל המשלים פרשיותיו עם הצבור מאריכין לו ימיו ושנותיו [גמרא]:","(ב) שנים מקרא - אבל לא יקרא אחד מקרא ואחד תרגום ויכוין לשמוע מהש\"ץ אלא צריך לקרות ב\"פ מקרא חוץ ממה ששמע מהש\"ץ אם לא שקרא אז ג\"כ בפיו וע' במ\"א סק\"ח שכ' בשם לחם חמודות דבדיעבד יוצא פ\"א במה ששמע מהש\"ץ ויש אחרונים שמחמירין אפי' דיעבד. ובענין הקריאה יש דעות בזה בין אחרוני' י\"א שיקרא כל פסוק ב\"פ ותרגום עליו וי\"א שיקרא כל פרשה ב\"פ ואח\"כ התרגום היינו שיקרא כל פרשה פתוחה או סתומה ב\"פ ואח\"כ התרגום ובמ\"א ובשע\"ת מצדדים כדעה ראשונה ובספר מעשה רב איתא שהגר\"א נהג לומר התרגום אחר כל פרשה פתוחה או סתומה או אחר מקום שנראה יותר הפסק ענין ודעביד כמר עביד ודעביד כמר עביד. מי שהוא בקי בטעם ובנקודות בע\"פ טוב להדר לקרות בס\"ת גופא:","(ג) ודיבן - ר\"ל אע\"פ שאין בו תרגום וה\"ה ראובן ושמעון וכי\"ב צריך לקרותו ג\"פ ויש מחמירין דבעטרות ודיבן שיש בו תרגום ירושלמי צריך לקרות שם התרגום:"]},{"s":"<i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"2\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>אם למד הפרשה <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>בפירוש רש\"י חשוב <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i>כמו תרגום <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>וירא שמים יקרא <i data-commentator=\"Turei Zahav\" data-order=\"2\"></i>תרגום וגם <i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"3\"></i>פרש\"י:","m":["(ד) בפירוש רש\"י - שהוא מפרש את המקרא כמו שמפרש התרגום ויותר ממנו אבל אם קראה בשאר לעז שהוא מפרש רק את המלות לחוד לא יצא י\"ח במקום תרגום לפי שהתרגום מפרש כמה דברים שאין להבין מתוך המקרא:","(ה) חשוב כמו תרגום - וע\"כ יוצא במה שקורא שני פעמים מקרא ואחד פירוש רש\"י ואותן פסוקים שאין עליהם פירש\"י יקרא אותן ג\"פ. מי שאינו בר הכי שיבין את פירש\"י ראוי לקרות בפירוש התורה שיש בלשון אשכנז בזמנינו כגון ספר צאינה וראינה וכיוצא בו המבארים את הפרשה ע\"פ פירש\"י ושאר חכמינו ז\"ל הבנוים על יסוד התלמוד:","(ו) תרגום וגם פירש\"י - כי התרגום יש לו מעלה שניתן בסיני וגם הוא מפרש כל מלה ומלה ופירש\"י יש לו מעלה שהוא מפרש את הענין ע\"פ מדרשי חז\"ל יותר מהתרגום ובאמת כן ראוי לנהוג לכל אדם שילמוד בכל שבוע הסדרה עם פירש\"י לבד התרגום כי יש כמה פרשיות בתורה ובפרט בחלק ויקרא שא\"א להבינם כלל ע\"י תרגום לחוד מי שאין בידו תרגום רק החומש לבד יש לו יקרא שני פעמים מקרא ואח\"כ כשיזדמן לו תרגום יאמר. לא יקרא פסוק המאוחר קודם המוקדם אלא יקרא כסדר. לא יקרא התרגום תחלה ואח\"כ מקרא אלא יקרא לכתחלה שנים מקרא מקודם ואח\"כ תרגום. אם אפשר לו שלא יפסיק בשמו\"ת על שום דבר הוא טוב ויפה מאד וכן ראיתי מהמדקדקים עושין כן וכן ראוי לבעל נפש לעשות [שכנה\"ג בשם סדר היום וכ\"כ ש\"א]:"]},{"s":"<i data-commentator=\"Magen Avraham\" data-order=\"5\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>מיום ראשון ואילך חשיב עם הצבור:","m":["(ז) מיום ראשון ואילך - כיון שמתחילין במנחתא דשבתא לקרות פרשת שבוע הבא נחשב שוב הקורא כקורא עם הציבור וא\"כ מה שכתב המחבר מיום ראשון ואילך לאו דוקא הוא:","(ח) חשוב עם הציבור - כמה אחרונים כתבו דמן המובחר הוא לקרותה בע\"ש ועיין בשע\"ת ובספר מטה יהודה כתב דאם הוא קורא מתחלת השבוע והלאה הוא ג\"כ בכלל מצוה מן המובחר וכמו שכתב בב\"י דמוכח כן מדברי הרמב\"ם וכן בספר מעשה רב כתב בהנהגת הגר\"א שהיה נוהג תיכף אחר התפלה בכל יום לקרוא מקצת מהסדרה שנים מקרא ואחד תרגום ומסיים בע\"ש:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>מצוה מן המובחר שישלים אותה <i data-commentator=\"Magen Avraham\" data-order=\"6\"></i>קודם שיאכל <i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i>בשבת ואם לא השלים קודם אכילה <i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i>ישלים אחר אכילה עד המנחה <i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"7\"></i>וי\"א עד רביעי בשבת <i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"3\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ח\" data-order=\"8\"></i>וי\"א עד <i data-commentator=\"Magen Avraham\" data-order=\"7\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"5\"></i>שמיני עצרת <i data-commentator=\"Be'er HaGolah\" data-label=\"•\" data-order=\"9\"></i><small> (דהיינו בשמחת תורה שאז משלימים הצבור):</small>","m":["(ט) שישלים אותה וכו' - וכדאיתא במדרש שצוה רבי את בניו אל תאכלו לחם בשבת עד שתגמרו את כל הפרשה. ומ\"מ פשוט דאין לעכב מחמת זה האכילה עד אחר חצות וכדלקמן בסימן רפ\"ח דזהו רק מצוה בעלמא ולכתחלה מהנכון אם לא קרא שנים מקרא ואחד תרגום בע\"ש להשכים בשבת בבקר ולקרא השמו\"ת קודם הליכתו לבהכ\"נ [כן איתא באור זרוע ריש הלכות שבת וכ\"מ בתר\"י ריש ברכות ע\"ש]:","(י) עד המנחה - דממנחה ולמעלה מתחילין הצבור לקרות פרשת שבוע הבא:","(יא) עד רביעי בשבת - דג' ימים הראשונים שייכין עדיין קצת לשבת שעבר וכדלקמן בסימן רצ\"ט ס\"ו לגבי הבדלה לכן בדיעבד יכול להשלים:","(יב) עד שמיני עצרת - היינו בא\"י ששם עושין שמ\"ע רק יום אחד וגומרין הציבור אז הס\"ת ולכך בדיעבד מקרי עד יום ההוא משלים פרשיותיו עם הציבור אבל לכתחלה לכו\"ע לא יאחר יותר מיום השבת:","(יג) שאז משלימין הציבור - ויש לו לקרות אז שנים מקרא ואחד תרגום ודלא כאותן שקורין מקרא לחוד כיון שחסר לו גם התרגום:","(יד) בשעת קה\"ת - ובסימן קמ\"ו במ\"א סק\"ה הביא בשם השל\"ה שמחמיר בזה אלא הכל צריכין לשמוע הקריאה מפי הש\"ץ וכן הוא דעת הגר\"א שהובא בספר מעשה רב דצריך לשמוע כל תיבה ותיבה ולראות בחומש ולא יסייע להקורא כלל ומשמע שתפסו העיקר כדעת השבלי לקט בשם רבו והר\"מ שהובא בהגהות מיימוני ובב\"י שם דרק בין גברא לגברא מותר. ומ\"מ נראה דלקרוא בלחש מלה במלה עם הש\"ץ אין להחמיר בזה כיון שמכוין אז גם לשמוע כל תיבה מפי הש\"ץ והמ\"א הביא שם בשם מטה משה דלכתחלה נכון לעשות כן וכ\"כ כמה אחרונים:"]},{"s":"<i data-commentator=\"Magen Avraham\" data-order=\"8\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ט\" data-order=\"10\"></i>יכול לקרות הפרשה שנים מקרא ואחד תרגום בשעת קריאת <i data-commentator=\"Ba'er Hetev\" data-order=\"6\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"6\"></i>התורה <small> (וע\"ל סי' קמ\"ו):</small>","m":["(טו) וע\"ל סימן קמ\"ו - דשם מסיק המחבר בס\"ב דנכון להמדקדק בדבריו לכוין דעתו לשמעם מפי הקורא והוא משום דחשש ג\"כ לדעת הפוסקים שהבאתי למעלה:"]},{"s":"<i data-commentator=\"Magen Avraham\" data-order=\"9\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"י\" data-order=\"11\"></i>מלמדי <i data-commentator=\"Ba'er Hetev\" data-order=\"7\"></i>תינוקות אין צריכים לחזור ולקרות הפרשה בשבת:","m":["(טז) מלמדי תינוקות - ודוקא בימיהם שהיו לומדים פירוש המקרא עם התינוקות ולכך יוצאין בזה גם ידי תרגום וכדלעיל בס\"ב אבל אם לומד פירוש המלות לחוד לא יצא ידי תרגום אלא השני פעמים מקרא דבודאי קרא עם התינוקות שני פעמים ולכן צריך לומר תרגום בעצמו [מחה\"ש וכן מצדד הפמ\"ג]:","(יז) אין צריכין וכו' - מכאן שניגון הטעמים אינו מעכב לגבי שמו\"ת [פמ\"ג]:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"כ\" data-order=\"12\"></i><i data-commentator=\"Magen Avraham\" data-order=\"10\"></i>אין צריך לקרות <i data-commentator=\"Ba'er Hetev\" data-order=\"8\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"8\"></i>פרשת יו\"ט: <small>הגה וכן אין צריך לקרות ההפטרות (מרדכי ה\"ק) ומכל מקום נהגו לקרות <i data-commentator=\"Magen Avraham\" data-order=\"11\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"9\"></i>ההפטרה ובשבת של חתונה יקרא ההפטר' של שבת <i data-commentator=\"Magen Avraham\" data-order=\"12\"></i>ולא שוש <i data-commentator=\"Ba'er Hetev\" data-order=\"10\"></i>אשיש (פסקי מהרא\"י סי' ק\"א):</small>","m":["(יח) אין צריך - ר\"ל שאין צריך לקרות לעצמו שמו\"ת דהא כבר קרא כל התורה מדי שבת בשבתו וביום הו\"ר יקרא שמו\"ת פרשת וזאת הברכה ואם קרא ביום שמ\"ע לא הפסיד [שע\"ת]:","(יט) נהגו לקרות ההפטרה - טעם המנהג שמא יקראוהו למחר למפטיר ויהא בקי ורגיל בה משא\"כ בפרשיות של יו\"ט ששם החזן הוא הקורא [מ\"א]:","(כ) של שבת ולא וכו' - ר\"ל שיש מנהג באיזה מקומות שקורין בצבור לבד הפטרת הסדרה עוד איזה פסוקים מהפטרת שוש אשיש [משום דכתיב בה כחתן יכהן פאר וגומר] וקמ\"ל דבשעה שקורא לעצמו ההפטרה אין צריך לקרות אלו הפסוקים משום דהוא מצוי ושגור בפי הכל ובקי בהן בלא זו הקריאה. ובד' פרשיות יקרא הפטרה דד' פרשיות:\n"]}],"286":[{"s":"<b>דיני תפלת מוסף בשבת. ובו ה סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>זמן תפלת מוסף מיד אחר תפלת השחר <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>ואין לאחרה יותר מעד סוף שבע שעות ואם התפלל אותה אחר שבע שעות נקרא פושע ואע\"פ כן יצא ידי חובתו מפני שזמנה כל היום <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>ואם שכח ולא התפלל עד שעבר כל זמנה אין לה תשלומין <i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>ויש בה נשיאת כפים: <small>הגה ואם התפלל אותה <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i>קודם תפלת שחרית <i data-commentator=\"Eshel Avraham\" data-label=\"א\" data-order=\"1\"></i>יצא (אהל מועד בשם הרשב\"א ר\"י פ' תפלת השחר):</small>","m":["(א) אחר תפלת השחר - כמו קרבן מוסף שזמנו לכתחלה אחר התמיד:","(ב) מעד סוף וכו' - דעיקר זמן הקרבת המוסף היה לכתחלה עד סוף שבע:","(ג) אין לה תשלומין - כיון שנזכר בה קרבן מוסף וקרבן מוסף אין לה תשלומין משא\"כ שארי תפלות שלא נזכר בהם קרבן כלל יש להן תשלומין כמ\"ש סימן ק\"ח:","(ד) ויש בה נשיאת כפים - היינו דנושאין כפים במוסף כמו בשחרית וכנ\"ל בסימן קכ\"ט וע\"ש בסימן קכ\"ח סמ\"ד בהג\"ה דבכל מדינותינו אין נוהגין לישא כפים בשבת כלל:","(ה) יצא - דקרבן מוסף זמנו מתחלת היום עד הערב אלא דאסור להקדים שום קרבן לכתחלה לקרבן תמיד של שחר ובדיעבד יצא:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>כל יחיד חייב להתפלל תפלת המוספין בין אם יש צבור בעיר או לא: <small>הגה [ואח\"כ חוזר השליח צבור התפלה כמו בשאר תפלות] [ב\"י בשם שבולי לקט]:</small>","m":["(ו) כל יחיד וכו' - דלא תימא דהואיל דהוא במקום הקרבת הקרבן לא הוטלה המצוה רק על הצבור שבעיר ולא על היחיד קמ\"ל דלא אמרינן הכי:"]},{"s":"<i data-commentator=\"Turei Zahav\" data-order=\"2\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i>מותר <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"1\"></i>לטעום קודם תפלת המוספין דהיינו <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>אכילת <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>פירות או אפי' <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>פת מועט אפילו טעימה שיש בה כדי לסעוד הלב <i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"1\"></i>אבל סעודה <i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i>אסורה:","m":["(ז) אכילת פירות - ואע\"ג דלאחר תפלת שחרית כבר נתחייב בקידוש ואסור לאכול ולשתות מקודם ואין קידוש אלא במקום סעודה י\"ל דדי כשישתה כוס יין אחר הקידוש דגם זהו מקרי סעודה כנ\"ל סי' רע\"ג ואח\"כ יאכל הפירות או כשאין לו יין כ\"כ יש לסמוך על הפוסקים דס\"ל דדי כשישתה כל הכוס יין של קידוש שמחזיק רביעית דזהו מקרי ג\"כ קידוש במקום סעודה:","(ח) פת מועט - דהיינו כביצה דכ\"ז הוא בכלל אכילת עראי וכ\"ש אם אוכל מיני תרגימא מחמשת המינים דשרי:","(ט) כדי לסעוד הלב - דהיינו שאוכל פירות הרבה דאכילת פירות לא מקרי קבע ונראה דאם חלש לבו יכול גם פת לאכול עד שתתיישב דעתו אף שהוא יותר מכביצה. כתב בא\"ר והובא בשע\"ת דאם חלש לבו ואין לו יין ולא שאר דבר לקדש עליו רשאי לאכול פירות וה\"ה מיני תרגימא מה' מינים קודם מוסף אף בלי קידוש אבל בלא\"ה אין להקל:"]},{"s":"<i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"2\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"7\"></i>היו לפניו שתי תפלות אחת של מנחה ואחת של מוספים כגון שאיחר מלהתפלל תפלת מוסף עד שש שעות <small>[ומחצה טור] </small> שהוא זמן תפלת מנחה צריך להתפלל <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>של מנחה <i data-commentator=\"Eshel Avraham\" data-label=\"ב\" data-order=\"2\"></i>תחלה ואח\"כ של מוסף: <small>הגה ומיהו אם הקדים של מוסף יצא [ב\"י בשם הרשב\"א] </small> <i data-commentator=\"Be'er HaGolah\" data-label=\"ח\" data-order=\"8\"></i>וי\"א דהיינו דוקא שצריך עתה להתפלל שתיהן כגון שרוצה לאכול ואסור לו לאכול עד שיתפלל מנחה אבל אם אינו צריך עתה להתפלל מנחה יכול להקדים של מוסף: <small>הגה ומיהו אם הגיע זמן מנחה קטנה יתפלל מנחה <i data-commentator=\"Ba'er Hetev\" data-order=\"5\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"5\"></i>תחלה (הר\"י והרא\"ש בשם ירוש') </small> <i data-commentator=\"Be'er HaGolah\" data-label=\"ט\" data-order=\"9\"></i>ויש מי שהורה שאין עושין כן בצבור להקדים תפלת מנחה לתפלת מוסף כדי שלא יטעו:","m":["(י) של מנחה תחלה - שהוא תדיר:","(יא) יצא - דהא דתדיר קודם הוא רק למצוה ולכתחלה ולא לעיכובא בדיעבד:","(יב) כגון שרוצה לאכול - לפי מה דמסיק הרמ\"א לעיל בסימן רל\"ב ס\"ב בהג\"ה אין לאסור לאכול קודם מנחה כשהגיע זמן מנחה גדולה אלא בסעודה גדולה וסעודת שבת לא מקרי סעודה גדולה [כ\"א סעודת נשואין או ברית מילה] ולא חיישינן שמא יפשע ובפרט האידנא דסומכין על קריאה לבהכ\"נ למנחה א\"צ להתפלל עתה מנחה:","(יג) אם הגיע וכו' - ואם הוא סמוך לערב ואין לו שהות להתפלל שתיהן יתפלל מוסף דמנחה יש לה תשלומין בערבית משא\"כ במוסף ובספר דגול מרבבה חולק עליו מהירושלמי שמפורש להיפוך וכן הקשה עליו בספר בית מאיר ובחידושי הגרע\"א מיישבו בדוחק:","(יד) שלא יטעו - פי' בשאר ימים להתפלל מנחה קודם מוסף אפילו קודם חצות:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"י\" data-order=\"10\"></i>בשבת ויו\"ט אין אומרים ברכו אחר קדיש בתרא <small> (וע\"ל סי' קל\"ג):</small>","m":["(טו) וע\"ל סי' קל\"ג - ברמ\"א דשם נתבאר היטב דין זה:"]}],"287":[{"s":"<b>ניחום אבלים וביקור חולים בשבת. ובו סעיף אחד:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>יכולים <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>לנחם אבלים בשבת וכן יכולים לבקר את החולה <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>ולא יאמר לו כדרך שאומר לו בחול אלא אומר לו שבת היא מלזעוק <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>ורפואה קרובה לבא <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>ורחמיו מרובים ושבתו בשלום: <small>הגה וי\"א דא\"צ לומר ורחמיו מרובים וכן נהגו (רמב\"ם פכ\"ד):</small>","m":["(א) יכולים וכו' - אמרינן בגמרא בקושי התירו לנחם אבלים ולבקר חולים בשבת וע\"כ לא יפה עושין אותן שכל ימי השבוע אין הולכין רק בשבת:","(ב) כדרך שאומר לו בחול - דמצטער ומעורר הבכי דאסור בשבת:","(ג) אומר לו וכו' - אבקור חולים קאי ובנחום אבלים יאמר לו שבת היא מלנחם ונחמה קרובה לבוא ויש מקילים דרשאי לומר המקום ינחמך. כתב בפמ\"ג אם בא האבל לבהכ\"נ אחר אמירת מזמור שיר ליום השבת שוב לא יקרא השמש צאו נגד האבל דאין להזכיר אבילות בפרהסיא ומ\"מ לילך בעצמו לו לומר שבת היא מלנחם וכו' רשאי:\n"]}],"288":[{"s":"<b>דין תענית ודין תענית חלום בשבת. ובו י סעיפים:</b><br><i data-commentator=\"Magen Avraham\" data-order=\"1\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>אסור להתענות בשבת <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>עד ו' שעות: <small>[הגה ואפי' לומד ומתפלל אסור] [מרדכי פ\"ק דשבת]:</small>","m":["(א) עד ו' שעות - דגם בחול האוכל אחר ו' שעות הוי כזורק אבן לחמת ע\"כ נקרא כמו תענית בשבת. ולשם תענית אפילו שעה אחת אסור וע\"כ שלא כדין עושין מקצת קהלות שמתענים בשבת עד סמוך לחצות על הגזרות ואם טעים מידי קודם תפלת מוסף מותר להתאחר יותר משש שעות [פמ\"ג]:","(ב) ומתפלל אסור - ולפ\"ז הש\"ץ שמנגן ואין יוצאין מבהכ\"נ עד אחר שש שלא כהוגן הוא ובפרט בחורף שהימים קצרים ומכ\"ש ביו\"ט מלבד בר\"ה [ב\"ח] ובא\"ר מצא סמך להקל בלומד ומתפלל להתאחר עד אחר חצות ובבגדי ישע שעל המרדכי פ\"ק דשבת כתב ג\"כ שמותר ללמוד ולהתפלל עד חצות:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>י\"א שאדם שמזיק לו האכילה דאז עונג הוא לו שלא לאכול לא יאכל: <small>הגה <i data-commentator=\"Turei Zahav\" data-order=\"2\"></i>וכן מי שיש לו עונג אם יבכה כדי שילך <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>הצער מלבו מותר לבכות בשבת (אגור בשם שבולי הלקט):</small>","m":["(ג) לא יאכל - וכמעט קרוב לאיסור האכילה כיון שמשער שיזיק לו [פמ\"ג ותו\"ש] והיינו אם גם כזית קשה לו לאכול ועיין לקמן בסימן רצ\"א ס\"א בהג\"ה:","(ד) הצער מלבו - כתב הט\"ז היינו דוקא אם מחמת רוב דביקותו בהקב\"ה זולגים עיניו דמעות שכן מצינו ברע\"ק בזוהר חדש שהיה בוכה מאד באמרו שיר השירים באשר שידע היכן הדברים מגיעים וכ\"ה מצוי במתפללים בכונה אבל סתם לבכות כדי שיצא הצער מלבו לא ע\"ש אבל בא\"ר ותו\"ש התירו כיון שע\"י בכיתו ירוח לו:","(ה) ואכילה וכו' - אבל כשאין לו צער אף שמתענה על עונות ומחמת תשובה אסור:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>אדם המתענה בכל יום ואכילה בשבת צער הוא לו מפני שינוי וסת <small> (פי' דבר קבוע) </small> יש אומרים שראו כמה חסידים ואנשי מעשה שהתענו בשבת מטעם זה וכן אמרו שכך היה עושה ה\"ר יהודה החסיד:","m":[]},{"s":"<i data-commentator=\"Magen Avraham\" data-order=\"2\"></i><i data-commentator=\"Turei Zahav\" data-order=\"3\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>מותר <i data-commentator=\"Eshel Avraham\" data-label=\"א\" data-order=\"1\"></i>להתענות בו <i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>תענית חלום כדי שיקרע גזר דינו <i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"1\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>וצריך <i data-commentator=\"Eshel Avraham\" data-label=\"ב\" data-order=\"2\"></i>להתענות <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i>ביום ראשון כדי שיתכפר לו מה שביטל עונג שבת <i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i>ואם תשש כחו ואינו יכול להתענות שני ימים רצופים לא יתענה ביום ראשון ויתענה אח\"כ: <small>הגה וכ\"ש אם היה ביום ראשון <i data-commentator=\"Ba'er Hetev\" data-order=\"5\"></i>חנוכה או פורים או יו\"ט אפי' <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i>יו\"ט שני של גליות שאין להתענות עד אח\"כ. יש אומרים מי שישן שינת צהרים וחלם לו חלום רע <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i>יתענה מחצי <i data-commentator=\"Ba'er Hetev\" data-order=\"6\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"6\"></i>היום עד <i data-commentator=\"Eshel Avraham\" data-label=\"ג\" data-order=\"3\"></i>חצי הלילה ואז יבדיל <i data-commentator=\"Magen Avraham\" data-order=\"6\"></i>וביום הראשון יתענה כאלו התענה כל יום השבת (מצאתי כתוב):</small>","m":["(ו) מותר להתענות - ואם חבירו ראה עליו חלום רע בשבת וסיפר לו לא יתענה אבל אם אירע כן בחול יתענה [כנה\"ג מ\"ב ומ\"א וא\"ר עיין שם] ועיין לעיל בסימן ר\"כ במ\"א סק\"ב דמי שחלם לו חלום קשה על חבירו יתענה והביאו כאן גם הא\"ר ע\"ש ומשמע שהחולם בעצמו יתענה כיון שהוא בחול ואולי דשם מיירי שאינו רוצה לספר לו לצערו:","(ז) תענית חלום - וגם יבלה כל היום בתורה ובתפלה ויתכפר לו ובסדר היום כתב דיוכל להתודות על עונותיו כשמתענה כמו בחול. ועיין לעיל בסימן ר\"כ במ\"ב דעוברות ומניקות אין להורות להן להתענות אפילו בחול אלא יתנו פדיון נפשם לצדקה ובפרט אם הן חלושות בודאי אין להן להחמיר על עצמן. כתב הט\"ז אם הרהר ביום וחלם לו בלילה מענין ההרהור אין לו להתענות בשבת דההרהור גרם זה ולא הראוהו מן השמים:","(ח) ביום ראשון - ואם ביום ראשון הוא תענית חובה כגון י\"ז בתמוז וכדומה או אפילו תענית יחיד שנהג בו חובה כגון שיש לו מנהג קבוע תמיד להתענות יום ראשון של סליחות אינו עולה לו כיון שאף אם לא היה מתענה בשבת היה מתענה יום זה וצריך ליתן יום אחר ויש חולקין ע\"ז וס\"ל דאף תענית חובה שהוא ביום ראשון עולה לו ויכוין ביום התענית חובה שיהיה לו כפרה על מה שהתענה ביום השבת ומי שקשה לו התענית יכול לסמוך על המקילין דעולה לו:","(ט) חנוכה וכו' - דוקא אלו הימים שמדינא אסור להתענות בהם אבל אם יום ראשון הוא יום שאיסור התענית בו אינו אלא מנהג כגון יומי דניסן או סיון או אסרו חג או בין יוה\"כ לסוכות וכה\"ג יכול להתענות בהם תענית לתעניתו וגם אם התענה בהם תענית חלום א\"צ למיתב אח\"כ תענית לתעניתו אבל המתענה תענית חלום בר\"ח וחנוכה ופורים ויו\"ט שני של גליות וחוה\"מ צריך למיתב תענית לתעניתו [אחרונים]:"]},{"s":"<i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"2\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"7\"></i>יש אומרים שאין להתענות תענית חלום בשבת אלא על חלום שראהו תלת זימני <i data-commentator=\"Be'er HaGolah\" data-label=\"ח\" data-order=\"8\"></i>וי\"א שבזמן הזה אין להתענות תענית חלום בשבת שאין אנו בקיאין בפתרון חלומות לידע איזה טוב ואיזה רע <i data-commentator=\"Be'er HaGolah\" data-label=\"ט\" data-order=\"9\"></i>והעולם אומרים שנמצא בספרים קדמונים <i data-commentator=\"Magen Avraham\" data-order=\"7\"></i>שעל שלשה חלומות <i data-commentator=\"Eshel Avraham\" data-label=\"ד\" data-order=\"4\"></i>מתענים בשבת ואלו הן <i data-commentator=\"Magen Avraham\" data-order=\"8\"></i>הרואה <i data-commentator=\"Ba'er Hetev\" data-order=\"7\"></i>ספר תורה שנשרף <i data-commentator=\"Ba'er Hetev\" data-order=\"8\"></i>או יום הכפורים בשעת נעילה או <i data-commentator=\"Magen Avraham\" data-order=\"9\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"9\"></i>קורות ביתו או שיניו שנפלו ויש אומרים הרואה יוה\"כ אפי' שלא בשעת נעילה וי\"א הרואה שקורא בתורה ויש אומרים הרואה שנושא אשה והא דרואה שיניו שנפלו דוקא שיניו אבל הרואה לחייו שנשרו חלום טוב הוא דמתו היועצים עליו רעה ונראה לי שהחלומות שאמרו בפרק הרואה <i data-commentator=\"Magen Avraham\" data-order=\"10\"></i>שהם <i data-commentator=\"Ba'er Hetev\" data-order=\"10\"></i>רעים גם עליהם מתענין בשבת:","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"י\" data-order=\"10\"></i>המתענה בשבת <i data-commentator=\"Magen Avraham\" data-order=\"11\"></i>אומר עננו אחר סיום תפלתו בלא חתימה וכוללו באלהי נצור: <small>הגה <i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"3\"></i>ויאמר אחר תפלתו רבון העולמים גלוי כו' כמו בחול (א\"ז הלכות תענית):</small>","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"כ\" data-order=\"11\"></i>אם הקדימה לאכול הוא עונג לו כגון שנתעכלה סעודת הלילה יקדים ואם האיחור עונג לו כגון שעדיין לא נתעכלה יאחר: <small>הגה וכן מי שיש לו סעודות כל יום כמו בשבת ישנה בשבת <i data-commentator=\"Magen Avraham\" data-order=\"12\"></i>להקדים <i data-commentator=\"Ba'er Hetev\" data-order=\"11\"></i>או לאחר (גמרא פ' כ\"כ וטור):</small>","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ל\" data-order=\"12\"></i>אין מתענין <i data-commentator=\"Magen Avraham\" data-order=\"13\"></i>על שום צרה <i data-commentator=\"Ba'er Hetev\" data-order=\"12\"></i>מהצרות כלל:","m":[]},{"s":"אין צועקים ולא מתריעין בו על שום צרה <i data-commentator=\"Be'er HaGolah\" data-label=\"מ\" data-order=\"13\"></i>חוץ מצרת המזונות שצועקים עליה בפה בשבת ולא בשופר <i data-commentator=\"Be'er HaGolah\" data-label=\"נ\" data-order=\"14\"></i>וכן עיר שהקיפוה עכו\"ם או נהר וספינה המטורפת בים <i data-commentator=\"Be'er HaGolah\" data-label=\"ס\" data-order=\"15\"></i>ואפי' על יחיד הנרדף מפני עכו\"ם או לסטים או רוח רעה <i data-commentator=\"Be'er HaGolah\" data-label=\"ע\" data-order=\"16\"></i>זועקין ומתחננין בתפילות בשבת אבל אין תוקעין <i data-commentator=\"Be'er HaGolah\" data-label=\"פ\" data-order=\"17\"></i>אא\"כ תוקעין לקבץ העם לעזור אחיהם ולהצילם <small> (וע\"ל סי' תקע\"ו סי\"ג):</small>","m":["(י) או ר\"ח - ודוקא שאר ראשי חדשים אבל בר\"ח ניסן דעת המ\"א דיכול להתענות בו מפני שהוא תענית צדיקים עסי' תק\"פ ובתו\"ש חולק עליו דהא כתב המ\"א שם לקמן דמי שאינו רגיל להתענות תענית צדיקים ואירע לו איזו צרה ח\"ו אל יתענה בו:","(יא) עד אח\"כ - וצריך בכל זה להקדים כל מה שיכול:","(יב) מחצי היום - ואעפ\"כ אינו מתפלל עננו אח\"כ:","(יג) עד חצי הלילה - ויש מקילין שלא יתענה רק עד הלילה ויש לסמוך ע\"ז כשהיה יו\"ט במוצאי שבת [א\"ר] ואם חלם לו בתחלת הלילה וננער השל\"ה החמיר שלא לטעום גם בלילה והביאו המ\"א בסי' תקס\"ד והא\"ר צידד להתיר שהתענית אינו מתחיל רק כשיאיר היום:","(יד) וביום ראשון יתענה - ואפילו אם חלם לו אחר שכבר קיים סעודה ג' אחר חצי היום וא\"כ אפילו בלא החלום אי בעי שלא לאכול עוד הרשות בידו מ\"מ כיון שהתענה לשם תענית עבירה היא בידו וצריך למיתב תענית ע\"ז:","(טו) שעל שלשה חלומות מתענין - ואף באלו הג' אין להתענות בשבת אא\"כ התענית עונג לו כגון שנפשו עגומה עליו וכשיתענה ימצא נחת רוח לאפוקי אם הוא אדם דלא קפיד בחלום רע או שהתענית קשה עליו ומצטער יותר בתעניתו ממה שמצטער בפחד החלום אסור להתענות בשבת (ריב\"ש) ובשם של\"ה כתבו האחרונים שאף באלו הג' היה רגיל על הרוב לפסוק שלא להתענות בשבת אלא יתענה ב' ימים בחול נגד יום השבת ויום ראשון שאחריו:","(טז) ס\"ת - וה\"ה תפלין שיש בהן פרשיות שבתורה אבל נביאים וכתובים משמע דלא [פמ\"ג] ומש\"כ שנשרף לאפוקי אם רואה שנפל מידו:","(יז) קורות ביתו - ובמדרש רבה איתא שפתרו לאשה שתלד זכר וכן הות לה:","(יח) או שיניו - ואם היה לו כאב שינים לא יתענה כמו שכתב הט\"ז במהרהר [שע\"ת]:","(יט) שהחלומות שאמרו - ופשוט דגם בזה דוקא אם נפשו עגומה עליו וכדלעיל:","(כ) שהם רעים - ולא יתענה על חלומות שהם הפסד ממון אלא דוקא על דברים שמחללין עליהם שבת:","(כא) גם עליהם וכו' - וצריך האדם לדקדק שהרבה דברים הולכים אחר השם בלשון כגון שונרא שינרא ע\"ש בגמרא:","(כב) אחר סיום תפלתו - היינו קודם יהיו לרצון. כתבו האחרונים דמותר לומר בשבת אלהי עד שלא נוצרתי וכו' יהי רצון וכו' דאינו אסור שאלת צרכיו אלא כשמבקש על חולי או פרנסה ודומה לו שיש צער לפניו אבל חרטת עונות טוב לומר בכל יום כיון שאינו בלשון וידוי:","(כג) ישנה בשבת - כדי שיהיה מינכר שהוא לכבוד שבת:","(כד) להקדים או לאחר - פי' שעה מועטת אבל לאחר הרבה אין נראה שיהא רעב בשבת:","(כה) על שום צרה - היינו אפי' על אותן שמבואר בסמוך שזועקין ומתחננין עליהן:","(כו) מהצרות - כשיש מאורע וצריך אדם לרחמים מותר לבקש וליפול על פניו ביחיד [מ\"א]:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"צ\" data-order=\"18\"></i>נרדף מפני רוח רעה שאמרו לאו דוקא דה\"ה לכל חולי שיש בו סכנת היום <i data-commentator=\"Turei Zahav\" data-order=\"4\"></i>זועקים ומתחננין וכן נהגו לומר מצלאים בשבת על חולים המסוכנים סכנות היום: <small>הגה וכן <i data-commentator=\"Turei Zahav\" data-order=\"5\"></i>מותר לברך <i data-commentator=\"Ba'er Hetev\" data-order=\"13\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"13\"></i><i data-commentator=\"Magen Avraham\" data-order=\"14\"></i>החולה המסוכן בו ביום. (ליקוטי מהר\"י ברין וב\"י בשם הר\"ן פרק ג' דתענית):</small>","m":["(כז) מפני רוח רעה - שנכנס בו רוח שד ורץ והולך שמא יטבע בנהר או יפול וימות או שהוא חולה ממיני החלאים [ר\"ן]:","(כח) המסוכן בו ביום - אבל מי שאינו מסוכן לא וכשעושין מי שבירך לחולה שאין בו סכנה אומר שבת היא מלזעוק ורפואה קרובה לבוא. ולברך המקשה לילד בודאי מותר דהא בכלל מסוכנת היא וכן היולדת בתוך שבוע ראשון ג\"כ נראה דלכו\"ע אין להחמיר: "]}],"289":[{"s":"<b>סדר סעודת שחרית של שבת. ובו ב סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>יהיה שלחנו ערוך ומטה <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>מוצעת יפה ומפה פרוסה כמו בסעודת הלילה <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>ויברך על היין בורא פרי הגפן והוא נקרא <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>קידושא רבה <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>ואח\"כ יטול ידיו <small> (וע\"ל סי' רע\"א סעיף י\"ב בהג\"ה) </small> <i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>ויבצע על לחם משנה כמו בלילה ויסעוד <i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>וגם זה הקידוש צריך שיהיה במקום סעודה ושלא יטעום קודם לו כלום כמו בקידוש הלילה <i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i>ומיהו לשתות מים בבקר קודם תפלה מותר מפני שעדיין לא חל עליו חובת קידוש: <small>הגה וע\"ל כל דיני קידוש סי' רע\"א רע\"ב רע\"ג:</small>","m":["(א) ומטה מוצעת - היינו מע\"ש או כדי שיישן בה בשבת או שהוא בחדר שדר שם ואיכא בזיון אם לא יציע המטות אבל בלא\"ה אסור [אחרונים] ומה שכתב ומפה פרוסה עיין לעיל ברע\"א מ\"ב סקמ\"א:","(ב) ויברך וכו' - יש נוהגין לפתוח מתחלה פסוק ושמרו בני ישראל וגו' או זכור את יום השבת עד ויקדשהו ויש מההמון שפותחין מעל כן ברך וגו' ושלא כדין הוא דכל פסוקא דלא פסקיה משה אנן לא פסקינן:","(ג) קידושא רבא - ונקרא בלשון זה שהוא כמו שקורין סגי נהור מפני שזה הקידוש אינו כלל דאורייתא רק שתקנוהו לכבוד שבת ואסמכוהו אקרא כדאיתא בגמרא:","(ד) וע\"ל סימן רע\"א סי\"ב וכו' - היינו דשם מבואר בהג\"ה דנוטלים לידים קודם קידוש ועיין שם במ\"ב דכמה אחרונים כתבו שם דטוב יותר לנהוג כדעת המחבר:","(ה) ויסעוד - כתב ברוקח סימן נ\"ד אחר שאכלו כל צרכן יש מזמרים זמירות ושבח להקב\"ה. וטוב ללמוד תורה במקצת קודם אכילה [א\"ר]:","(ו) ושלא יטעום קודם לו וכו' - וגם הנשים שייכים בענין זה דכל מילי דשבת איש ואשה שוין [אחרונים]:","(ז) לא חל עליו וכו' - דקידוש אין שייך אלא בזמן הסעודה ומשום קודם התפלה לא שייך במים וכדלעיל בסימן פ\"ט:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"7\"></i>במקום שאין יין מצוי <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i><i data-commentator=\"Turei Zahav\" data-order=\"1\"></i>הוי שכר ושאר משקין חוץ מהמים <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>חמר מדינה ומקדשין עליו <i data-commentator=\"Be'er HaGolah\" data-label=\"ח\" data-order=\"8\"></i>ואם אין לו אפילו שכר ושאר משקין <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i>אוכל בלא <i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"3\"></i>קידוש:","m":["(ח) במקום שאין יין מצוי - משמע דבמקום שהוא מצוי אין לקדש על השכר ושאר משקין ועיין לעיל בסי' רע\"ב סקכ\"ט במ\"ב מה שכתבנו שם דנוהגין להקל בזה בשחרית במדינותינו ומ\"מ מצוה מן המובחר על היין הוא ולענין יי\"ש ע\"ש בד\"ה על שכר:","(ט) חמר מדינה - ומשקה שאינו חמר מדינה הסכימו הרבה אחרונים דאין מקדשין אפילו בשחרית דדומיא דקידוש הלילה תקנוה ופרטי הדין של חמר מדינה מבואר לקמן בסימן רצ\"ו במ\"ב לענין הבדלה וה\"ה כאן:","(י) אוכל בלא קידוש - פי' כשיש לו פת [ואפילו חתיכת פת ולא פת שלם] אומר המוציא על הפת ואסור לאכול דבר אחר קודם לכן לדעת קצת פוסקים ואם אין לו גם פת אוכל בלא קידוש ואין לו לבטל מצות עונג שבת בשביל זה ובלילה אם אין לו חתיכת פת ויין ושאר משקין לקדש עליו ויש לו תבשיל ופירות וכיוצא בו י\"א דאם מצפה שיביאו לו איזה דבר לקדש עליו ימתין איזה שעות ועכ\"פ א\"צ להמתין יותר מחצות ואם הוא אדם חלש א\"צ להמתין ויאכל מה שיש לו בלא קידוש ויסמוך על מה שהזכיר קדושת היום בתפלה ולכשיביאו לו אח\"כ בלילה פת או יין אומר עליו כל נוסח הקידוש ויסעוד כזית עכ\"פ:"]}],"290":[{"s":"<b>בשבת ישלים מאה ברכות בפירות. ובו ב סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"1\"></i>ירבה פירות ומגדים ומיני ריח כדי להשלים מנין <i data-commentator=\"Eshel Avraham\" data-label=\"א\" data-order=\"1\"></i>מאה ברכות: <small>הגה ואם רגיל בשינת <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"1\"></i>צהרים אל יבטלנו כי עונג הוא לו (טור):</small>","m":["(א) ירבה בפירות וכו' - וגם בליל ש\"ק טוב שישלים בם המאה ברכות:","(ב) מנין מאה ברכות - כי בכל יום מברך אדם מאה ברכות וכדאיתא לעיל בסימן רמ\"ו ס\"ג עי\"ש במ\"ב ועתה שנחסר לו כמה ברכות שבתפלת שבת יש רק ז' ברכות וע\"כ ישתדל להשלימם:","(ג) אל יבטלנו - ומ\"מ לא ירבה בו יותר מדאי שלא יביאנו לידי ביטול תורה שאפילו ת\"ח שלומדים כל השבוע שמצוה שיתענגו ביותר וכדלקמיה בהג\"ה אין הפי' שיבלו כל היום בתענוגים רק ימשכו יותר בתענוג משאר בני אדם. כתבו הספרים בשם הזוהר שמצוה על האדם לחדש חידושי תורה בשבת. ומי שאינו בר הכי לחדש ילמוד דברים שלא למד עד הנה:","(ד) כי עונג וכו' - אבל לא יאמר נלך ונישן כדי שנוכל לעשות מלאכתנו במו\"ש שמראה בזה שנח וישן בשביל ימות החול:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>אחר סעודת שחרית קובעים מדרש לקרות בנביאים <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>ולדרוש בדברי אגדה <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>ואסור לקבוע סעודה באותה שעה: <small>הגה ופועלים ובעלי בתים שאינן עוסקים בתורה כל ימי שבוע יעסקו יותר בתורה בשבת מתלמידי חכמים העוסקים בתורה כל ימי השבוע ותלמידי חכמים ימשיכו יותר בעונג אכילה ושתיה קצת שהרי מתענגים בלמודם כל ימי השבוע: [ב\"י סי' רפ\"ח בשם ירושלמי]:</small>","m":["(ה) קובעים מדרש וכו' - דאיתא במדרש אמרה תורה לפני הקב\"ה רבש\"ע כשיכנסו ישראל לארץ זה רץ לכרמו וזה רץ לשדהו אני מה תהא עלי אמר לה יש לי זוג שאני מזווג לך ושבת שמו שהם בטלים ממלאכתם ויכולים לעסוק בך [טור]:","(ו) ולדרוש וכו' - והעיקר יהיה אז ללמד לרבים את חקי האלהים ואת תורותיו להורות הלכות שבת והאסור והמותר גם להמשיך לב השומעים באגדה המדריכים את האדם ליראת שמים וכדאיתא בילקוט ר\"פ ויקהל אמר הקב\"ה למשה עשה לך קהלות גדולות ודרוש לפניהם ברבים הלכות שבת וכו' להורות לישראל איסור והיתר וכו' ולא כמו שנוהגין עכשיו [ב\"ח ומ\"א]:","(ז) ואסור לקבוע וכו' - בגמרא איתא בתלת מילי נחתי בע\"ב מנכסייהו וחד מנייהו דקבעי סעודתא בשבתא בעידן בי מדרשא והענין כדאיתא בירושלמי [הובא בב\"י רפ\"ח] לא ניתנו שבתות ויו\"ט לישראל אלא כדי לעסוק בהם בתורה מפני שכל ימות החול הם טרודים במלאכתם ואין להם פנאי לעסוק בה בקביעות ובשבת הם פנוים ממלאכה ויכולים לעסוק בה כראוי לפיכך אסור לו לפנות עצמו מד\"ת ולקבוע סעודתו בשעה שדורשין בבהמ\"ד דברי תורה ברבים אלא יקדים אותה או יאחר אותה. וזהו תוכחת מגולה לאותן האנשים שמטיילין בעת ההיא בשוקים וברחובות כי אפילו סעודת שבת שהיא מצוה אסור אז מפני בטול תורה וכ\"ש לטייל ולהרבות אז בשיחה בטלה שאסור:","(ח) סעודה באותה שעה - ולאכול בלי קביעות סעודה כמו שרגיל בימות השבת נראה שמותר וכנ\"ל בסימן רמ\"ט ס\"ב לענין ע\"ש עיין שם. והנה כיון שהטעם שאסרו חז\"ל קביעות סעודה אז הוא מפני שיתבטל עי\"ז מתורה וכנ\"ל ממילא נשמע דמכ\"ש שצריך ליזהר שלא יגרום עי\"ז ביטול ת\"ת דרבים כגון מה שמצוי בעו\"ה לאיזה אנשים שמזרזין להעולם בשבת בקיץ אף שעוד היום גדול להתפלל מנחה ולקיים הסעודה ג' וגורמים שכל אנשי בהמ\"ד יפסיקו מלמודם וכבר אחז\"ל [בשבת קי\"ח] אמר ר' יוסי יהא חלקי ממושבי בהמ\"ד ולא ממעמידי בהמ\"ד אם לא שלא ישאר זמן להתפלל מנחה ולקיים הסעודה שלישית ביום כדין אז בודאי נכון לזרז לזה. אין להמשיך הדרשה שיבטל עי\"ז סעודה שלישית:"]}],"291":[{"s":"<b>דין שלש סעודות. ובו ו סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>יהא זהיר מאוד לקיים סעודה שלישית <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>ואף אם הוא שבע יכול לקיים אותה <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>בכביצה <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>ואם אי אפשר לו כלל לאכול אינו חייב לצער את עצמו <i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>והחכם עיניו בראשו שלא ימלא בטנו בסעודת הבוקר כדי ליתן מקום לסעודה שלישית: <small>הגה ומי שלא אכל <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"2\"></i>בליל שבת יאכל שלש סעודות ביום השבת (הרא\"ש פ' ע\"פ):</small>","m":["(א) יהא זהיר מאד - וכדאיתא בגמרא חייב אדם לאכול ג' סעודות בשבת ואסמכוהו אקרא דכתיב ויאמר משה אכלוהו היום כי שבת היום לה' היום לא תמצאוהו בשדה ותלתא היום כתוב בקרא זה ואחז\"ל כל המקיים שלש סעודות בשבת ניצול משלש פורעניות מחבלו של משיח ומדינה של גיהנם וממלחמת גוג ומגוג שנאמר וגו'. ואף לעני העובר ממקום למקום צריך ליתן לו כל הג' סעודות בשבת וכדאיתא ביו\"ד בסי' ר\"נ ועיין לעיל בסימן רמ\"ב במ\"ב דאף בשביל סעודה שלישית כשמשיג באיזה מקום ללוות צריך ללוות:","(ב) בכביצה - לאו דוקא אלא מעט יותר מכביצה דכביצה מקרי עדיין אכילת עראי כמ\"ש סוף סימן רל\"ב ולא חשיב סעודה [מ\"א] וי\"א שאפילו בכזית יוצא ידי הסעודה ונכון להחמיר לכתחלה אם אפשר לו:","(ג) אינו חייב וכו' - דהסעודה לעונג ניתנה ולא לצער:","(ד) ליתן מקום - דאל\"כ לפעמים היא אכילה גסה ואינה חשובה אכילה:","(ה) בליל שבת וכו' - וג\"כ צריך לקדש בשחרית כל הקידוש של לילה מלבד ויכלו אם לא קידש בערבית וכנ\"ל בסימן רע\"א ס\"ח וה\"ה ביו\"ט מי שלא אכל בליל יו\"ט צריך לאכול שתי סעודות למחר ביום [דביו\"ט החיוב הוא שתי סעודות אחת בלילה ואחת ביום] וה\"ה שיאמר בשחרית כל הקידוש של יו\"ט של לילה אם לא קידש בלילה:","(ו) שלש סעודות ביום - ואם שכח רצה בבהמ\"ז בסעודה שניה מצדדים האחרונים שלא לחזור ולברך:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>זמנה משיגיע זמן המנחה דהיינו <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>משש שעות ומחצה ולמעלה ואם עשאה קודם לכן <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i>לא קיים מצות סעודה שלישית: <small>הגה י\"א דאסור לשתות מים בין מנחה למעריב בשבת דאז חוזרים הנשמות לגיהנם וע\"כ <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i>אין לאכול סעודה שלישית בין מנחה למעריב אלא יאכל אותה קודם מנחה (תוס' והרא\"ש ומרדכי פ' ע\"פ) וי\"א דיותר טוב להתפלל <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i>מנחה תחלה (רמב\"ם וטור והגהות מרדכי והגהות מיי' פ\"ל ואגור) וכן נוהגים לכתחלה בכל מדינות אלו מ\"מ אין לשתות מים מן הנהרות אבל בבית שרי וכ\"ש שאר משקין דשרי (הגהות מיי' פ\"ל) וי\"א דאין אסור אלא תוך י\"ב חודש של אביו ואמו (אגודה ומרדכי פ' ע\"פ) וי\"א דאיסור זה של שתיית מים אינו רק בע\"ש (תוס' והרא\"ש ומרדכי בשם רבי משולם והגהות מיי'):</small>","m":["(ז) משש שעות ומחצה - ואם התחיל לאכול הסעודה שלישית קודם חצות ונמשכה הסעודה עד אחר שהגיע זמן מנחה גדולה יצא דהא עכ\"פ אכלה בזמנה ולא אזלינן בזה בתר התחלה:","(ח) דאז חוזרות - ר\"ל דאז קרוב לזמן החזרה לגיהנם ואיתא במדרש כל השותה מים בשבת בה\"ש כאלו גוזל קרוביו המתים ועיין במרדכי פרק ערבי פסחים באורו:","(ט) ועל כן אין לאכול - דפן יבוא גם לשתות:","(י) מנחה תחלה - דאסור לאכול עד שיתפלל והדעה הראשונה ס\"ל דסעודה קטנה שרי כמ\"ש בסימן רל\"ב:","(יא) וכן נוהגים לכתחלה - ובמקום שקשה לו לקיים הסעודה לאחר מנחה יוכל אפילו לכתחלה לקיים הסעודה קודם מנחה אם הוא קודם זמן מנחה קטנה ועיין לעיל בסימן רל\"ב במ\"ב ובסימן ר\"צ במ\"ב:","(יב) הנהרות - ס\"ל לדעה זו דמה דאיתא במדרש הנ\"ל דאין לשתות מים בין השמשות היינו דוקא בשותה מן הנהרות:","(יג) רק בע\"ש - שמפרשים מה דאיתא במדרש הנ\"ל בשבת בין השמשות היינו בין השמשות של ליל שבת:","(יד) ויברך בהמ\"ז וכו' - וכתבו האחרונים שאח\"כ יקום וילך מעט בינתים והנשארים במקומן לא יצאו ידי חובתן דהוי כסעודה אחת. וכתב הב\"י דלא ידרוש ברבים לעשות כן להפסיק סעודתן כיון שקודם חצות אין רשאין להפסיק אין הכל בקיאין בזה:"]},{"s":"<i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"1\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i>אם נמשכה סעודת הבוקר עד שמגיע זמן המנחה <i data-commentator=\"Magen Avraham\" data-order=\"6\"></i>יפסיק הסעודה ויברך <i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"3\"></i>ברכת המזון ויטול ידיו ויברך ברכת המוציא ויסעוד ונכון הדבר שאם לא היה עושה כן מאחר שנמשכה סעודת הבוקר עד אותה שעה לא היה יכול <i data-commentator=\"Magen Avraham\" data-order=\"7\"></i>לאכול אח\"כ <i data-commentator=\"Turei Zahav\" data-order=\"2\"></i>אלא אכילה <i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i>גסה: <small>הגה <i data-commentator=\"Magen Avraham\" data-order=\"8\"></i>אבל מי שיודע שאפשר <i data-commentator=\"Ba'er Hetev\" data-order=\"5\"></i>לאכול אחר שיתפלל מנחה עם הצבור לא יעשה סעודה שלישית קודם מנחה מיהו אם עשאה יצא:</small>","m":["(טו) אלא אכילה גסה - כי כל זמן האכילה האיצטומכא פתוחה משא\"כ אחר הסעודה ולא חיישינן שגורם ברכה שא\"צ כיון שמוכרח לעשות כן משום סעודה ג' שתהיה כדין וזהו מה שמסיק רמ\"א אבל מי שיודע וכו' כדי לצאת מחשש ברכה שאינה צריכה:","(טז) אבל מי שיודע - היינו שמשער בנפשו שלא תהיה אז אכילתו אכילה גסה:","(יז) אחר שיתפלל מנחה - ואפילו אם חל יו\"ט במו\"ש שאי אפשר לו לאכול סעודה שלישית בסוף היום כנהוג שהרי ראוי לו להמנע מלקבוע אז סעודה בעיו\"ט כמו בע\"ש מ\"מ אם יודע שיוכל אז לאכול עכ\"פ כשיעור ביצה ויותר וכנ\"ל בס\"א לא יחלק סעודת שחרית לשתים דהא י\"א דאסור לעשות כן משום ברכה שאינה צריכה. כתב מ\"א בשם ס\"ח מי שיש לו מזון ב' סעודות מצומצמות ואם יחלקם לג' סעודות לא יהיה לו כל סעודה לשבעה מוטב שיאכל ב' סעודות לשבעה ומ\"מ אם נמשכה סעודת הבקר עד אחר חצות יחלקנה לשנים וכמ\"ש בסעיף זה דהא מ\"מ ישבע כשאוכל שנית אבל לכתחלה אין להמתין עד אחר חצות משום זה דמבטל במקצת עונג שבת:"]},{"s":"<i data-commentator=\"Magen Avraham\" data-order=\"9\"></i><i data-commentator=\"Turei Zahav\" data-order=\"3\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"7\"></i>א\"צ לקדש בסעודה שלישית <i data-commentator=\"Be'er HaGolah\" data-label=\"ח\" data-order=\"8\"></i>אבל צריך לבצוע על <i data-commentator=\"Ba'er Hetev\" data-order=\"6\"></i>שתי ככרות: <small>הגה ואם סועד הרבה פעמים בשבת צריך לכל סעודה שתי ככרות (אבודרהם ומיי') ולפחות לא יהיה לו בסעודה שלישית <i data-commentator=\"Turei Zahav\" data-order=\"4\"></i>פחות מככר א' שלם [טור ומרדכי פ' כ\"כ] ומזה פשט המנהג להקל לבצוע בסעודה שלישית רק בככר אחד שלם אבל יש להחמיר ליקח שנים:</small>","m":["(יח) א\"צ לקדש - דהיינו לברך על היין קודם הסעודה דאיתקש יום ללילה לענין קידוש מה לילה סגי בחד זימנא אף ביום כשתקנו חכמים לקדש סגי נמי בחד זימנא בבוקר אבל שתי ככרות צריך דכל הסעודות שאדם סועד ביום השבת שוות:","(יט) פחות מככר אחד - דביום ששי ירד המן לכל אחד שני עמרים ומכל עומר עשו ב' ככרות הרי ד' לב' עמרים אכל אחד בע\"ש ואחד בליל שבת ואחד בבוקר הרי נשאר לו רק אחד שלם לסעודה ג':","(כ) שלם - ואם אין לו די בפרוסה שהיא כביצה וכנ\"ל בס\"א דאע\"ג דמצות לחם משנה אין לו מצות סעודה מיהא קיים [אחרונים]:","(כא) ליקח שנים - וכן ראוי לנהוג לכתחלה כי הסברא הראשונה היא העיקר. וטוב להדר לברך על היין תוך הסעודה [תיקוני שבת]. ואם אין לו לחם משנה לכל אחד מהמסובין נכון לנהוג שזה שבוצע יכוין לפטור בברכת המוציא כל המסובין וגם יאמר להמסובין שיכוונו שיצאו בברכתו כדי שכולם יצאו בלחם משנה [ח\"א]:"]},{"s":"<i data-commentator=\"Turei Zahav\" data-order=\"5\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ט\" data-order=\"9\"></i>צריך לעשותה בפת <i data-commentator=\"Be'er HaGolah\" data-label=\"י\" data-order=\"10\"></i>ויש אומרים שיכול לעשותה בכל מאכל העשוי באחד <i data-commentator=\"Magen Avraham\" data-order=\"10\"></i>מחמשת מיני דגן <i data-commentator=\"Be'er HaGolah\" data-label=\"כ\" data-order=\"11\"></i>וי\"א שיכול לעשותה בדברים שמלפתים בהם הפת כבשר ודגים אבל לא בפירות <i data-commentator=\"Be'er HaGolah\" data-label=\"ל\" data-order=\"12\"></i>וי\"א דאפילו <i data-commentator=\"Eshel Avraham\" data-label=\"א\" data-order=\"1\"></i>בפירות יכול לעשותה וסברא ראשונה עיקר שצריך לעשותה בפת אא\"כ הוא שבע ביותר: <small>הגה או במקום שאי אפשר לו לאכול פת כגון בערב פסח שחל להיות בשבת שאסור לו לאכול פת לאחר מנחה כדלקמן בהלכות פסח: [מהרי\"ל הלכות פסח]:</small>","m":["(כב) צריך לעשותה בפת - כיון דילפינן ג' סעודות מג' פעמים היום דכתיבי גבי מן צריך לעשותה בפת. וגם מצוה לכתחלה להרבות במעדנים כפי יכלתו [אחרונים]:","(כג) וי\"א שיכול לעשותה בכל וכו' - ולכו\"ע למצוה מן המובחר בפת ושני ככרות וכנ\"ל בס\"ד אלא דפליגי לענין דיעבד אם יצא בזה [מב\"ח]:","(כד) מאחד מחמשת וכו' - שמברכין עליהם בורא מיני מזונות וטעם דעה זו כיון דאין דרך לאכול סעודה ג' לתיאבון סגי בהכי וזהו ג\"כ טעם שאר הדעות שמקילין בזה [תו\"ש]:","(כה) שאסור לו וכו' - ע\"כ יקיים אותה במיני טיגון שעושין ממצה כתושה או בבשר ודגים או פירות:"]},{"s":"<i data-commentator=\"Magen Avraham\" data-order=\"11\"></i><i data-commentator=\"Turei Zahav\" data-order=\"6\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"מ\" data-order=\"13\"></i>נשים חייבות בסעודה שלישית:","m":["(כו) חייבות בסעודה שלישית - דלכל מילי דשבת איש ואשה שוין כמו שנתבאר בסי' רע\"א ועוד שגם הם היו בנס של המן ועל כולם אמר אכלוהו היום דמזה נלמד חיוב ג' סעודות בשבת:\n"]}],"292":[{"s":"<b>דין תפלת מנחה בשבת. ובו ב סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>במנחה <small>[אומרים אשרי ובא לציון <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i><i data-commentator=\"Turei Zahav\" data-order=\"1\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"1\"></i>ואני תפלתי וגו'] (טור) </small> <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>מוציאין ספר תורה וקורין <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"2\"></i>שלשה אנשים עשרה פסוקים מפרשה הבאה <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>ואפי' חל יו\"ט להיות בשבת קוראין בפרשה הבאה ולא בשל יום טוב:","m":["(א) אומרים אשרי ובא לציון וכו' - ומפסיקין בקדיש קודם ואני תפלתי. ואמירת ובא לציון במנחה הוא במקום סדר קדושה דחול ובשבת שמאריכין הרבה בשחרית ומוסף הניחוה עד מנחה [כל בו]:","(ב) ואני תפלתי - הוא על פי המדרש שאמר דוד לפני הקב\"ה רבש\"ע אין אומה זו כעו\"ג ששותין ומשתכרים ופוחזים ואנו לא כן אע\"פ שאכלנו ושתינו ואני תפלתי וגו' אבל במנחה של יו\"ט א\"א אותו כיון דאין קורין בתורה שהוא עת רצון עי\"ז ומיהו בשבת נהגו לאמרו אף במקום שאין ס\"ת וכן אפילו ביחיד [אחרונים]:","(ג) ומוציאין וכו' - הוא מתקנת עזרא כדאיתא בגמרא:","(ד) ג' אנשים וכו' - במנחה א\"א קדיש על הבימה לעולם [היינו בין בשבת בין בתענית] רק לפני העמוד קודם תפלת י\"ח וקאי נמי אס\"ת דאי יאמרו מיד על הבימה א\"כ לפני העמוד לא יאמרו קדיש כי אין במה להפסיק בין הקדישים [יהללו פסוק אחד לא הוי הפסק ואף שאומרים מזמור לה' הארץ אין זה מעיקר הדין] ולעולם ראוי להסמיך הקדיש לתפלת י\"ח משא\"כ בשחרית יש הפסק באמירת אשרי בינתים ולפ\"ז כשאין ס\"ת בשבת במנחה לא יאמרו רק פ\"א קדיש אחר אשרי ובא לציון ופסוק ואני תפלתי יאמרו אז קודם הקדיש כדי שלא יהא הפסק בין קדיש להתפלה [א\"ר וש\"א]:","(ה) ולא בשל יו\"ט - דהא הקריאה איננה בשביל יו\"ט דהא במנחה ביו\"ט אין קורין:"]},{"s":"<i data-commentator=\"Turei Zahav\" data-order=\"2\"></i> <i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>אומרים <i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>צדקתך <i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>ואם חל בו יום שאלו היה חול לא היו אומרים <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>בו <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i>במנחה נפילת אפים אין אומרים צדקתך: <small>הגה ונהגו <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i>שלא לקבוע <i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i>מדרש בין מנחה למעריב (טור זוהר תרומה ע' רע\"ט) אבל אומרים פרקי אבות בקיץ ושיר המעלות בחורף וכל מקום לפי מנהגו:</small>","m":["(ו) צדקתך - דמתו בו יוסף משה ודוד ולכן נהגו שלא לקבוע אז מדרש כי חכם שמת כל המדרשות בטלים וב\"ח האריך להוכיח שלא מת משה בשבת רק בע\"ש ולא נגנז עד שבת במנחה בשעתא דעת רצון וכמ\"ש בזוהר ואנו אומרים צדוק הדין עליו בזמן שנגנז וי\"מ דאומרים צדקתך להצדיק הדין על הרשעים שחוזרין לגיהנם במו\"ש:","(ז) בו במנחה וכו' - פי' בין שיום השבת הוא ר\"ח בין שיום א' שאחריו הוא ר\"ח וא\"כ אלו היה חול לא היו אומרים במנחה נפילת אפים שכבר חל במקצת יום שלאחריו ולכן גם עתה א\"א צדקתך:","(ח) ונהגו - ואינו איסור אלא מנהג לזכרון בעלמא והטעם כנ\"ל בסק\"ה ודוקא שלא ללמוד בחברותא אבל שנים שנים לומדים בבתיהם כמ\"ש ביו\"ד סימן שד\"מ סי\"ח לענין נשיא שמת:","(ט) בין מנחה למעריב - היינו כשהוא סמוך לחשיכה ולכן המנהג לדרוש קודם מנחה ואם נמשכה הדרשה עד סמוך לחשיכה אזי לא יאמרו פרקים או שיר המעלות כדי שיוכלו לקיים סעודה ג' בזמנה [מ\"א] ובא\"ר איתא בשם מלבושי יו\"ט שראה לרבו מהר\"ל מפראג כמה פעמים שדרש בין מנחה למעריב. וע\"כ נראה דבזמנינו אין למנוע זה כידוע שמצוי בעו\"ה באיזה מקומות שעוסקין אז כמה אנשים בבהמ\"ד בשיחה בטלה ובודאי טוב יותר לשמוע אז דברי מוסר כדי שלא יבואו לזה:\n"]}],"293":[{"s":"<b>דיני ערבית במוצאי שבת. ובו ג סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>מאחרין תפלת ערבית <i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"1\"></i>כדי להוסיף מחול על הקודש:","m":["(א) מאחרין וכו' - היינו אף דמן הדין סגי במה שיתעכב מלעשות מלאכה עד הזמן המבואר בס\"ב מ\"מ לכתחלה ראוי ונכון וכן מנהג כל ישראל לאחר את התפלה כדי שיתוסף יותר מחול על הקודש. המנהג לזמר קודם מעריב המזמור אלהים יחננו [תהלים ס\"ו] ועוד מזמורים כנזכר בסידורים. ואם יחול ת\"ב במוצאי שבת אין מזמרין דאז אין זמן חנינה. וכן כשיחול יו\"ט במו\"ש ג\"כ אין המנהג לזמר. כתב הפמ\"ג דאפשר משום דאין אומרים תחנה בשבת ויו\"ט משא\"כ בכל שבת יוכל לאמרו משחשכה קודם מעריב. ועיין לעיל בסימן מ\"ט בשם חות יאיר דתהילים מותר המורגל בו לומר בעל פה ומה טוב ויפה המנהג הזה א' כדי ללוות שבת שנקראת כלה מלכתא בשירות ותשבחות וכדאיתא במדרש ועוד כי עי\"ז נתאחר המעריב ונתוסף מחול על הקודש וגם כדי שלא יבואו לדבר בדברים בטלים אח\"כ מצאתי בכנסת הגדולה סימן רל\"ה כעין מה שכתבתי:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>צריך ליזהר מלעשות מלאכה עד שיראו <i data-commentator=\"Sha'arei Teshuvah\" data-order=\"1\"></i>שלשה <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>כוכבים קטנים <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>ולא יהיו מפוזרים אלא <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>רצופים ואם הוא יום המעונן ימתין עד שיצא הספק מלבו:","m":["(ב) מלעשות מלאכה - עיין לקמן בסימן רצ\"ט ס\"י:","(ג) עד שיראו - וקודם לכן אסור משום ספק יום ומדינא סגי בג' כוכבים בינונים אלא שאין אנו בקיאין בזה ושמא הן גדולים הנראין ביום לכן אנו מצריכין קטנים:","(ד) ג' כוכבים קטנים - עיין לקוטי פר\"ח על יו\"ד שכתב דאם הרקיע מזהיר כעין אורה של יום תו לא נחשב אותו הזמן רק בה\"ש והביאו הגאון רע\"א בחידושיו ביו\"ד סימן רס\"ב עי\"ש ובבאור הגר\"א בלקוטיו שם כתב דאם נסתלק האדמימות מן כל כפת הרקיע באותו צד ששקעה החמה אין אנו חוששין במה שמזהיר. ודע עוד דבספר תפארת ישראל בפ\"ב דשבת מצריך ג' קטנים לבד ג' בינונים ולא ידעתי מקורו ואולי דטעמו שמא אנו טועין בדבר וגדולים הם לכך אנו צריכין עוד כוכבים הגדולים מהם ומזה אנו יודעין שעכ\"פ הם אינם גדולים ולפי מה שכתב בשערי תשובה סימן רל\"ה בשם המטה יהודה והברכי יוסף עי\"ש ניחא דברי התפארת ישראל בפשיטות אולם שארי אחרונים לא הזכירו ד\"ז [ואפשר דאם בשארי מקומות הרקיע מעונן ולא יכול לראות עוד כוכבים יש להקל לכו\"ע] ונ\"ל דלפי מה שכתב הגר\"א דבעינן שיסתלק האדמימות מן כל כפת הרקיע באותו צד ששקעה החמה ואז מועיל הג' כוכבים נראה דמועיל אז בג' כוכבים קטנים לבד:","(ה) אלא רצופים - משום תוספת שבת. וה\"ה כשרואה ג' כוכבים קטנים שאינם רצופים וממתין מעט אחרי כן מותר לעשות מלאכה דעיקר טעם הרצופין משום תוספת וכיון שהמתין מעט הרי הוסיף [דגול מרבבה]:","(ו) עד שיצא - מה שלא זכר השו\"ע שימתין השיעור ד' מילין מעת תחלת השקיעה לפי מה שפסק לעיל בסימן רס\"א ס\"ב דאפשר דמיירי דלא נודע לו גם זמן השקיעה משום הענן:","(ז) מלבו - ואם יש לו מורה שעות שהולך בטוב ויודע בבירור שהיה אתמול בזה הזמן לילה ע\"פ הדין דהיינו ג' כוכבים קטנים נראה דיוכל לסמוך ע\"ז וכ\"כ בברכי יוסף דיוכל לסמוך על מורה שעות:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>מי שהוא אנוס <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>כגון שצריך להחשיך על התחום לדבר מצוה <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i>יכול להתפלל של מוצאי שבת מפלג המנחה ולמעלה <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>ולהבדיל מיד <i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>אבל לא יברך על הנר וכן אסור בעשיית מלאכה עד צאת הכוכבים: <small>הגה ונוהגים לומר והוא רחום וברכו באריכות נועם כדי להוסיף מחול על הקודש (א\"ז):</small>","m":["(ח) כגון שצריך וכו' - היינו שהולך מביתו מבע\"י עד סוף התחום ויושב שם עד הערב כדי שמיד שיחשך ילך לדבר מצוה הנחוץ לו ומיירי ששם לא ימצא לו כוס להבדיל עליו:","(ט) יכול וכו' - ומ\"מ כתבו האחרונים דאין לעשות כן דדבר תמוה הוא לרבים גם שמא יבואו להקל במלאכה ובפרט בימינו דנוהגין לעשות תמיד כרבנן שמתפללין מנחה עד הערב בודאי מדינא אסור להקדים מעריב במו\"ש ואף דבע\"ש יש שמקילין היינו משום דמצוה להוסיף מחול על הקודש משא\"כ במו\"ש:","(י) ולהבדיל מיד - ומ\"מ ימתין מלקרות ק\"ש עד צה\"כ:"]}],"294":[{"s":"<b>דיני הבדלה בתפלה. ובו ה סעיפים:</b><br><i data-commentator=\"Turei Zahav\" data-order=\"1\"></i><i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"1\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>אומרים הבדלה <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>בחונן הדעת ואם טעה ולא הבדיל משלים תפלתו <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"1\"></i><i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>ואינו חוזר מפני שצריך להבדיל על הכוס <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>ואם טעם קודם שהבדיל על הכוס <i data-commentator=\"Turei Zahav\" data-order=\"2\"></i>צריך לחזור ולהבדיל <i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>בתפלה:","m":["(א) אומרים הבדלה וכו' - ואפילו אם נזדמן שהבדיל על הכוס מקודם מ\"מ צריך להבדיל בתפלה ג\"כ. ואי עיקר מצות הבדלה היא דאורייתא או דרבנן עיין במה שנכתוב לקמן ריש סימן רצ\"ו:","(ב) בחונן הדעת - וקבעוה בברכה זו מפני שאסור לתבוע צרכיו קודם הבדלה. מנהג פשוט לומר אתה חונן וכו' עד לאנוש בינה ואח\"כ אתה חוננתנו וכו' וחננו מאתך וכו' [אחרונים] ואם התחיל מאתה חוננתנו ואילך יצא. אם שכח להתפלל מתפלל שחרית שתים ואינו מזכיר אתה חוננתנו לא בראשונה ולא בשניה בד\"א כשכבר הבדיל מאתמול על הכוס אבל אם לא הבדיל כלל דיש עליו עדיין חיוב מצות הבדלה יזכיר אתה חוננתנו בשחרית בתפלה שניה שהיא להשלמה ואח\"כ צריך להבדיל ג\"כ על הכוס כדלקמן סימן רצ\"ט ס\"ו:","(ג) ואינו חוזר מפני וכו' - היינו דלכתחלה מצוה להבדיל בין בתפלה ובין בכוס והכא בדיעבד סומך עצמו על מה שיבדיל אח\"כ על הכוס ומ\"מ אסור לע\"ע במלאכה עד שיבדיל בכוס או שיאמר עכ\"פ המבדיל בין קודש לחול וכמ\"ש סוף סימן רצ\"ט:","(ד) ואם טעם וכו' - ואע\"ג דקי\"ל בסימן רצ\"ט ס\"ה דאם טעה ואכל קודם הבדלה יכול להבדיל אח\"כ מ\"מ כאן דטעה גם בתפלה קנסינן ליה וצריך לחזור ולהתפלל ולהבדיל בתפלה:","(ה) וסובר שאף למחר וכו' - דאם מצפה שיהיה לו למחר יוכל לסמוך ע\"ז שיבדיל למחר על הכוס וכדלקמן ברצ\"ט ס\"ו וא\"צ להחזיר התפלה:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>טעה ולא הבדיל בתפלה ואין לו כוס בלילה וסבור שאף למחר לא יהיה לו <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>צריך לחזור <i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i>ולהתפלל:","m":["(ו) צריך לחזור ולהתפלל - היינו כשעקר רגליו [או כשסיים תפלתו ואינו רגיל לומר תחנונים אחר תפלתו דדינו ג\"כ כעקר רגליו וכדלעיל בסימן קי\"ז ס\"ה ע\"ש] חוזר לראש ואם לא סיים עדיין תפלתו חוזר לברכת אתה חונן מיהו אם נזכר קודם שומע תפלה לא יחזור אלא יאמר אתה חוננתנו בשומע תפלה דכשמבדילין בתפלה אומרים אבינו מלכנו החל עלינו וכו' דהוא בקשה והוי מעין שומע תפלה דהוא כולל כל הבקשות מיהו אם יש לו כוס יסמוך על הכוס ולא יאמרנה בש\"ת כיון דעיקרה הוא שבח ולא שייך כ\"כ לשומע תפלה [מ\"א וש\"א]:","(ז) כשסיים הברכה - היינו שהזכיר השם של סיום הברכה דבזה מקרי כאלו כבר סיים [אחרונים]:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>תשעה באב שחל להיות באחד בשבת טעה ולא הבדיל בתפלה א\"צ לחזור ולהתפלל כיון שמבדיל על הכוס במוצאי תשעה באב:","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>במקום שאמרו שאינו חוזר להתפלל מיד כשסיי' הברכ' <i data-commentator=\"Turei Zahav\" data-order=\"3\"></i>אין לו לחזור אע\"פ שלא פתח בברכה שלאחריה:","m":[]},{"s":" <i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>במקום שאמרו שאינו חוזר אם רצה להחמיר על עצמו לחזור <i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i>אם סיים תפלתו <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"5\"></i>רשאי אבל אם עדיין לא סיים תפלתו אינו רשאי לחזור:","m":["(ח) רשאי - בתורת נדבה ועיין לעיל בסוף סימן ק\"ז דאין להתפלל נדבה אלא מי שמכיר עצמו זריז וזהיר ושיכוין:","(ט) אינו רשאי - כיון דאינו צריך לחזור הוי הפסק [טור]:"]}],"295":[{"s":"<b>הבדלה שעושה ש\"ץ. ובו סעיף אחד:</b><br><small>הגה <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i><i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"1\"></i>ואומרים <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"1\"></i>ויהי נועם וסדר קדושה באריכות כדי לאחר סדר קדושה שאז חוזרים רשעים לגיהנם (טור) ובזמן שאין אומרים ויהי נועם <i data-commentator=\"Turei Zahav\" data-order=\"2\"></i>כגון שחל יום טוב <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"2\"></i>בשבוע <i data-commentator=\"Turei Zahav\" data-order=\"3\"></i>אין אומרים סדר <i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>קדושה אבל אומרים ויתן לך (כל בו) </small>: <br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>מבדיל שליח צבור כדי להוציא מי שאין לו יין: <small>הגה ונהגו לומר ולהזכיר <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i>אליהו הנביא במ\"ש להתפלל שיבא ויבשרנו הגאולה (טור):</small>","m":["(א) ואומרים ויהי נועם - ונוהגין לכפול פסוק ארך ימים [טור ע\"ש הטעם] ופסוק ויהי נועם צריך לאומרו מעומד. ויש מקומות שא\"א ויהי נועם בבית האבל רק מתחילין יושב בסתר וגו':","(ב) וסדר קדושה - היינו שמתחילין מואתה קדוש ואין אומרים ובא לציון גואל לפי שאין גאולה בלילה ולכן גם ואני זאת בריתי אין אומרים לפי שסמוכים הם להדדי בספר ישעיה [ט\"ז] ומ\"ש שאומרים באריכות היינו בנעימות קול כדי שיתארך מעט יותר ולעכב לרשעים מלחזור לגיהנם דעד שישלימו ישראל סדריהם נמשכת קדושת שבת ואח\"כ חוזרים לגיהנם וכמו שאחז\"ל דבמו\"ש צועק הממונה על הרוחות חזרו לגיהנם שכבר השלימו ישראל את סדריהם [טור]:","(ג) כגון שחל יו\"ט וכו' - היינו אפילו חל ביום וי\"ו דבעינן שכל השבוע יהיה ראוי למלאכה משום דכתיב בו ומעשה ידינו כוננה עלינו וגו'. ודוקא יו\"ט גמור אבל פורים או ע\"פ שחל בימי החול אין למנוע מלומר ויהי נועם במו\"ש שלפניו:","(ד) סדר קדושה - דויהי נועם שייך למלאכת המשכן שבו ברך משה לישראל בשעה שסיימו מלאכת המשכן ועי\"ז שרתה שכינה וזהו שמסמיכין פסוק ואתה קדוש יושב תהלות ישראל ולכך בזמן שאין אומרין ויהי נועם אין אומרים ממילא כל סדר קדושה [ט\"ז]:","(ה) ויתן לך - שהם פסוקים של ברכה בתחלת ימי השבוע:","(ו) מי שאין לו יין - דמי שיש לו יין יותר טוב שיבדיל בביתו כדי להוציא את כל בני ביתו ועמ\"ש ברצ\"ו ס\"ז במ\"ב:","(ז) במו\"ש - דאיתא בעירובין [מ\"ג] מובטח להן לישראל שאין אליהו בא לא בערבי שבתות ולא בערבי יו\"ט מפני הטורח [שמניחין צרכי שבת והולכין להקביל פניו רש\"י] וע\"כ אנו מתפללים כיון שעבר השבת ויכול לבוא שיבוא ויבשרנו [טור] ועיין בא\"ר שכתב דהמדקדקים אומרים גם שאר פזמונים ושירים כאשר הם מצויים אצלנו וראוי ליזהר לומר רבש\"ע וכו' החל את וכו' כי הוא בירושלמי וטור סימן רצ\"ט. יש מקומות שמדליקין נרות במקום אופל דעי\"ז זכה שאול למלוכה:"]}],"296":[{"s":"<b>דיני הבדלה על היין. ובו ח סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>סדר <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>הבדלה יין בשמים נר הבדלה וסימנך יבנ\"ה <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>וצריך ליזהר שלא יהא הכוס פגום: <small>הגה ונהגו לומר קודם הבדלה שעושים בבית הנה אל ישועתי וגו' כוס ישועות אשא וגו' ליהודים היתה אורה וגו' לסי' טוב ובשעת הבדלה <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>יתנו עיניהם <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>בכוס ובנר ונוהגין לשפוך מכוס של יין על הארץ <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i>קודם שיסיים בורא פרי הגפן כדי <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>שלא יהיה הכוס <i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>פגום <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>וטעם השפיכה דאמרי' כל בית שלא נשפך בו יין כמים אין בו סי' ברכה ועושין כן לסי' טוב בתחלת השבוע גם <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i>שופכים <i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i>מן הכוס לאחר הבדלה ומכבין בו הנר ורוחצים בו עיניו משום חבוב <i data-commentator=\"Ba'er Hetev\" data-order=\"5\"></i>מצוה:</small>","m":["(א) סדר הבדלה וכו' - הנה הרמב\"ם סובר דמצות הבדלה היא ד\"ת כמו קידוש והוא בכלל זכור את יום השבת לקדשו שצריך לזכור אותו ולקדשו בין בכניסתו ובין ביציאתו בכניסה בקידוש וביציאה בהבדלה לומר שהוא מובדל בקדושה בראש ובסוף משאר ימים וי\"א שהוא מד\"ס ואסמכוהו אקרא. וצריך להיות ג\"כ בכוס כמו בקידוש ואם הבדיל בתפלה לכו\"ע הבדלה על הכוס דרבנן:","(ב) פגום - היינו שאם שתה אחד מן היין מתחלה נפגם להבדלה וכמו לענין קידוש לעיל בסימן רע\"א ס\"י ע\"ש במ\"ב ועיין באחרונים בסימן קפ\"ג שאם הכוס בעצמו פגום אין להקפיד עליו אם אין לו אחר:","(ג) יתנו עיניהם בכוס - היינו המבדיל וגם השומעים העונים אמן כדי שלא יסיחו דעתם:","(ד) כדי שלא יהיה וכו' - היינו דמשום זה אינו שופך קודם שמתחיל הברכה כדי שלא יברך תחלת הברכה על כוס פגום שאינו מלא ואחר סיום הברכה ג\"כ לא יוכל לשפוך שיש ביזוי לכוס של ברכה כששופך ממנו אחר ברכה קודם שתיה ולכן שופכין קודם סיום הברכה ועיין לקמיה:","(ה) וטעם השפיכה - והאחרונים הסכימו דלא ישפוך בשעת ברכה כלל אלא בשעה שמוזג ישפכנו מלא על כל גדותיו שישפך על הארץ וגם זה יש למעט בחלק הנשפך משום הפסד משקין:","(ו) שופכין מן הכוס - היינו לאחר שתיה. ושתית הכוס תהיה בישיבה דאין שותין מעומד לכתחלה. נהגו הנשים שלא לשתות מכוס הבדלה. כוס של הבדלה רגיל המבדיל לשתותו כולו ואינו משקה ממנו בני ביתו [מ\"א] ונראה שהטעם כדי שיוכל לברך ברכה אחרונה דכשישתה רק מלא לוגמיו יש ספק ברכה אחרונה וכמבואר לעיל סימן ר\"י:"]},{"s":"<i data-commentator=\"Turei Zahav\" data-order=\"2\"></i> <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>אין מבדילין על <i data-commentator=\"Ba'er Hetev\" data-order=\"6\"></i>הפת <i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>אבל על השכר מבדילין אם הוא חמר מדינה וה\"ה לשאר משקין חוץ מן המים: <small>הגה <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i>וטוב יותר להבדיל על כוס פגום של יין מעל שכר (אבודרהם) <i data-commentator=\"Magen Avraham\" data-order=\"6\"></i>ונהגו להבדיל במוצאי פסח <i data-commentator=\"Ba'er Hetev\" data-order=\"7\"></i>על שכר ולא על יין <i data-commentator=\"Turei Zahav\" data-order=\"3\"></i>משום דחביב <i data-commentator=\"Ba'er Hetev\" data-order=\"8\"></i>עליו </small> ובי\"ט שחל להיות במוצאי שבת שיש בו קידוש שהוא נאמר על הפת <i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>יש אומרים שאגב הקידוש מבדילין גם כן עליו <i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i>וי\"א שיותר טוב לומר הקידוש והבדלה שניהם על השכר <small>הגה [והסברא ראשונה עיקר]:</small>","m":["(ז) על הפת - ול\"ד לקידוש דשאני קידוש שהוא במקום סעודה והוי מענין הצריך לקידוש משא\"כ הבדלה:","(ח) על השכר מבדילין - אם אין לו יין ואם יש לו יין הוא קודם לכל המשקין [או\"ז] וחז\"ל הפליגו ג\"כ בגודל המצוה ואמרו המבדיל על היין או שומע מאחרים שמבדילין הקב\"ה קוראהו קדוש ועושהו סגולה שנאמר והייתם לי סגלה מכל העמים ואומר ואבדיל אתכם מן העמים [טור]:","(ט) חמר מדינה - עיין לעיל בסימן רע\"ב ס\"ט במ\"ב ובה\"ל שם מהו חמר מדינה ומה שכתב ה\"ה לשאר משקין היינו משקין שרגילין לשתותו אבל משקין שרגילין בפסח כגון מי לאקריץ אינו חמר מדינה כיון שאין רגילין לשתותו כל השנה וה\"ה כל כיוצא בזה ואפילו מי דבש לא הוי חמר מדינה אלא במדינות שרגילין לשתותן אבל במקום שאין שותין אותו אלא לפרקים לא הוי חמר מדינה וגרע משכר. ועל יי\"ש אין כדאי להבדיל דהא כתב המ\"א דכוס הבדלה רגיל המבדיל לשתותו כולו ואין משקה ממנו בני הבית וביי\"ש קשה לקיים זה אך כשאין לו משקה אחר יכול להבדיל עליו ואך שיזהר לשתות ממנו עכ\"פ כמלא לוגמיו שהוא רוב רביעית וא\"ל לא יצא. כתב בשערי תשובה בשם הברכי יוסף דעל חלב ושמן אין להבדיל שאין רגילין לשתותו למשקה:","(י) חוץ מן המים - אף אם רוב שתיית המדינה הוא מן המים משום דלא חשיב. ועל קווא\"ס ובארשט מוכח מט\"ז בסימן קפ\"ב וא\"ר שם דאף בשעת הדחק אין מברכין דאף שההמונים שותין אותן מ\"מ לא חשיבי וכמו מים הוא [ואף דעת המ\"א שם דהעתיק דעת רש\"ל להקל בשעת הדחק היינו דוקא גבי כוס בהמ\"ז שאין בו חשש ברכה לבטלה וכדמוכח בתשובת רש\"ל משא\"כ בהבדלה. ובח\"א כתב דבשעת הדחק יש להבדיל על משקה קווא\"ס ולא ידעתי טעמו ואולי מיירי בשנעשה משקה חשוב כעין משקה שכר וגם זה דוקא אם עיקר שתיית ההמון הוא מהמשקה הזה דאל\"ה לא הוי חמר מדינה]:","(יא) וטוב יותר וכו' - והמ\"א מצדד דבמקום שהשכר הוא חמר מדינה יש לומר דעדיף מכוס יין פגום ועיין בביאור הגר\"א שכתב ג\"כ דדינא דהרמ\"א הוא דוקא כשהשכר אינו חמר מדינה:","(יב) ונהגו להבדיל - ודוקא במקום שהשכר הוא חמר מדינה אבל בארץ אשכנז דלא הוי חמר מדינה לא מהני מה שהוא חביב ואסור להבדיל עליו:","(יג) דחביב עליו - שלא שתהו כל ימי הפסח:","(יד) מבדילין ג\"כ - ר\"ל אף דבעלמא אין מבדילין על הפת כדלעיל הכא אגב קידוש שהוא העיקר אומרים כל היקנה\"ז על הפת:","(טו) והסברא ראשונה עיקר - טעמו משום דהרבה ראשונים ס\"ל דאין מקדשין על השכר וכדלעיל בסימן רע\"ב ס\"ט ע\"ש לכך טוב יותר לעשות כל היקנה\"ז על הפת ומ\"מ נראה דבזה ידקדק לכתחלה לחפש אחר יין אפילו אם הפת חביב לו יותר מיין דכמה גדולי ראשונים סברי דאין אומרים המבדיל על הפת אפילו במו\"ש שהוא יו\"ט ואך אם לא ימצא יין הפת עדיף משכר:"]},{"s":"אם אין לו יין ולא שכר ושאר משקין <i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"7\"></i>י\"א <i data-commentator=\"Magen Avraham\" data-order=\"7\"></i>שמותר לו <i data-commentator=\"Ba'er Hetev\" data-order=\"9\"></i>לאכול <i data-commentator=\"Be'er HaGolah\" data-label=\"ח\" data-order=\"8\"></i>וי\"א שאם מצפה שיהיה לו למחר <i data-commentator=\"Magen Avraham\" data-order=\"8\"></i>לא יאכל עד למחר שיבדיל <i data-commentator=\"Be'er HaGolah\" data-label=\"ט\" data-order=\"9\"></i>ואם אין לו אלא כוס אחד <i data-commentator=\"Magen Avraham\" data-order=\"9\"></i>ואינו מצפה שיהיה לו למחר מוטב שיאכל קודם שיבדיל ויברך עליו ברכת המזון ואח\"כ יבדיל עליו ממה שיברך ברכת המזון בלא כוס לדברי האומרים דבהמ\"ז טעונה כוס ולדברי האומרים דאינו טעונה כוס לא יאכל עד שיבדיל <i data-commentator=\"Be'er HaGolah\" data-label=\"י\" data-order=\"10\"></i>ומיירי שכוס זה לא היה בו אלא רביעית בצמצום וכבר היה מזוג כדינו שאם היה משים בו מים יותר לא היה ראוי לשתייה שאל\"כ לדברי הכל מבדיל תחלה ושותה ממנו מעט ומוסיף עליו להשלימו לרביעית ומברך עליו ברכת המזון:","m":["(טז) ולא שכר - וה\"ה אם יש לו שכר אלא שאינו חמר מדינה:","(יז) שמותר לו וכו' - ומ\"מ צריך שיתפלל תחלה ויאמר הבדלה בחונן הדעת ואעפ\"כ כשישיג למחר כוס חייב להבדיל כדין וכדלקמן בסימן רצ\"ט ויש שרוצים לומר שיאמר עתה ברכת המבדיל בלא כוס ואין להורות כן:","(יח) לאכול - והא דאמרינן בגמרא דאמימר איקלע לאתרא ולא היה לו על מה להבדיל ולן בתענית עד למחר ס\"ל לדעה זו דמחמיר על עצמו היה:","(יט) שיהיה לו למחר - היינו בבקר אבל בערב אינו מחויב להמתין כ\"כ ואפשר דאפילו יותר מחצות היום אינו מחויב להמתין:","(כ) לא יאכל - ואפילו במוצאי שבת ליו\"ט ג\"כ לא יאכל אם אין לו כוס [מ\"א] ומיירי בשאין לו פת ג\"כ דאם יש לו פת הלא הכריע רמ\"א לעיל בס\"ב דיכול להבדיל על הפת [אחרונים]:","(כא) עד למחר שיבדיל - ויש להחמיר כסברא אחרונה הזו אם לא באדם חלש שקשה לו התענית יכול לסמוך אדעה ראשונה:","(כב) ואינו מצפה וכו' - אבל אם מצפה שיהיה לו למחר עוד כוס יבדיל עכשיו על כוס זה ובאכילה ימתין עד למחר כדי שיברך על הכוס למ\"ד דבהמ\"ז טעונה כוס מיהו המ\"א בריש סי' קפ\"ב חולק ע\"ז דבשביל כוס בהמ\"ז שלא יהיה לו אינו מחויב למנוע עצמו מלאכול:","(כג) ושותה ממנו מעט - היינו כמלא לוגמיו:","(כד) ומוסיף עליו - היינו שימזגנו במים:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"כ\" data-order=\"11\"></i>מי שאין ידו משגת לקנות יין לקידוש ולהבדלה יקנה להבדלה דקידוש אפשר בפת:","m":["(כה) יקנה להבדלה - דין זה מובא ג\"כ לעיל בסי' רע\"א סי\"א דרך אגב ועיין שם במ\"ב סקנ\"ו:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ל\" data-order=\"12\"></i>אם אין ידו משגת לקנות שמן לנר חנוכה ויין להבדיל <i data-commentator=\"Turei Zahav\" data-order=\"4\"></i>נר חנוכה קודם:","m":["(כו) נר חנוכה קודם - משום דפרסומי ניסא עדיף ועוד דעיקר מצות הבדלה נוכל לקיים בתפלה:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"מ\" data-order=\"13\"></i>אומר <i data-commentator=\"Turei Zahav\" data-order=\"5\"></i>הבדלה מיושב: <small>הגה וי\"א מעומד [אגודה וכל בו ואגור] וכן נוהגים במדינות אלו. </small> <i data-commentator=\"Turei Zahav\" data-order=\"6\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"נ\" data-order=\"14\"></i>ואוחז היין <i data-commentator=\"Ba'er Hetev\" data-order=\"10\"></i>בימין וההדס בשמאל ומברך על היין ושוב <i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"1\"></i>נוטל ההדס בימין והיין בשמאל ומברך על ההדס ומחזיר היין לימינו:","m":["(כז) מיושב - מיירי כשמוציא לאחרים ידי חובתן וע\"כ כיון דאחד פוטר חבירו יש להם לכולם לעשות קביעות ובמעומד לא הוי קביעות והי\"א ס\"ל דכיון שהוא הלוית המלך אין מלוין אלא מעומד ולענין הקביעות סגי כשמזמנין הכל ועומדין ומכוונין כדי לצאת וס\"ל דמתוך שקובעין עצמן כדי לצאת ידי ברכת הבדלה מהני נמי קביעות זו לצאת בברכת היין [ב\"י]:","(כח) וכן נוהגין וכו' - ויקנה\"ז לכו\"ע טוב לברך מיושב כמו בשאר קידוש לעיל בסימן רע\"א ס\"י בהג\"ה:","(כט) ואוחז היין בימין - דכן בכל דבר שמברך עליו צריך לאחזו בימינו בשעת הברכה וכדלעיל בסימן ר\"ו ס\"ד:","(ל) והיין בשמאל - ואינו מניחו אז מידו משום דכל הברכות של הבדלה מצוה להיות על הכוס:","(לא) ומברך על ההדס - ומניחו ורואה בצפרנים ומברך בורא מאורי האש ואח\"כ מחזיר היין לימינו וגומר ההבדלה:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ס\" data-order=\"15\"></i>אפילו שמעו כל בני הבית הבדלה בבית הכנסת <i data-commentator=\"Magen Avraham\" data-order=\"10\"></i>אם נתכוונו שלא לצאת מבדילין בבית:","m":["(לב) כל בני הבית - וכ\"ש אם יש אחד מבני הבית אפילו קטן שהגיע לחינוך שלא שמע עדיין הבדלה יוכל להבדיל בשבילו אף שהוא בעצמו יצא כבר ידי חובת הבדלה בבהכ\"נ כגון שנתכוין לצאת וכמו לענין קידוש לעיל בסימן רע\"ג ס\"ד ועיין מה שכתבנו לקמיה לענין להוציא נשים:","(לג) אם נתכוונו שלא לצאת - כתב הלבוש דהאידנא מסתמא מתכוין כל אחד מבני הבית שלא לצאת בהבדלה שמבדילין בבהכ\"נ שסומכין על הבדלה שבבית והו\"ל כלא הבדילו כלל ולא נפיק בה. ת\"ח אין סומכין על ההבדלה שבבהכ\"נ ומבדילין בביתם כדי שיוכלו להוציא ב\"ב [מ\"א בשם סמ\"ע] וכן ראוי לכל אדם לנהוג. כתב המ\"א אם נתכוין לצאת בברכת הבדלה אע\"פ שלא נתכוין לברכת פה\"ג מ\"מ יצא ידי הבדלה דברכת המבדיל הוא העיקר אלא דאסור לטעום מהיין אא\"כ יברך פה\"ג:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ע\" data-order=\"16\"></i>נשים חייבות בהבדלה כשם שחייבות בקידוש <i data-commentator=\"Turei Zahav\" data-order=\"7\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"פ\" data-order=\"17\"></i>ויש מי שחולק: <small>הגה ע\"כ <i data-commentator=\"Magen Avraham\" data-order=\"11\"></i>לא יבדילו לעצמן רק ישמעו הבדלה מן <i data-commentator=\"Ba'er Hetev\" data-order=\"11\"></i>האנשים:</small>","m":["(לד) נשים חייבות - אע\"ג דהוי מצוה שהזמן גרמא דבדיני שבת איש ואשה שוין דאיתקש זכור לשמור וכמ\"ש בריש סימן רע\"א והבדלה נמי בכלל זכור הוא למ\"ד הבדלה ד\"ת וכמ\"ש בריש הסימן ואפילו למ\"ד הבדלה דרבנן דומיא דקידוש תקנוה והיש מי שחולק ס\"ל דהבדלה כיון שהיא בחול אינה תלויה בעניני דיני שבת והיא בכלל שאר מצות שהזמן גרמא דנשים פטורות:","(לה) לא יבדילו לעצמן - והב\"ח כתב אפילו למ\"ד שפטורות מ\"מ יכולות להמשיך על עצמן חיוב ולהבדיל לעצמן כמו בשופר ולולב שג\"כ פטורות ואפ\"ה מברכות כמבואר לקמן בסימן תקפ\"ט ומסיק המ\"א דהעיקר כדברי הב\"ח. והנה לפי מה שכתב המ\"א לעיל בסק\"ד דנהגו הנשים שלא לשתות מכוס הבדלה א\"כ בלאו כל הטעמים האיך תבדיל בעצמה והלא אינה יכולה לשתות הכוס וכ\"כ בעל דרך החיים אלא כונת המ\"א להקל בשאין לה ממי לצאת דאז בע\"כ תבדיל לעצמה ותשתה כדי שלא לבטל מצות הבדלה:","(לו) מן האנשים - ואם האנשים כבר הבדילו לעצמם או שנתכונו לצאת בבהכ\"נ לא יבדילו כדי להוציא הנשים אם אין שם זכרים גדולים או קטנים ששומעין ממנו דלהיש חולקין הוא ברכה לבטלה [מ\"א וש\"א] והנה בספר זכור לאברהם בערך הבדלה וכן בספר ברכי יוסף הביאו כמה פוסקים דס\"ל דאפילו מי שהבדיל כבר יכול להבדיל בשביל הנשים מ\"מ למה לנו להכניס עצמן בחשש ספק לענין ברכה אחרי דהיא יכולה להבדיל בעצמה וכמו שכתבנו בס\"ק הקודם ועיין מה שכתבנו בביאור הלכה לענין ברכת הנר אם אשה חייבת בם כשמברכת לעצמה:\n"]}],"297":[{"s":"<b>דיני בשמים להבדלה. ובו ה סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>מברך על <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"1\"></i>הבשמים אם יש לו <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>ואם אין לו <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i>אינו צריך לחזור אחריהם:","m":["(א) מברך על הבשמים - והברכה הוא בורא מיני בשמים על איזה מין שהוא אף שבחול צריך לברך על כל מין כברכתו [דהיינו על עצי בשמים בורא עצי בשמים ועל עשבי בשמים בורא עשבי בשמים וכדלעיל בסימן רט\"ז ועי\"ש עוד כמה פרטים בזה] מ\"מ במו\"ש מברכין על הכל בורא מיני בשמים כדי שלא יבואו לטעות ההמון עם שאין הכל בקיאין בכל ברכה המיוחדת אבל בברכה זו יוצא על הכל וכמש\"כ שם בס\"א ומ\"מ לכתחלה טוב יותר שיקח לבשמים דבר שברכתו בורא מיני בשמים כגון המוסק שקורין פיז\"ם או נעגילע\"ך שגם זה להרבה אחרונים ברכתו הוא בורא מיני בשמים מותר לברך במ\"ב על פלפלין שקורין ענגילש\"ע פעפע\"ר שגם זה הוא בכלל בשמים אבל בסתם פלפלין יש דעות בין הפוסקים והוי ספק ברכה וכן זנגביל שקורין אינגבע\"ר:","(ב) א\"צ לחזור אחריהם - שאין מברכין עליהם אלא להשיב הנפש שהיא כואבת מיציאת השבת. כתבו האחרונים שאף מי שמתענה בשבת צריך לברך על הבשמים במו\"ש משא\"כ ביוה\"כ אף כשחל בשבת אין צריך לברך במוצאי יוה\"כ:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>אין מברכין על בשמים <i data-commentator=\"Turei Zahav\" data-order=\"2\"></i>של בית הכסא ולא על של מתים <small> (ודוקא) </small> הנתונים למעלה ממטתו של מת ולא על בשמים <i data-commentator=\"Turei Zahav\" data-order=\"3\"></i>שבמסיבת ע\"א דסתם מסיבתן לעכו\"ם. <small>הגה ואם בירך על בשמים אלו לא יצא <i data-commentator=\"Turei Zahav\" data-order=\"4\"></i>וצריך לחזור ולברך על <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>אחרים [ב\"י בשם א\"ח]:</small>","m":["(ג) של בית הכסא ולא וכו' - דכל זה לאו לריחא עבידי אלא לעבורי ריח הסרחון:","(ד) למעלה ממטתו - אבל נתונים לפני מטתו מברכין שאני אומר לכבוד חיים הם עשויים [ירושלמי]:","(ה) שבמסיבת עובדי כוכבים - היינו שמסובין לאכילה לסעודה אבל אם לא היו מסובין כלל מותר לברך על בשמים שלהן וכן מסיק הט\"ז להלכה בסימן רצ\"ח סק\"ה ומ\"מ כתב לבסוף דטוב לכתחלה לחוש לדעת רבינו יונה דס\"ל דסתם בשמים של עובדי כוכבים עומד לבסוף למכרן לע\"ג ואין לברך עליהן אם לא במקום שנראה שאין עומד לע\"ג כגון שהוא תגר שדרכו למכור אותם לאנשים הרבה או שדרכו לשום הבשמים לתבשיל שלו אז אין איסור לברך עליהם אפילו לדעת ר\"י:"]},{"s":"<i data-commentator=\"Turei Zahav\" data-order=\"5\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>שקים מלאים בשמים שמשימים עכו\"ם תוך קנקני היין אע\"פ <i data-commentator=\"Turei Zahav\" data-order=\"6\"></i>שמותר <i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>להריח בהם <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>אין מבדילין <i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i>עליהם:","m":["(ו) להריח בהם - שאין היין נותן בהם טעם כי אין דרך שיריחו בשמים מהיין אלא אדרבה הם נותנים טעם בהיין ועוד שאין מכוין המריח לריח היין אלא לריח התבלין:","(ז) אין מבדילין עליהם - דמאיס הוא לגבוה. כתב הט\"ז כאן ולעיל בסימן רי\"ז דאין מברכין על ריח שבכלי שנבלע בו ע\"י הבשמים שהיו בו מקודם. ואם רואה שבשולי הכלי יש אבק משיורי הבשמים כמו שרגילות בתיבות שמשימין בהם בשמים מותר לברך [אחרונים]:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>נהגו <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>לברך על ההדס כל היכא דאפשר: <small>הגה וי\"א דאין לברך <i data-commentator=\"Turei Zahav\" data-order=\"7\"></i>על הדס היבש דאינו מריח רק על שאר בשמים (טור בשם הר\"ר אפרים והר\"א מפראג) וכן נהגו במדינות אלו ונ\"ל דיש <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>להניח גם הדס עם הבשמים דאז עושין ככולי עלמא:</small>","m":["(ח) על ההדס - פי' דשל לולב כיון דאיתעביד ביה חדא מצוה ליעביד ביה מצוה אחריתא ודוקא בשאר ימות השנה ולא בסוכות דהוקצה למצותו ומש\"כ כל היכא דאפשר היינו כל היכא שיש בו עוד ריח קצת מצוה לכתחלה להדר אחריו וכ\"כ בזוהר וסמך לדבר ותחת הסרפד יעלה הדס וסמיך ליה שומר שבת מחללו וגו' והי\"א ס\"ל דכיון שנתיבש וניטל ממנו עיקר הריח אין לברך עליו:","(ט) עם הבשמים - ואם אין לו יכול לברך גם על עשבים שיש להם ריח טוב וכנ\"ל בסק\"א:","(י) דאז עושין ככו\"ע - עין בט\"ז שכתב על מה דאיתא בטור בשם רבינו אפרים שהיה לו זכוכית מיוחדת שהיו בה מיני בשמים והיה מברך עליהן דאף דלהלכה יש לצדד דיכול לברך במ\"ב גם על הבשמים שהיו מונחים בבית לצורך תבשיל כיון שנוטלן עתה בידו להריח בהן וכ\"כ בספר תוספת שבת בפשיטות מ\"מ רבינו אפרים עשה זה למצוה מן המובחר שייחד אותם מתחלה לשם ריח מצוה וכך נוהגין רוב העולם שמיחדין כלי לזה וקורין אותו הדס ע\"ש שהיו מניחין שם בדורות הראשונים הדס כדי להריח:"]},{"s":"<i data-commentator=\"Magen Avraham\" data-order=\"4\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i> מי שאינו מריח אינו מברך על הבשמים אלא א\"כ מתכוין להוציא <i data-commentator=\"Turei Zahav\" data-order=\"8\"></i>בני ביתו הקטנים שהגיעו לחינוך <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i>או להוציא מי שאינו <i data-commentator=\"Ba'er Hetev\" data-order=\"5\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"5\"></i>יודע:","m":["(יא) מי שאינו מריח - היינו שאין לו חוש הריח:","(יב) להוציא וכו' - וצריכין שיריחו תיכף אחר ברכתו:","(יג) או להוציא וכו' - כל האחרונים חולקין ע\"ז וסוברין דוקא להוציא ב\"ב הקטנים הוא דשרי שמוטל עליו כדי לחנכם במצות אבל לא להוציא מי שאינו יודע דכיון שהוא אינו חייב בדבר אינו יכול להוציא אחרים ידי חובתן דאף דבעצם קידוש והבדלה יכול להוציא לאחרים אע\"פ שאינו חייב בדבר כגון שיצא מכבר שאני התם שהן חובה על כל איש ישראל וכל ישראל ערבים זה בזה משא\"כ בזה שהוא רק מנהג החכמים ואין צריך לחזור אחריו וכדלעיל בס\"א הוא דומה לכל ברכת הנהנין שאינו יכול להוציא אחרים בברכתו אם אינו נהנה אז בעצמו וכדלעיל בסימן קס\"ז סי\"ט וע\"כ ה\"ה מי שהבדיל כבר ויש לו חוש הריח ובירך על הבשמים ובא להבדיל פעם אחרת בשביל אחרים יריח עוד בעצמו פעם אחרת כדי שיוכל עוד הפעם לברך במ\"ב. ודע דמה שנוהגין איזה אנשים שאין רוצין לצאת בברכת הנר והבשמים שאומר המבדיל ומברכין אותן לעצמן בשעה שאומר המברך ברכת המבדיל שלא כדין הם עושין דכיון שהם יוצאין בהבדלה צריכין להטות אזנם ולשמוע ברכת ההבדלה ולא לברך אז ברכה אחרת ולבד כ\"ז מצוה יותר לצאת כולם בברכתו דברוב עם הדרת מלך ולא לברך כ\"א בפני עצמו וכדלקמן בסימן רצ\"ח סי\"ד אם לא שהוא רחוק אז מן האור ולא יוכל להשתמש לאורה דאינו יוצא אז בברכת המברך וכדלקמן ברצ\"ח ס\"ד ובאופן זה לא יכוין לצאת בברכת הנר אלא יאחר אותה לאחר הבדלה כשיהיה סמוך אצל האש:\n"]}],"298":[{"s":"<b>דיני נר הבדלה. ובו טו סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>מברך <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>על הנר בורא מאורי האש אם יש לו <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>ואינו צריך לחזור אחריו וה\"מ במוצאי שבת <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>אבל <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>במוצאי יוה\"כ י\"א שמחזר <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>אחריו: <small>הגה מי שאין לו כוס להבדיל כשרואה האש מברך עליו וכן הבשמים (טור):</small>","m":["(א) מברך על הנר וכו' - משום דתחלת ברייתו הוי במו\"ש כדאמרינן בפסחים דף נ\"ד במו\"ש נתן הקב\"ה דעה באדה\"ר וטחן ב' אבנים זו בזו ויצא מהן אור והא דמברכין במוצאי יוה\"כ אף כשאינו חל במו\"ש מפני שהוא כעין הבדלה שכל היום היה אסור להשתמש בזה האור אף לאוכל נפש ולא כמו בשאר יו\"ט ועכשיו מותר ולכך דעת הי\"א דצריך לחזור אחריו כמו להבדלה:","(ב) בורא מאורי האש - דכמה נהורא איכא בנורא לבנה אדומה וירוקה ואם אמר מאור האש דעת הב\"ח דלא יצא אפילו בדיעבד. ואם אמר ברא מאורי האש לשון עבר יצא:","(ג) וא\"צ לחזור אחריו - שאין מברכין אלא לזכר שנברא האור במו\"ש וכנ\"ל וע\"כ יוכל לברך על הכוס אפילו בלא נר ומתי שיזדמן לו אח\"כ שיראה אש ויהנה לאור יברך בורא מאורי האש ואך דוקא בליל מו\"ש ולא יותר דעבר זמנו וכדלקמן בסי' רצ\"ט ס\"ו:","(ד) מי שאין לו כוס וכו' - ואם משער שיזדמן לו כוס בלילה ורוצה ללמוד קודם שיבוא לידו הכוס מצדד הגרע\"א בחידושיו שלא יברך עתה על הנר וטוב יותר שיסדרם על הכוס:"]},{"s":"<i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"1\"></i> <i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>מצוה מן המובחר לברך <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>על אבוקה <i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>ויש מי שאומר שאם אין לו <i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>אבוקה צריך להדליק נר אחר לצורך הבדלה חוץ מהנר המיוחד להאיר בבית: <small>הגה ונר שיש לו <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i>שתי פתילות מקרי אבוקה. (אגודה):</small>","m":["(ה) על אבוקה - שאורה רב וטוב להדר שיהיה של שעוה [מ\"א בשם כונת האר\"י] עוד כתב בשם ס\"ח דלא יקח עצי דמשחן שקורין קי\"ן בל\"א מפני שריחו רע ונראה דהיינו אותן שנשמע מהן ריח רע של זפת והנה לעיל בסימן רס\"ד איתא דגם בנר של זפת גופא מדליקין בליל שבת וכן בעיטרן שבודאי ריחו רע אפ\"ה היו מדליקין בו אי לאו משום שמא יניח ויצא באמצע הסעודה ובודאי לא עדיף אור הבדלה שאין צריך לחזור אחריו מנר שבת שהוא חובה ואולי דכונת הס\"ח שאין זה מן המובחר אף שאורו רב מפני ריחו הרע אבל לא גריע משאר נר שאינו אבוקה גם בפמ\"ג כתב שאם אין לו נר אחר יכול לברך עליו:","(ו) נר אחר - משום היכר שהוא לשם מצוה ונראה דמיירי באופן שאינו יכול לקרב את הנר הזה לנר שבביתו דאל\"ה הרי יכול לקיים מצות אבוקה:","(ז) לצורך הבדלה - וכ\"ז הוא רק למצוה בעלמא ולא לעיכובא [מאמר מרדכי]:","(ח) ונר שיש לו שתי פתילות - סתם נר שבגמרא ופוסקים היינו נר של שמן וקמ\"ל דכיון שאורותיהן מגיעין זה לזה למעלה הוי אבוקה ובנר שלנו אם מונח שם כמה פתילות הוי כמו פתילה עבה ואינה חשובה אבוקה אך אם מפריד ביניהם שעוה או חלב כגון מה שעושין משעוה שהנרות קלועים יחד או שמדביק יחד שתי נרות להדדי בעת הברכה זהו ג\"כ חשיב אבוקה ומשמע מדברי המ\"א שיראה שיגיעו המאורות להדדי דאז חשיב אבוקה:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i>נוהגים להסתכל <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i><i data-commentator=\"Turei Zahav\" data-order=\"2\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"4\"></i>בכפות הידים ובצפרנים: <small>הגה ויש לראות בצפרני יד ימין ולאחוז הכוס ביד שמאל ויש לכפוף האצבעות לתוך היד שאז רואה הצפרנים עם הכפות בבת אחת ולא יראה פני האצבעות שבפנים (זוהר פ' בראשית ובפ' ויקהל):</small>","m":["(ט) נוהגים להסתכל וכו' - הטעם דהא בעינן שיוכל להכיר לאורו בין מטבע למטבע וכדלקמיה ולכך נוהגים להסתכל בצפרנים לראות אם יוכל ליהנות לאורו ולהכיר בין מטבע למטבע כמו שמכיר בין צפורן לבשר ועוד שהצפרנים הן סימן ברכה שהן פרות ורבות לעולם וגם מסתכלים בכפות ידים שיש בשרטוטי היד סימן להתברך בו:","(י) לכפוף האצבעות - היינו הד' אצבעות על גב האגודל:","(יא) שאז רואה וכו' - ויש נוהגין לפשוט אח\"כ הד' אצבעות ולראות מאחריהם על הצפרנים [מ\"א בשם ס' הכונות]:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"7\"></i>אין מברכין על הנר עד שיאותו לאורו <i data-commentator=\"Be'er HaGolah\" data-label=\"ח\" data-order=\"8\"></i>דהיינו שיהיה סמוך לו בכדי שיוכל להכיר בין מטבע מדינה זו למטבע מדינה אחרת:","m":["(יב) דהיינו שיהיה סמוך - ואפילו אם הוא עומד חוץ לבית כל שהאור גדול שיוכל להכיר במקום שעומד מקרי דבר זה נהנה לאורה ויכול לברך [גמרא]:","(יג) שיוכל להכיר - וע\"כ אם הוא יוצא בברכת הבדלה מאחרים ורוצה לצאת גם בברכת במ\"ה יקרב עצמו אצל האש כשיעור זה כדי שיהיה יוכל לצאת גם בברכת בורא מאורי האש ועיין מש\"כ לעיל בסוף סימן רצ\"ז:","(יד) אין מברכין וכו' - ואפילו בדיעבד לא יצא:"]},{"s":"<i data-commentator=\"Magen Avraham\" data-order=\"6\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ט\" data-order=\"9\"></i>אין מברכין על הנר שלא <i data-commentator=\"Ba'er Hetev\" data-order=\"5\"></i>שבת ממלאכת עבירה לאפוקי אור שהודלק <i data-commentator=\"Magen Avraham\" data-order=\"7\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"6\"></i>לחיה ולחולה שכיון שלא הודלק לעבירה מברכין עליו אבל אם הדליקו עכו\"ם בשבת כיון <i data-commentator=\"Turei Zahav\" data-order=\"3\"></i>שאם היה מדליקו ישראל היה עובר לא שבת ממלאכת עבירה מיקרי ואין מברכין <i data-commentator=\"Turei Zahav\" data-order=\"4\"></i>על <i data-commentator=\"Magen Avraham\" data-order=\"8\"></i>אור של <i data-commentator=\"Ba'er Hetev\" data-order=\"7\"></i>ע\"א <small> (טור)</small>:","m":["(טו) שלא שבת וכו' - היינו שהודלק באיסור בשבת ואפילו רק בבין השמשות:","(טז) לחיה ולחולה - אם אין בהם סכנה דוקא ע\"י א\"י אבל ע\"י ישראל כיון שאסור לו להדליק בשבילם מקרי שלא שבת ממלאכת עבירה אבל כשיש בהם סכנה אפילו ע\"י ישראל וכ\"ש ע\"י א\"י ואין חילוק בין אם הדליק להחולה ממדורת ישראל או ממדורה של עצמו כיון שהוא לצורך ישראל ובהיתר הודלק:","(יז) אם הדליקו א\"י - היינו אפילו לצורך עצמו:","(יח) בשבת - ואפילו אם אין אנו יודעין תלינן שמסתמא הדליקו בשבת [ב\"ח וכן מוכח בגמרא]:","(יט) של עבודת גלולים - ואפילו אם לא הודלק רק במו\"ש דהטעם משום דהודלק לכבוד ע\"ג ואסור ליהנות ממנו ודוקא כשהשלהבת קשורה בנר או בגחלת של ע\"ג דכיון שהגחלת יש בו ממש והשלהבת קשורה בו חל האיסור גם על השלהבת ולכן אין לברך עליה אבל אם ישראל הדליק נר מנר של ע\"ג שרי לברך עליה דבזה אין כאן ממשו של איסור רק השלהבת לחוד והשלהבת אין בו ממש [מ\"א בשם רש\"ל] ועיין בפמ\"ג שמצדד דמ\"מ לכתחלה אסור לישראל להדליק נרו מנר של עבו\"ג אלא דאם הדליק רשאי לברך עליה עי\"ש:"]},{"s":"<i data-commentator=\"Turei Zahav\" data-order=\"5\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"י\" data-order=\"10\"></i>עכו\"ם שהדליק במוצאי שבת מישראל <i data-commentator=\"Turei Zahav\" data-order=\"6\"></i>או <i data-commentator=\"Magen Avraham\" data-order=\"9\"></i>ישראל מעכו\"ם <i data-commentator=\"Ba'er Hetev\" data-order=\"8\"></i>מברכין עליו <i data-commentator=\"Magen Avraham\" data-order=\"10\"></i>אבל עכו\"ם שהדליק מעכו\"ם <i data-commentator=\"Magen Avraham\" data-order=\"11\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"9\"></i>אין מברכין עליו <i data-commentator=\"Turei Zahav\" data-order=\"7\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"כ\" data-order=\"11\"></i>ובמוצאי יוה\"כ <i data-commentator=\"Ba'er Hetev\" data-order=\"10\"></i>אין מברכין על נר שהדליק ישראל מעכו\"ם <small> (ועיין לקמן סי' תרכ\"ד סעיף ה'):</small>","m":["(כ) שהדליק במו\"ש מישראל - וקמ\"ל בזה אף דאין מברכין על אור שהדליק הא\"י מא\"י אחר אף במו\"ש דהודלק בהיתר וכדלקמיה התם משום דגזרינן אטו א\"י ראשון שהוא הדליקו בשבת שלא יבוא לברך על אורו אבל הכא לא שייך זה ולכך מותר ומיירי שלא הדליק הא\"י הנר במסיבת א\"י אחרים דאל\"ה אמרינן סתם מסבת עובדי גלולים לעבודת גלולים ואסור לברך על הנר וכדלעיל בסימן רצ\"ז ס\"ב לענין בשמים:","(כא) או ישראל מא\"י - היינו אפילו אם הא\"י הדליק הנר שלו בשבת אפ\"ה שרי דהא ע\"י הדלקת הישראל ניתוסף אור של היתר על מקצת האור שיש בו מן האור הראשון ועל התוספת של היתר הוא מברך:","(כב) אבל א\"י שהדליק וכו' - ולא אמרינן בזה דאתוספת אור של היתר שהדליק א\"י זה במו\"ש הוא מברך דגזרו אטו א\"י ראשון ואף דגם על הנר של הא\"י הראשון היה אפשר מן הדין לברך עליו דהא ניתוסף במו\"ש עליו אור של היתר [דמטבע האש להיות ניתוסף עליו תמיד אור חדש] גזרו חכמים אטו עמוד ראשון דהיינו שיבוא לברך סמוך לחשיכה מיד בעוד שלא ניתוסף ההיתר [גמרא] וכתב המ\"א דבדיעבד יצא בזה וא\"צ לחזור ולברך כיון דאינו אלא משום גזירה וכ\"כ ש\"א:","(כג) אין מברכין עליו - אם הוציא הא\"י אש מעצים ואבנים במו\"ש מותר לברך בורא מאורי האש על אותו האש דלא שייך למיגזר כאן אבל אם הדליק הא\"י נר מזה האש יש לצדד להחמיר דאתי למיחלף ולהתיר גם בנר שהודלק בנר שלא שבת [א\"ר ודה\"ח דלא כרמ\"ע]:","(כד) אין מברכין על נר וכו' - מפני שאורו של א\"י נעשה בו מלאכה שהודלק ביוה\"כ ואף דבמו\"ש מברכין על נר זה התם הטעם שהוא מברך על תוספת שלהבת של היתר שניתוסף ע\"י הדלקת הישראל והתוספת הזה כיון שהוא נולד עכשיו הו\"ל כאור היוצא מעצים ואבנים במו\"ש דמותר לברך עליו משא\"כ במוצאי יוהכ\"פ מבואר לקמיה בס\"ח דאין מברכין על אור היוצא מעצים ואבנים:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ל\" data-order=\"12\"></i>היה הולך חוץ לכרך <i data-commentator=\"Magen Avraham\" data-order=\"12\"></i>וראה <i data-commentator=\"Ba'er Hetev\" data-order=\"11\"></i>אור <i data-commentator=\"Magen Avraham\" data-order=\"13\"></i>אם רובן עכו\"ם אין מברכין עליו ואם רובן ישראל או אפילו מחצה על מחצה מברכין עליו:","m":["(כה) ואם רובן ישראל - ותלינן שהאור הוא של ישראל ומיירי שהוא סמוך כ\"כ שיכול להשתמש לאורו כמ\"ש ס\"ד:","(כו) מברכין עליו - לפי שגם תחלת בריית האור היה במו\"ש ע\"י אדה\"ר ע\"ד זה שהקיש אבנים זה בזה וזה אין שייך במוצאי יוה\"כ שלא היה אז תחלת ברייתו וטעם ברכתו הוא לפי שכל היום היה אסור לו להשתמש בהאור ועכשיו הותר לו לכן אין לברך אלא באור ששבת דהיינו שהיה דלוק מבע\"י ושבת כל יוה\"כ שלא היו יכולין להשתמש בו ועכשיו הותר:"]},{"s":"<i data-commentator=\"Turei Zahav\" data-order=\"8\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"מ\" data-order=\"13\"></i>אור היוצא מהעצים והאבנים <i data-commentator=\"Magen Avraham\" data-order=\"14\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"12\"></i>מברכין עליו אבל במוצאי יוה\"כ אין מברכין עליו:","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"נ\" data-order=\"14\"></i>גחלים הבוערות כל כך שאילו מכניס קיסם ביניהם הוא נדלק מברכין עליהם והוא שעשוים להאיר:","m":["(כז) להאיר - אבל אם עשויין כדי להתחמם אין מברכין עליהן שאפילו על הנר אין לברך אם אין עשוי להאיר וכדלקמיה בסי\"א:","(כח) נר בהכ\"נ - ונר של בהמ\"ד שבימינו מסתברא דתלוי לפי המקום אם לומדים שם ומדליקין בשביל זה הרי נעשה להאיר:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ס\" data-order=\"15\"></i>אור של כבשן בתחילת שריפת הלבנים אין מברכין עליו שאז אינו עשוי להאיר ואחר שנשרפו אז עשוי להאיר מברכין עליו:","m":[]},{"s":" נר בית הכנסת <i data-commentator=\"Turei Zahav\" data-order=\"9\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ע\" data-order=\"16\"></i>אם יש שם אדם חשוב מברכין עליו ואם לאו אין מברכין עליו <i data-commentator=\"Be'er HaGolah\" data-label=\"פ\" data-order=\"17\"></i>וי\"א בהפך <i data-commentator=\"Be'er HaGolah\" data-label=\"צ\" data-order=\"18\"></i>ואם יש <i data-commentator=\"Magen Avraham\" data-order=\"15\"></i>שמש <i data-commentator=\"Ba'er Hetev\" data-order=\"13\"></i>שאוכל שם מברכין עליו והוא שלא תהא לבנה זורחת שם:","m":["(כט) אם יש שם אדם חשוב - אז נעשה להאיר וכשאין אדם חשוב נעשה לכבוד השכינה והי\"א ס\"ל להיפך דכשיש אדם חשוב נעשה לכבודו ולא להאיר ובדליכא אדם חשוב שרי דנעשה להאיר מיהו אם יכבנו ויחזור וידליקנו לצורך הבדלה ודאי שרי לכו\"ע בכל ענין. איתא בב\"י דבארצותינו נוהגין להדליק בבהכ\"נ נר מיוחד כדי להבדיל עליו. כתב בספר א\"ר דמדתלינן כאן באדם חשוב ש\"מ דכל כי האי גוונא כגון שמדליק נר בביתו לכבוד אדם חשוב שבא אליו אין מברכין עליו:","(ל) מברכין עליו - שעשוי להאיר לאכילתו ומיירי שאוכל בבית הסמוך לבהכ\"נ והחלונות פתוחים לו דבבהכ\"נ אסור לאכול כמ\"ש סימן קנ\"א. איתא ברא\"ש והעתיקו האחרונים דהאידנא אין מברכין כלל על נר של בהכ\"נ שאין מדליקין בו רק לכבוד שהרי דולקין הנרות אף ביום והכונה על אותן שדולקין לפני העמוד שהם רק לכבוד אבל אותן שלוקחין כ\"א בידו להאיר מברכין [דה\"ח] וכמה אנשים נכשלין בזה שלוקחין מנרות של העמוד על הבדלה ואין נכון לעשות כן ואולי כשרוצה לצרף מהן לאבוקה אין להקפיד. ונראה פשוט דעל נר יארצייט אין לברך שאינו עשוי להאיר רק לזכר נשמת המת:","(לא) שלא תהא לבנה - שאם יש לבנה א\"צ השמש לאור הנר ולא נעשה אלא לכבוד השכינה:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ק\" data-order=\"19\"></i>אין מברכין <i data-commentator=\"Magen Avraham\" data-order=\"16\"></i>על נר <i data-commentator=\"Ba'er Hetev\" data-order=\"14\"></i>של מתים שאינו עשוי להאיר הלכך מת שהיו מוליכין לפניו נר אילו הוציאוהו ביום והוציאוהו בלילה בנר אין מברכין עליו:","m":["(לב) שאינו עשוי להאיר - רק שמדליקין אותן לכבוד המת:","(לג) אין מברכין עליו - כיון שגם ביום היו מוליכין לפניו א\"כ הוא לכבוד אע\"פ שצריכין לו עתה בלילה. וכתב המ\"א דה\"ה על נר שמדליקין לכבוד החתן אין מברכין:"]},{"s":"<i data-commentator=\"Ateret Zekenim\" data-label=\"♦\" data-order=\"2\"></i> <i data-commentator=\"Be'er HaGolah\" data-label=\"ר\" data-order=\"20\"></i>סומא <i data-commentator=\"Magen Avraham\" data-order=\"17\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"15\"></i>אינו מברך:","m":["(לד) אינו מברך - דהא בעינן שיאותו לאורו עד שיהא יכול להכיר בין מטבע למטבע וכדלעיל בס\"ד ובסומא לא שייך זה ועיין בפמ\"ג דנשאר בצ\"ע אם יכול להוציא אחרים בברכה זו כיון שהוא בעצמו פטור מן הדבר וכ\"ז דוקא בברכת במ\"ה אבל שאר הבדלה אומר [מ\"א וא\"ר וש\"א]:","(לה) היו יושבין וכו' - מיירי שהבדילו מכבר ולא היה להם אז אור בסמוך להם שיהיו נאותין לאורו ועתה נזדמן להם או שיודעין שלא יהיה להם כוס בלילה דאי מצפין שיהיה להם כוס מוטב שימתינו בברכת הנר ויסדרו על הכוס וכמש\"כ לעיל בסק\"ד:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ש\" data-order=\"21\"></i>היו יושבים בבית המדרש והביאו להם אור <i data-commentator=\"Turei Zahav\" data-order=\"10\"></i><i data-commentator=\"Magen Avraham\" data-order=\"18\"></i>אחד מברך לכולם:","m":["(לו) אחד מברך לכולם - ואע\"ג דצריכין כולם לשתוק ולשמוע ברכתו והוי בטול בהמ\"ד וא\"כ היה טוב יותר שיברך כ\"א לעצמו אפ\"ה הא עדיפא משום ברב עם הדרת מלך [גמרא]. כתבו האחרונים דאפילו מי שכבר בירך במ\"ה יכול לחזור ולברך להוציא ב\"ב:"]},{"s":" <i data-commentator=\"Be'er HaGolah\" data-label=\"ת\" data-order=\"22\"></i>נר בתוך חיקו או בתוך פנס <small>[פי' כלי שנותן הנר שלא תכבה] </small> או בתוך אספקלריא <i data-commentator=\"Magen Avraham\" data-order=\"19\"></i>רואה את השלהבת ואינו משתמש לאורה <i data-commentator=\"Magen Avraham\" data-order=\"20\"></i>משתמש לאורה ואינו רואה את השלהבת אין מברכין עליה עד שיהא רואה את השלהבת ומשתמש <i data-commentator=\"Ba'er Hetev\" data-order=\"16\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"16\"></i>לאורה:","m":["(לז) נר בתוך חיקו - היינו שהיתה טמונה בתוך חיקו שאינו רואה השלהבת ולא נשתמש לאורה וכן פנס כה\"ג והדר מוסיף אספקלריא דאע\"פ שהוא רואה את האור דרך האספקלריא מ\"מ לא מקרי זה ראיה ממש לענין ברכת במ\"ה דבעינן שיהיה האור מגולה והמ\"א ושארי אחרונים כתבו דדוקא בפנס שהיא של ברזל אף שיש בה נקבים אין רואה השלהבת להדיא אבל באספקלריא של זכוכית מקרי רואה השלהבת ויכול לברך עליה כשהיא בסמוך לו שיוכל להשתמש לאורה ועיין בביאור הלכה שהבאנו דכמה פוסקים סוברים כדעת השו\"ע וע\"כ אין כדאי לכתחלה להקל בזה:","(לח) ואינו משתמש לאורה - כגון שעומד מרחוק ולא יוכל להכיר בין מטבע למטבע:","(לט) ואינו רואה וכו' - כגון שעומד מן הצד:"]}],"299":[{"s":"<b>שלא לאכול ולא לעשות שום מלאכה קודם שיבדיל. ובו י סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>אסור לאכול שום דבר או אפי' לשתות יין או שאר משקין חוץ ממים <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i><i data-commentator=\"Magen Avraham\" data-order=\"1\"></i><i data-commentator=\"Turei Zahav\" data-order=\"1\"></i>משתחשך עד שיבדיל אבל אם היה יושב ואוכל מבע\"י וחשכה לו <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>אין צריך להפסיק <small>[אפילו משתייה ב\"י] </small> ואם היה יושב ושותה וחשכה לו צריך להפסיק <i data-commentator=\"Turei Zahav\" data-order=\"2\"></i><i data-commentator=\"Magen Avraham\" data-order=\"3\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>ויש אומרים דהני מילי בספק חשיכה אבל בודאי חשיכה אפילו היה יושב ואוכל פורס מפה ומבדיל וגומר סעודתו: <small>הגה והמנהג פשוט כסברא הראשונה:</small>","m":["(א) משתחשך - ואפילו בספק חשיכה ועיין לעיל בסימן רס\"א במ\"ב דנקטינן לספק חשיכה תיכף מששקעה החמה לענין הדלקת הנרות וכל מלאכה ומ\"מ נ\"ל דלענין אכילת סעודה שלישית אם לא אכל מקודם בודאי צריך לאכול אפילו אחר שקיעה ואפילו לשאר אכילה אם הוא תאב לאכול ולשתות ג\"כ אין להחמיר עד חצי שעה שקודם צה\"כ. כתב המ\"א דמה שכתב המחבר משתחשך מיירי כשלא התפלל ערבית אבל אם התפלל ערבית אפילו אם התפלל מבע\"י [דיש אופן שמותר וכבסי' רצ\"ג] חלה עליו חובת הבדלה ואסור לאכול עד שיבדיל על הכוס:","(ב) יושב ואוכל - ואפילו רק התחלה בעלמא שבירך ברכת המוציא מבע\"י ונשתהה לאכול עד שחשכה [אחרונים]:"]},{"s":"<i data-commentator=\"Turei Zahav\" data-order=\"3\"></i><i data-commentator=\"Magen Avraham\" data-order=\"4\"></i>היו <i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>שותים ואמרו בואו ונבדיל <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i>אם רצו לחזור ולשתות קודם הבדלה <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>אינם צריכים לחזור ולברך <i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>ויש מי שחולק בדבר:","m":[]},{"s":"<i data-commentator=\"Turei Zahav\" data-order=\"4\"></i>כשמפסיק להבדיל <i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>אינו צריך לברך בפה\"ג על כוס של <i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i>הבדלה <i data-commentator=\"Magen Avraham\" data-order=\"6\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i>וי\"א שצריך:","m":[]},{"s":"כשהיה אוכל וחשכה שאמרנו שאינו צריך להפסיק <i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"7\"></i>גומר סעודתו <i data-commentator=\"Magen Avraham\" data-order=\"7\"></i>ומברך בהמ\"ז <i data-commentator=\"Ba'er Hetev\" data-order=\"5\"></i>על הכוס ואח\"כ מבדיל עליו <i data-commentator=\"Be'er HaGolah\" data-label=\"ח\" data-order=\"8\"></i>ואם יש לו שני כוסות מברך בהמ\"ז על אחד ומבדיל על אחר:","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ט\" data-order=\"9\"></i>טעה ואכל קודם שהבדיל יכול להבדיל אח\"כ:","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"י\" data-order=\"10\"></i>שכח ולא הבדיל במוצאי שבת מבדיל עד סוף יום ג' <i data-commentator=\"Be'er HaGolah\" data-label=\"כ\" data-order=\"11\"></i>וי\"א שאינו מבדיל אלא כל יום ראשון ולא יותר ודוקא בפה\"ג ומבדיל בין קודש לחול אבל על נר ובשמים <i data-commentator=\"Be'er HaGolah\" data-label=\"ל\" data-order=\"12\"></i>אינו מברך אלא במוצאי שבת <i data-commentator=\"Be'er HaGolah\" data-label=\"מ\" data-order=\"13\"></i>ויש מי שאומר דהא דקי\"ל טעם מבדיל ה\"מ היכא דהבדיל בליל מו\"ש אבל אם לא הבדיל בלילה כיון שטעם שוב אינו מבדיל: <small>הגה והעיקר כסברא הראשונה ומי שמתענה ג' ימים וג' לילות ישמע <i data-commentator=\"Magen Avraham\" data-order=\"8\"></i>הבדלה <i data-commentator=\"Ba'er Hetev\" data-order=\"6\"></i>מאחרים ואם אין אחרים אצלו יכול להבדיל <i data-commentator=\"Ba'er Hetev\" data-order=\"7\"></i>בשבת <i data-commentator=\"Magen Avraham\" data-order=\"9\"></i>מבעוד יום ולשתות ולקבל אח\"כ התענית עליו. [ת\"ה סי' קנ\"ט] עיין סי' תקנ\"ג:</small>","m":["(ג) מבעוד יום - דוקא בזה שהתחיל לאכול בהיתר אבל אם התחיל באיסור פוסק ומבדיל אך בלא\"ה צריך לפסוק משום ק\"ש של ערבית שהיא דאורייתא אם התחיל לאכול בתוך חצי שעה שקודם צה\"כ וכדלעיל בסימן רל\"ה ואין לסמוך על קריאת השמש לבהכ\"נ [ואפילו במקום שדרך לקרות] אלא אם רגיל לילך לבהכ\"נ במו\"ש [מ\"א וש\"א]:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"נ\" data-order=\"14\"></i>המבדיל על יין <i data-commentator=\"Turei Zahav\" data-order=\"5\"></i>על <i data-commentator=\"Ba'er Hetev\" data-order=\"8\"></i>שלחנו אפילו הבדיל קודם שנטל ידיו פוטר היין שבתוך המזון שאין צריך לברך עליו <i data-commentator=\"Be'er HaGolah\" data-label=\"ס\" data-order=\"15\"></i>וי\"א דלא פטור אלא א\"כ נטל ידיו קודם שהבדיל: <small>הגה <i data-commentator=\"Turei Zahav\" data-order=\"6\"></i>ואם הבדיל <i data-commentator=\"Ba'er Hetev\" data-order=\"9\"></i>תחלה <i data-commentator=\"Magen Avraham\" data-order=\"10\"></i>צריך לברך אחריו ברכת מעין שלש: [תוספות ומרדכי פרק כיצד מברכין]:</small>","m":[]},{"s":" כשפוטר יין שבתוך המזון שאין צריך לברך עליו <i data-commentator=\"Be'er HaGolah\" data-label=\"ע\" data-order=\"16\"></i>גם א\"צ לברך ברכה אחרונה על כוס של הבדלה ואם אין לו אלא כוס אחד וסבור שיביאו לו יין יותר והבדיל על אותו כוס ואח\"כ לא הביאו לו יותר ובירך בהמ\"ז בלא כוס <i data-commentator=\"Be'er HaGolah\" data-label=\"פ\" data-order=\"17\"></i>יש מי שאומר <i data-commentator=\"Magen Avraham\" data-order=\"11\"></i><i data-commentator=\"Turei Zahav\" data-order=\"7\"></i>שצריך לברך ברכה אחרונה על כוס <i data-commentator=\"Ba'er Hetev\" data-order=\"10\"></i>של הבדלה:","m":["(ד) א\"צ להפסיק - ואפילו לק\"ש ותפלה א\"צ להפסיק באמצע סעודתו כיון שהתחיל מבע\"י דהיה בהיתר ואין להחמיר בזה להפסיק שאם היה מפסיק באמצע נראה כמגרש המלך ודומה לזה דרשו במכילתא זכור ושמור שמרהו ביציאתו כאדם שאינו רוצה שילך אוהבו מאצלו כ\"ז שיכול. ואם הפסיק תוך הסעודה והתפלל כתב המ\"א דאפשר דחלה עליו חובת הבדלה ואסור לאכול עד שיבדיל:","(ה) יושב ושותה וחשכה לו - היינו שישב לשתות מבע\"י ולא בתוך הסעודה וחשכה לו ואפילו אם רק נעשה ספק חשיכה צריך להפסיק דשתיה לאו דבר חשוב הוא שתועיל התחלתו מבע\"י:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"צ\" data-order=\"18\"></i>אם רוצה לסעוד תיכף להבדלה צריך ליזהר שלא יביא לחם לשלחן קודם הבדלה ואם הביא פורס עליו מפה ומכסנו לפי שהוא <i data-commentator=\"Turei Zahav\" data-order=\"8\"></i>מוקדם בפסוק <i data-commentator=\"Magen Avraham\" data-order=\"12\"></i>וצריך להקדימו אם לא יכסנו:","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ק\" data-order=\"19\"></i>אסור לעשות שום מלאכה קודם שיבדיל <i data-commentator=\"Be'er HaGolah\" data-label=\"ר\" data-order=\"20\"></i>ואם הבדיל בתפלה מותר אע\"פ שעדיין לא הבדיל על הכוס ואם צריך לעשות מלאכה קודם שהבדיל בתפלה <i data-commentator=\"Magen Avraham\" data-order=\"13\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ש\" data-order=\"21\"></i>אומר <i data-commentator=\"Ba'er Hetev\" data-order=\"11\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"11\"></i>המבדיל בין <small>[הקודש ובין החול] </small> <i data-commentator=\"Magen Avraham\" data-order=\"14\"></i>בלא ברכה ועושה מלאכה: <small>הגה <i data-commentator=\"Magen Avraham\" data-order=\"15\"></i>וכן נשים <i data-commentator=\"Magen Avraham\" data-order=\"16\"></i>שאינם מבדילין <i data-commentator=\"Ba'er Hetev\" data-order=\"12\"></i>בתפלה יש ללמדם שיאמרו המבדיל בין קודש לחול קודם שיעשו מלאכה [כל בו] וי\"א דכל זה במלאכה גמורה <i data-commentator=\"Turei Zahav\" data-order=\"9\"></i>כגון כותב ואורג אבל <i data-commentator=\"Magen Avraham\" data-order=\"17\"></i>הדלקת <i data-commentator=\"Ba'er Hetev\" data-order=\"13\"></i>הנר בעלמא או הוצאה מרשות לרשות אין צריך לזה [רי\"ו ני\"ב תי\"ט] ומזה נתפשט המנהג להקל שמדליקים נרות מיד שאמר הקהל <i data-commentator=\"Ba'er Hetev\" data-order=\"14\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"14\"></i>ברכו אבל העיקר כסברא ראשונה וי\"א לדלות מים בכל מוצאי שבת כי בארה של מרים סובב כל מוצאי שבת כל הבארות ומי שפוגע בו וישתה ממנו יתרפא מכל תחלואיו [כל בו] ולא ראיתי למנהג זה וע\"ל סי רס\"ג מי שמוסיף מחול על הקודש אם מותר לומר לאחר שהבדיל לעשות לו מלאכה:</small>","m":["(ו) וי\"א דה\"מ וכו' - קאי על מה שכתב בדעה קמייתא דבהתחיל מבע\"י אין צריך להפסיק אפילו כשנעשה ודאי חשיכה ולדעה זו צריך להפסיק אבל לענין לכתחלה אין נ\"מ בין דעה זו לדעה קמייתא דאף לדעה קמייתא אסור להתחיל לאכול אפילו בספק חשיכה:","(ז) היו שותים - היינו בתוך אכילתן והתחלת אכילה היתה מבעוד יום ולכך ס\"ל להדעה קמייתא דכיון שלא היו צריכין להפסיק אף שחשכה וכדלעיל בס\"א האמירה שאמרו בואו ונבדיל אין מזיק לזה ורשאין לאכול ולשתות וא\"צ לחזור ולברך שלא הסיחו דעתם ע\"י אמירה זו אבל כשהיו עוסקים בשתיה לבד דצריך להפסיק כשחשכה וכדלעיל אם אמרו בואו ונבדיל לכו\"ע הסיחו דעתם מהשתיה ואם רוצים לשתות עוד [אע\"פ שאינם רשאים] צריכים לחזור ולברך:","(ח) בדבר - ס\"ל דכיון שאמרו בואו ונבדיל צריכין לחזור ולברך והעיקר כדעה קמייתא:","(ט) כשמפסיק להבדיל - היינו אפילו אם היה קבוע מתחלה לשתיה לבד דמחוייב להפסיק אפ\"ה א\"צ לברך עתה בפה\"ג שנפטר בברכת בפה\"ג שבירך על שתיה הראשונה ואצ\"ל אם קאי באמצע אכילתו שא\"צ מן הדין להפסיק ורוצה עתה להבדיל על היין שא\"צ לברך עליו בפה\"ג אם כבר בירך בפה\"ג על היין שבתוך הסעודה או שלפני הסעודה וכן אם מבדיל על השכר בתוך הסעודה א\"צ לברך שהכל אפילו אם לא בירך כלל שהכל מתחלה שברכת המוציא פוטרת אותה:","(י) וי\"א שצריך - ס\"ל דכוס של הבדלה הוא ענין בפ\"ע ואין שייך לסעודה והעיקר כדעה א' ומ\"מ טוב ליזהר לכתחלה שלא להבדיל בסעודה לא על השכר ולא על היין אם כבר בירך מתחלה על היין ואם הוא מוכרח להפסיק ולהבדיל כגון שהיה עוסק מתחלה בשתיה לבד לא יברך דהעיקר כדעה א':","(יא) ומברך וכו' - היינו למ\"ד בהמ\"ז טעונה כוס ועיין סימן קפ\"ב ס\"א:","(יב) על הכוס - ואינו טועמו עד אחר הבדלה כדי שלא יפגמנו:","(יג) ואם יש לו שני כוסות וכו' - הטעם דאין אומרים שתי קדושות על כוס אחד ורישא דאין לו כ\"א אחד שאני:","(יד) מברך בהמ\"ז - ומותר לשתות מהכוס אף שהוא קודם הבדלה דכוס של בהמ\"ז שייך לסעודה. וכ\"ז למי שנזהר תמיד לברך על כוס אבל למי שמברך לפעמים בלא כוס לפי שסומך על הפוסקים שס\"ל דאין בהמ\"ז טעונה כוס אסור לו לשתות עתה מהכוס של בהמ\"ז קודם הבדלה [מ\"א וש\"א] וכתב הח\"א דזה דוקא אם הוא כבר ודאי חשיכה אבל אם הוא ספק חשיכה נראה דיכול לשתות מכוס של בהמ\"ז אף מי שאינו נזהר תמיד לברך על הכוס:","(טו) טעה ואכל וכו' - וה\"ה אם הזיד ואכל אף דעבר במזיד מ\"מ צריך להבדיל אח\"כ בלילה אלא אורחא דמילתא נקט וכן מה שכתב אח\"כ בס\"ו שכח ולא הבדיל ה\"ה בהזיד ולא הבדיל:","(טז) מבדיל עד סוף וכו' - דכל אלו הג' ימים שייכים עוד לשבת העבר ומכאן והלאה שייכים לשבת הבאה ומ\"מ לכו\"ע לכתחלה יקדים להבדיל ביום א' דזריזין מקדימין למצות וגם דאסור לו לאכול קודם שיבדיל כיון דבידו הוא להבדיל. כתב בחידושי רע\"א בשם ספר לשון חכמים דבמוצאי יו\"ט אין להבדלה תשלומין דבשבת שייך לומר דהג' ימים ראשונים שייכים עוד לשבת שעבר משא\"כ ביו\"ט ומ\"מ הגרע\"א מצדד שם דכל יום א' שאחר יו\"ט יכול להבדיל ע\"ש:","(יז) אלא כל יום ראשון - דלא ס\"ל הסברא הנ\"ל אך ביום הראשון הטעם הוא דהיום הולך אחר הלילה של מו\"ש:","(יח) אבל על הנר וכו' - דברכת על האור משום דבמו\"ש הוא זמן בריאתו ועל הבשמים נמי משום כדי להשיב נפש הכואבת ביציאת נשמה יתירה וכ\"ז לא שייך ממו\"ש ואילך [עו\"ש]:","(יט) כסברא הראשונה - ואתרוייהו יש אומרים קאי [א\"ר]:","(כ) ג' ימים וג' לילות - עיין באחרונים שכתבו דה\"ה אם מתענה ב' ימים וב' לילות ואפילו יום אחד ולילו אף דיכול לקיים מצות הבדלה בעצמו אחר תענית מ\"מ יותר טוב שישמע במו\"ש הבדלה מאחרים דקרובי אבדלתא לשבת עדיף טפי דאז הוא עיקר מצות הבדלה והא דנקט ג' ימים משום סיפא דבאין אחרים יכול להבדיל מבע\"י וזהו דוקא בג' ימים דיעבור הזמן ולא יוכל לקיים הבדלה כלל משא\"כ בשני ימים דלא יעבור הזמן טוב יותר שימתין ויבדיל לבסוף שני ימים משיבדיל מבע\"י:","(כא) ישמע הבדלה מאחרים - וה\"ה דיכול להבדיל בעצמו ויתן לאחרים לשתות וכדלעיל בסימן רע\"ב ס\"ט אך המ\"א שדי בזה שם נרגא דזה אינו מותר רק דוקא כשאחרים בעצמן אין יודעים לברך ולכן עצה זו עדיף טפי:","(כב) מבעוד יום - היינו אחר פלג המנחה ויתפלל ג\"כ מעריב מקודם וכדלעיל בסימן רצ\"ג ס\"ג ואפ\"ה מותר לאכול ולשתות אח\"כ ולא אמרינן דכיון דאבדיל כבר קיבל עליו את התענית ואסור בשתיה משום דעיקר התענית אינו מחמת חובה כת\"ב אלא מחמת נדרו ובנדרים הולכים אחר לשון בני אדם ובלשון ב\"א גם אחר שהבדיל מקרי יום והתענית אינו מתחיל אלא מתחלת הלילה ואפשר שגם בבין השמשות שהוא ספק לילה אבל לא מקודם וה\"ה כשמקבל עליו תענית של לילה ויום בשאר ימי החול ג\"כ אין חל עליו חובת תענית מבע\"י אף שכבר התפלל ערבית:","(כג) ולקבל אח\"כ - אין הכונה שיקבל תענית ממש דהא כבר קיבל עליו היום במנחה כדרך כל תענית שצריך קבלה במנחה שלפניו ואי מיירי שיש עליו נדר מכבר להתענות כל ג' ימים שאחר שבת ג\"כ א\"צ עתה קבלת תענית כלל אלא ר\"ל שיקבל אח\"כ בדעתו שיתחיל התענית מעתה ועיין בבה\"ל:","(כד) על שלחנו - לאו דוקא ולא בא למעט אלא חדר אחר דשם הוי ההבדלה מידי אחרינא אבל באותו חדר חשוב על שלחנו דהא בדעתם לשתות אח\"כ בסעודה שיאכלו שם אחר זה:","(כה) אא\"כ נטל ידיו - שנט\"י היא התחלת קביעות הסעודה ושייכא לסעודה והא דמותר להבדיל ולא חשיב הפסק בין נטילה להמוציא עיין בסימן קע\"ד במ\"א סק\"ו:","(כו) ואם הבדיל תחלה - הגה זו היא מסקנת דעת הי\"א דס\"ל דמה שהבדיל קודם הנטילה אע\"פ שהוא על שלחנו אינו שייך למה שישתה תוך המזון אח\"כ ומשו\"ה צריך לברך מחדש תוך הסעודה על היין וע\"כ חייב לברך ברכה אחרונה קודם הסעודה ולהלכה ודאי יש לפסוק ספק ברכות להקל ופטור מברכה אחרונה ובתוך הסעודה ג\"כ פטור לברך על היין כדעה הראשונה ועיין לעיל בסימן קע\"ד ס\"ד ובמש\"כ שם במ\"ב:","(כז) כשפוטר וכו' - היינו דאז בודאי אמרינן דשתיה חדא היא והבהמ\"ז פוטר גם לכוס הבדלה מברכה אחרונה ואפילו אם בירך בהמ\"ז בלא כוס הבהמ\"ז עצמו פוטרו אבל אם אין לו יין על תוך המזון וגם אין לו כוס לבהמ\"ז שיפטור גם אותו דרך אגב בברכה אחרונה שלו אז י\"א דאינו נפטר בבהמ\"ז וצריך לברך ב\"א על כוס הבדלה וזהו תמצית ביאור דברי השו\"ע:","(כח) וסבור שיביאו וכו' - דאל\"ה הלא מבואר ברצ\"ו ס\"ג די\"א דיאכל קודם הבדלה ואח\"כ יברך בהמ\"ז ויבדיל על כוס אחד ע\"ש ועוד דאל\"ה עדיף טפי לברך ברכה אחרונה תיכף אחר שתיית הכוס ולא להמתין לברך אותה אחר שיסעוד ויברך בהמ\"ז:","(כט) שצריך לברך - ואף דגבי כוס קידוש פסק השו\"ע לעיל בסימן רע\"ב ס\"י דא\"צ לברך ברכה אחרונה אחריו בכל גווני דבהמ\"ז פוטרתו קידוש שאני שהיא צורך סעודה דאין קידוש אלא במקום סעודה משא\"כ הבדלה. והנה הי\"א הזה הוא דעת הטור שחילק בסברא זו שכתבנו ועיין במ\"א שהוכיח דהרא\"ש לא ס\"ל לחלק בזה וכן בביאור הגר\"א דעתו כהמ\"א וע\"כ נראה שאם לא בירך קודם הסעודה לא יברך אח\"כ:","(ל) לסעוד תיכף - אבל אם אינו סועד תיכף א\"צ לכסותו דלא שייך קדימה בזה:","(לא) וצריך להקדימו - אף דבכאן אין להקדימו דאסור לאכול קודם הבדלה מ\"מ כיון שבעלמא הדין נותן להקדימו וא\"כ הוי ביזוי לפת שיקדים לו דבר אחר לכן יש לכסותו:","(לב) שום מלאכה - ואפילו חפצים האסורים מדברי סופרים [א\"ר]:","(לג) קודם שיבדיל - היינו אפילו משתחשך כיון שלא הבדיל עדיין חל במקצת קדושת שבת עליו ואסרו חז\"ל במלאכה:","(לד) אומר המבדיל - בלבוש איתא אומר ברוך המבדיל בין הקודש ובין החול ומ\"מ אינו נקרא זה ברכה כיון שאין אומר בה שם ומלכות ומה שדי בלשון זה לענין עשיית מלאכה שהוא להכירא בעלמא ללוות את המלך:","(לה) בין הקודש וכו' - וא\"צ לומר כל הלשון של הבדלה ומ\"מ לענין אכילה לא מהני עד שיבדיל הבדלה גמורה על הכוס וגם בתפלה:","(לו) בלא ברכה וכו' - וביו\"ט שחל במו\"ש ורוצה לעשות מלאכת אוכל נפש ולא הבדיל עדיין בתפלה אומר ברוך המבדיל בין קודש לקודש בלא שם מלכות ומותר במלאכה אבל לענין טעימה אסור אפילו הבדיל בתפלה שאמר ותודיענו עד שיקדש כדין:","(לז) שאינן מבדילין וכו' - היינו שרובן לא נהגו להתפלל במוצאי שבת:","(לח) אבל הדלקת הנר וכו' - הטעם כיון דמדאורייתא בלא הבדלה מותר במלאכה רק תקנת חכמים הוא שצריך להבדיל מקודם הקילו במלאכה שאין בה טורח:","(לט) ומזה נתפשט המנהג וכו' - עיין מ\"א שמפקפק מאד על מנהג זה וכן בב\"י דמנין לנו לחלק בין מלאכה למלאכה וגם רבינו ירוחם אפשר שלא כוון להקל בזה רק אחר שהבדיל בתפלה וע\"כ מסיק דיש לדרוש ברבים שילמדו בנותיהם לומר המבדיל בין קודש לחול קודם שיעשו שום מלאכה ומכש\"כ אותן שמבערות עצים ואש ומחממות מים דהוי מלאכה שיש בה טורח ולכו\"ע אסור וכ\"כ שארי אחרונים:","(מ) העיקר כסברא ראשונה - ובעל נפש יעשה כמ\"ש בדרכי משה בשם אור זרוע וכן איתא בזוהר (פ' במדבר) שלא להדליק נר עד אחר סדר קדושה אבל חזן הכנסת מותר להדליק נר אחר שהבדיל בתפלה או אמר ברוך המבדיל בין קודש לחול משום כבוד הצבור שיושבין בחושך וטלטול הנר שרי לכו\"ע [מ\"א] ולהביא יין ביו\"ט שני אחר שחשכה אף שלא התפלל עדיין וגם לא קידש אפ\"ה שרי דהא אין בזה משום מלאכה רק משום הכנה מיו\"ט לחבירו וכיון שנתקדש היום שרי. מהרי\"ל היה מקפל הטלית שלו בכל מוצאי שבת כדי להתעסק במצוה מיד: "]}],"300":[{"s":"<b>שיסדר שלחנו במו\"ש. ובו סעיף אחד:</b><br><i data-commentator=\"Turei Zahav\" data-order=\"1\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>לעולם יסדר אדם <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"1\"></i>שלחנו במוצאי שבת כדי ללות את השבת אפילו אינו צריך אלא לכזית:","m":["(א) יסדר אדם שלחנו וכו' - היינו לפרוס מפה על שלחנו דרך כבוד וכן שאר דברים הנהוגים אצלו בעריכת השלחן אבל אינו מחוייב לבשל תבשילין ולהכין יותר ממה שצריך לאכול. ומשמע בגמרא דיקבע סעודה זו על הפת לכתחלה כמו בשאר סעודות של שבת וגם משמע דטוב לכתחלה להדר אותה בבשר או בשאר תבשילין אם יש לו ואם אין לו או שחושש לאכילה גסה כגון בקיץ שמאחרין בזמננו לאכול הסעודה ג' סמוך לערב יקיימה במזונות או עכ\"פ בפירות:","(ב) כדי ללוות וכו' - דכשם שצריך לכבד השבת בכניסתה כן צריך לכבדה ביציאתה כשם שאדם מלוה את המלך בצאתו מן העיר ומטעם זה נראה שטוב להקדימה כדי שתהיה סמוכה ליציאת השבת ואם אינו תאב עדיין לאכול מהנכון עכ\"פ שלא יעסוק במלאכה בקבע עד שיקיים סעודה זו ועיין בשע\"ת דמשמע דאינו כדאי בכל גוונא לאחרה יותר מחצות. ואמרו הקדמונים דאבר אחד יש באדם ונסכוי שמו וזה האבר נשאר קיים בקבר עד עת התחיה ואפילו אחר שנרקבו בו כל העצמות וזה האבר אינו נהנה משום אכילה כ\"א מסעודת מלוה מלכה. ודע דמ\"מ סעודה זו אינה חובה עליו כמו הג' סעודות של שבת דשם אסמכוהו אקרא וזה רק מצוה בעלמא ונ\"מ היכי דא\"א לו לקיים כולם:","(ג) את השבת - ומטעם זה יש נוהגים להרבות נרות במו\"ש יותר מימי החול ונוהגים ג\"כ לומר פיוטים וזמירות אחר הבדלה [אחרונים]:"]}]};